-- Requiere: ejecutar antes 00_SETUP_COMPLETO.sql
-- ============================================

BEGIN;
SET search_path TO public;

-- Garantizar columnas fuente en pregunta
ALTER TABLE pregunta ADD COLUMN IF NOT EXISTS ubicacion_fuente TEXT;
ALTER TABLE pregunta ADD COLUMN IF NOT EXISTS codigo_fuente TEXT;

-- 1) Materias base (5 bloques para pruebas)
INSERT INTO materia (codigo, nombre, nombre_corto, descripcion, total_preguntas_banco, color_hex, icono, orden_visualizacion, categoria, nivel_dificultad_promedio, activo) VALUES
  ('SBM1','Bloque 1 - Constitucional y DDHH','Bloque 1','Preguntas 1-600 del banco suboficiales',600,'#2563EB','gavel',1,'Juridica','media',TRUE),
  ('SBM2','Bloque 2 - Regimen PNP','Bloque 2','Preguntas 601-1200 del banco suboficiales',600,'#0EA5E9','local_police',2,'Normativa','media',TRUE),
  ('SBM3','Bloque 3 - Administrativo','Bloque 3','Preguntas 1201-1800 del banco suboficiales',600,'#8B5CF6','description',3,'Procedimental','media',TRUE),
  ('SBM4','Bloque 4 - Penal y Procesal','Bloque 4','Preguntas 1801-2400 del banco suboficiales',600,'#F97316','balance',4,'Penal','alta',TRUE),
  ('SBM5','Bloque 5 - Operativo y Protocolos','Bloque 5','Preguntas 2401-3000 del banco suboficiales',600,'#10B981','shield',5,'Operativa','media',TRUE)
ON CONFLICT (codigo) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  nombre_corto = EXCLUDED.nombre_corto,
  descripcion = EXCLUDED.descripcion,
  total_preguntas_banco = EXCLUDED.total_preguntas_banco,
  activo = TRUE,
  actualizado_at = NOW();

-- 2) Banco suboficiales desde PDF
INSERT INTO banco_de_pregunta (nombre, version, descripcion, total_preguntas, fecha_publicacion, activo, es_oficial)
SELECT 'Banco Suboficiales 2025 Promo 2026 (PDF)', 'v1.0-pdf', 'Carga desde PDF proporcionado por el usuario', 3000, CURRENT_DATE, TRUE, TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf'
);

-- Preguntas 1 a 100
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1, 'SUB-0001', 'SBM1', 'TODA PERSONA TIENE DERECHO: A ELEGIR SU LUGAR DE RESIDENCIA, A TRANSITAR POR EL TERRITORIO NACIONAL Y A SALIR DE ÉL Y ENTRAR EN ÉL, SALVO LIMITACIONES POR:.', 'RAZONES DE SANIDAD O POR MANDATO JUDICIAL O POR APLICACIÓN DE LA LEY DE EXTRANJERÍA.', 'ART. 2. Num. 11', '180838'),
