    (15, 'SUB-0015', 'SBM1', 'NO PUEDEN PARTICIPAR EN ACTIVIDADES PARTIDARIAS O MANIFESTACIONES NI REALIZAR ACTOS DE PROSELITISMO, MIENTRAS NO HAYAN PASADO A LA SITUACIÓN DE RETIRO:.', 'LOS MIEMBROS DE LAS FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL.', 'ART. 34', '180852'),
    (16, 'SUB-0016', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA LIBERTAD Y A LA SEGURIDAD PERSONALES, EN CONSECUENCIA NADIE DEBE SER VÍCTIMA DE:.', 'VIOLENCIA MORAL, PSÍQUICA O FÍSICA, NI SOMETIDO A TORTURA O A TRATOS INHUMANOS O HUMILLANTES.', 'ART. 2. Num. 24. Literal H', '180853'),
