    (77, 'SUB-0077', 'SBM1', 'EL VOTO ES PERSONAL, IGUAL, LIBRE:.', 'SECRETO Y OBLIGATORIO.', 'ART. 31', '180914'),
    (78, 'SUB-0078', 'SBM1', 'LOS CIUDADANOS TIENEN EL DERECHO DE SER ELEGIDOS Y DE ELEGIR LIBREMENTE A SUS REPRESENTANTES, DE ACUERDO CON LAS CONDICIONES Y PROCEDIMIENTOS DETERMINADOS POR:.', 'LEY ORGÁNICA.', 'ART. 31', '180915'),
    (79, 'SUB-0079', 'SBM1', 'TODA PERSONA TIENE DERECHO A QUE LOS SERVICIOS INFORMÁTICOS, COMPUTARIZADOS O NO, PÚBLICOS O PRIVADOS:.', 'NO SUMINISTREN INFORMACIONES QUE AFECTEN LA INTIMIDAD PERSONAL Y FAMILIAR.', 'ART. 2. Num. 6', '180916'),
    (80, 'SUB-0080', 'SBM1', 'RESPECTO A LA LIBERTAD Y A LA SEGURIDAD PERSONALES, NADIE PUEDE SER VÍCTIMA DE VIOLENCIA MORAL, PSÍQUICA O FÍSICA:.', 'NI SOMETIDO A TORTURA O A TRATOS INHUMANOS O HUMILLANTES.', 'ART. 2. Num. 24. Literal H', '180917'),
    (81, 'SUB-0081', 'SBM1', 'ES ESTADO DE SITIO SE PRODUCE EN CASO DE :.', 'GUERRA EXTERIOR.', 'ART. 137, Num. 2', '180918'),
    (82, 'SUB-0082', 'SBM1', 'TODA PERSONA TIENE DERECHO A CONTRATAR CON FINES LÍCITOS, SIEMPRE QUE NO SE CONTRAVENGAN:.', 'LEYES DE ORDEN PÚBLICO.', 'ART. 2. INC.14', '180919'),
    (83, 'SUB-0083', 'SBM1', 'LAS ORGANIZACIONES POLITICAS COMO PARTIDOS,MOVIMIENTOS O ALIANZAS, SU INSCRIPCION EN EL REGISTRO CORRESPONDIENTE LES CONCEDE PERSONALIDAD:.', 'JURÍDICA', 'ART. 35', '180920'),
    (84, 'SUB-0084', 'SBM1', 'TODA PERSONA TIENEN DERECHO A: ELEGIR SU LUGAR DE RESIDENCIA, A TRANSITAR POR EL TERRITORIO NACIONAL Y A SALIR DE ÉL Y ENTRAR EN ÉL, SALVO LIMITACIONES POR RAZONES DE SANIDAD O POR MANDATO JUDICIAL O POR:.', 'APLICACIÓN DE LA LEY DE EXTRANJERÍA.', 'ART. 2. Num. 11', '180921'),
    (85, 'SUB-0085', 'SBM1', 'EN CASO DE DELITOS COMETIDOS CONTRA EL PATRIMONIO DEL ESTADO, EL PLAZO DE PRESCRIPCIÓN SE:.', 'DUPLICA', 'ART. 41', '180922'),
    (86, 'SUB-0086', 'SBM1', 'CON RELACIÓN A LOS INGRESOS QUE POR TODO CONCEPTO, PERCIBEN LOS ALTOS FUNCIONARIOS, Y OTROS SERVIDORES PÚBLICOS, ES OBLIGATORIA LA PUBLICACIÓN EN_____________________________:.', 'EL DIARIO OFICIAL.', 'ART. 40', '180923'),
    (87, 'SUB-0087', 'SBM1', 'LA LEY REGULA EL INGRESO A LA CARRERA_________________________, Y LOS DERECHOS, DEBERES Y RESPONSABILIDADES DE LOS SERVIDORES PÚBLICOS:.', 'ADMINISTRATIVA', 'ART. 40', '180924'),
    (88, 'SUB-0088', 'SBM1', 'LAS FUERZAS ARMADAS ESTÁN CONSTITUIDAS POR EL EJÉRCITO, LA MARINA DE GUERRA Y LA FUERZA AÉREA. TIENEN COMO FINALIDAD PRIMORDIAL:.', 'GARANTIZAR LA INDEPENDENCIA, LA SOBERANÍA Y LA INTEGRIDAD TERRITORIAL DE LA REPÚBLICA.', 'ART. 165', '180925'),
    (89, 'SUB-0089', 'SBM1', 'TODA PERSONA TIENE DERECHO A SOLICITAR SIN EXPRESIÓN DE CAUSA:.', 'LA INFORMACIÓN QUE REQUIERA.', 'ART. 2. Num. 5', '180926'),
    (90, 'SUB-0090', 'SBM1', '¿QUIÉN PROPICIA EL ACCESO A LA CULTURA Y FOMENTA SU DESARROLLO Y DIFUSIÓN?:.', 'ESTADO', 'ART. 2. Num. 8', '180927'),
    (91, 'SUB-0091', 'SBM1', 'SIEMPRE QUE TENGAN RESIDENCIA EN EL PERÚ, SON PERUANOS LOS QUE ADQUIEREN LA NACIONALIDAD POR NATURALIZACIÓN O POR:.', 'OPCIÓN', 'ART. 52', '180928'),
    (92, 'SUB-0092', 'SBM1', 'TODA PERSONA TIENE DERECHO: A ASOCIARSE Y A CONSTITUIR FUNDACIONES Y DIVERSAS FORMAS DE ORGANIZACIÓN JURÍDICA..', 'SIN FINES DE LUCRO, SIN AUTORIZACIÓN PREVIA Y CON ARREGLO A LA LEY.', 'ART. 2. Num. 13', '180929'),
    (93, 'SUB-0093', 'SBM1', 'ACCIÓN DE GARANTÍA CONSTITUCIONAL, QUE PROCEDE CONTRA CUALQUIER AUTORIDAD O FUNCIONARIO RENUENTE A ACATAR UNA NORMA LEGAL O UN ACTO ADMINISTRATIVO, SIN PERJUICIO DE LAS RESPONSABILIDADES DE LEY:.', 'LA ACCION DE CUMPLIMIENTO.', 'ART. 200. Num. 6', '180930'),
    (94, 'SUB-0094', 'SBM1', 'ESTÁ EXONERADO DEL PAGO DE GASTOS JUDICIALES:.', 'EL ESTADO.', 'ART. 47', '180931'),
    (95, 'SUB-0095', 'SBM1', 'LAS FUERZAS ARMADAS Y LA POLICÍA NACIONAL PARTICIPAN EN EL:.', 'DESARROLLO ECONÓMICO Y SOCIAL DEL PAÍS.', 'ART. 171', '180932'),
    (96, 'SUB-0096', 'SBM1', 'LA PRORROGA DEL ESTADO DE SITIO REQUIERE LA APROBACIÓN DEL:.', 'SENADO', 'ART. 137, Num. 2', '180933'),
    (97, 'SUB-0097', 'SBM1', 'PUEDE LEVANTARSE A PEDIDO DEL JUEZ:.', 'RESERVA TRIBUTARIA.', 'ART. 2. Num. 5', '180934'),
    (98, 'SUB-0098', 'SBM1', 'CONFORME A LEY, LA DEFENSA DE LOS INTERESES DEL ESTADO ESTÁ A CARGO DE LOS:.', 'PROCURADORES PÚBLICOS.', 'ART. 47', '180935'),
    (99, 'SUB-0099', 'SBM1', 'LOS LIBROS, COMPROBANTES Y DOCUMENTOS CONTABLES Y ADMINISTRATIVOS ESTÁN SUJETOS A:.', 'INSPECCIÓN O FISCALIZACIÓN DE LA AUTORIDAD COMPETENTE, DE CONFORMIDAD CON LA LEY.', 'ART. 2. Num. 10', '180936'),
    (100, 'SUB-0100', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA VIDA, A SU IDENTIDAD, A SU INTEGRIDAD:.', 'MORAL, PSÍQUICA Y FÍSICA.', 'ART. 2. Num. 1', '180937')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

