INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 101 a 200
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (101, 'SUB-0101', 'SBM1', 'ES DERECHO Y DEBER DE LOS VECINOS PARTICIPAR EN EL GOBIERNO MUNICIPAL DE SU:.', 'JURISDICCIÓN', 'ART. 31', '180938'),
    (102, 'SUB-0102', 'SBM1', 'SI SE CONSIDERA QUE HA SIDO SOLICITADA CON EL FIN DE PERSEGUIR O CASTIGAR POR MOTIVO DE RELIGIÓN, NACIONALIDAD, OPINIÓN O RAZA; NO SE CONCEDE:.', 'EXTRADICIÓN', 'ART. 37', '180939'),
    (103, 'SUB-0103', 'SBM1', 'TODA PERSONA TIENE DERECHO A SOLICITAR SIN EXPRESION DE CAUSA LA INFORMACION QUE REQUIERA Y A RECIBIRLA DE CUALQUIER ENTIDAD PÚBLICA CON:', 'EL COSTO.', 'ART. 2. Num. 5. Párrafo 1', '180940'),
    (104, 'SUB-0104', 'SBM1', 'TODA PERSONA TIENE DERECHO: A LA LIBERTAD DE CREACIÓN INTELECTUAL, ARTÍSTICA, TÉCNICA Y CIENTÍFICA, ASÍ COMO:.', 'A LA PROPIEDAD SOBRE DICHAS CREACIONES Y A SU PRODUCTO.', 'ART. 2. Num. 8', '180941'),
    (105, 'SUB-0105', 'SBM1', 'ES ESTADO DE SITIO SE PRODUCE EN CASO DE :.', 'INVASIÓN', 'ART. 137, Num. 2', '180942'),
    (106, 'SUB-0106', 'SBM1', 'PUEDE LEVANTARSE A PEDIDO DEL JUEZ:.', 'SECRETO BANCARIO.', 'ART. 2. Num. 5', '180943'),
    (107, 'SUB-0107', 'SBM1', 'LA LEY ESTABLECE LAS EQUIVALENCIAS CORRESPONDIENTES AL PERSONAL MILITAR O POLICIAL DE CARRERA QUE:', 'NO TIENE GRADO O JERARQUÍA DE OFICIAL.', 'ART. 174', '180944'),
    (108, 'SUB-0108', 'SBM1', 'TODA PERSONA TIENE DERECHO A CONTRATAR CON FINES LÍCITOS, SIEMPRE QUE NO SE CONTRAVENGAN LEYES:.', 'DE ORDEN PÚBLICO.', 'ART. 2. Num. 14', '180945'),
    (109, 'SUB-0109', 'SBM1', 'EN EL ESTADO DE EMERGENCIA PUEDEN RESTRINGIRSE O SUSPENDERSE EL EJERCICIO DE LOS DERECHOS CONSTITUCIONALES RELATIVOS :.', 'A LA LIBERTAD Y SEGURIDAD PERSONALES.', 'ART. 137, Num. 1', '180946'),
    (110, 'SUB-0110', 'SBM1', 'NO SE SUSPENDE DURANTE LA VIGENCIA DE LOS REGÍMENES DE EXCEPCIÓN A QUE SE REFIERE EL ARTÍCULO 137º DE LA CONSTITUCIÓN:.', 'EL EJERCICIO DE LAS ACCIONES DE HÁBEAS CORPUS Y DE AMPARO.', 'ART. 200', '180947'),
    (111, 'SUB-0111', 'SBM1', 'EL SECRETO BANCARIO Y LA RESERVA TRIBUTARIA PUEDEN LEVANTARSE A PEDIDO:', 'DEL FISCAL DE LA NACIÓN.', 'ART. 2. Num. 5', '180948'),
    (112, 'SUB-0112', 'SBM1', 'TODA PERSONA TIENE DERECHO:.', 'AL HONOR Y A LA BUENA REPUTACION.', 'ART. 2. Num. 7', '180949'),
    (113, 'SUB-0113', 'SBM1', 'DEL PAGO DE GASTOS JUDICIALES, EL ESTADO ESTÁ:.', 'EXONERADO', 'ART. 47', '180950'),
    (114, 'SUB-0114', 'SBM1', 'GARANTIZA LA SEGURIDAD DE LA NACIÓN MEDIANTE EL SISTEMA DE DEFENSA NACIONAL:.', 'EL ESTADO.', 'ART. 163', '180951'),
    (115, 'SUB-0115', 'SBM1', 'ES OBLIGATORIA LA PUBLICACIÓN PERIÓDICA EN EL DIARIO OFICIAL DE LOS INGRESOS QUE, POR TODO CONCEPTO, PERCIBEN LOS ALTOS FUNCIONARIOS, Y OTROS SERVIDORES PÚBLICOS QUE SEÑALA LA LEY, EN RAZÓN DE SUS:.', 'CARGOS', 'ART. 40', '180952'),
    (116, 'SUB-0116', 'SBM1', 'TODA PERSONA TIENE DERECHO:.', 'A LA IGUALDAD ANTE LA LEY.', 'ART. 2. Num. 2', '180953'),
    (117, 'SUB-0117', 'SBM1', 'LAS FUERZAS ARMADAS Y LA POLICÍA NACIONAL NO SON DELIBERANTES. ESTÁN SUBORDINADAS:.', 'AL PODER CONSTITUCIONAL.', 'ART. 169', '180954'),
    (118, 'SUB-0118', 'SBM1', 'DESPUÉS DE LOS SETENTA AÑOS EL VOTO ES:.', 'FACULTATIVO', 'ART. 31', '180955'),
    (119, 'SUB-0119', 'SBM1', 'EL ESTADO RECONOCE EL ASILO:.', 'POLITICO', 'ART. 36', '180956'),
    (120, 'SUB-0120', 'SBM1', 'LOS MIEMBROS DE LAS FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL, NO PUEDEN POSTULAR A CARGOS DE ELECCIÓN:.', 'POPULAR', 'ART. 34', '180957'),
    (121, 'SUB-0121', 'SBM1', 'ES CONSIDERADA UNA FINALIDAD FUNDAMENTAL DE LA POLICÍA NACIONAL:.', 'PRESTA PROTECCIÓN Y AYUDA A LAS PERSONAS Y A LA COMUNIDAD.', 'ART. 166', '180958'),
    (122, 'SUB-0122', 'SBM1', 'EN CASO DE FLAGRANTE DELITO, LA DETENCIÓN NO DURARÁ MAS DEL TIEMPO ESTRICTAMENTE NECESARIO PARA LA REALIZACIÓN DE LAS INVESTIGACIONES Y EN TODO CASO, EL DETENIDO DEBE SER PUESTO A DISPOSICIÓN DEL JUZGADO CORRESPONDIENTE:.', 'DENTRO DEL PLAZO MAXIMO DE CUARENTA Y OCHO HORAS O EN EL TÉRMINO DE LA DISTANCIA.', 'ART. 2. Num. 24. Literal F', '180959'),
    (123, 'SUB-0123', 'SBM1', 'PARA LA FUNCIÓN PÚBLICA, LA LEY ESTABLECE LA RESPONSABILIDAD DE LOS FUNCIONARIOS Y SERVIDORES PÚBLICOS, ASÍ COMO EL PLAZO DE SU:.', 'INHABILITACIÓN', 'ART. 41', '180960'),
    (124, 'SUB-0124', 'SBM1', 'SE RECONOCEN LOS DERECHOS DE SINDICACIÓN Y HUELGA DE LOS:.', 'SERVIDORES PÚBLICOS.', 'ART. 42', '180961'),
    (125, 'SUB-0125', 'SBM1', 'LOS EXTRANJEROS EN EL PERÚ, CUANDO SON CITADOS POR CUALQUIER AUTORIDAD, TIENEN DERECHO A:.', 'USAR SU PROPIO IDIOMA ANTE CUALQUIER AUTORIDAD MEDIANTE UN INTÉRPRETE.', 'ART. 2. Num. 19', '180962'),
    (126, 'SUB-0126', 'SBM1', 'EN SU DOMINIO MARÍTIMO, EL ESTADO EJERCE:.', 'SOBERANÍA Y JURISDICCIÓN.', 'ART. 54', '180963'),
    (127, 'SUB-0127', 'SBM1', 'A LOS SERVIDORES PÚBLICOS, SE LE RECONOCEN LOS DERECHOS DE:.', 'SINDICACIÓN Y HUELGA.', 'ART. 42 Constitución Política del Perú', '180964'),
    (128, 'SUB-0128', 'SBM1', 'CUANDO SE PRESUME ENRIQUECIMIENTO ILÍCITO EL FISCAL DE LA NACIÓN, POR DENUNCIA DE TERCEROS O DE OFICIO, FORMULARA CARGOS ANTE EL:.', 'PODER JUDICIAL.', 'ART. 41', '180965'),
    (129, 'SUB-0129', 'SBM1', 'EL ESTADO ESTÁ EXONERADO DEL PAGO DE:.', 'GASTOS JUDICIALES.', 'ART. 47', '180966'),
    (130, 'SUB-0130', 'SBM1', 'EN CASO DE DELITO DE FUNCIÓN, LOS MIEMBROS DE LAS FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL ESTÁN SOMETIDOS AL FUERO RESPECTIVO Y AL:.', 'CÓDIGO DE JUSTICIA MILITAR.', 'ART. 173', '180967'),
    (131, 'SUB-0131', 'SBM1', 'TODOS LOS PERUANOS TIENEN EL DEBER DE:.', 'HONRAR AL PERÚ.', 'ART. 38', '180968'),
    (132, 'SUB-0132', 'SBM1', 'ASIGNA LOS FONDOS DESTINADOS A SATISFACER LOS REQUERIMIENTOS LOGÍSTICOS DE LAS FUERZAS ARMADAS Y LA POLICÍA NACIONAL', 'LA LEY.', 'ART. 170', '180969'),
    (133, 'SUB-0133', 'SBM1', 'NO PUEDEN POSTULAR A CARGOS DE ELECCIÓN POPULAR, LOS MIEMBROS DE LAS:.', 'FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL EN SITUACIÓN DE ACTIVIDAD.', 'ART. 34', '180970'),
    (134, 'SUB-0134', 'SBM1', 'TODA PERSONA TIENE DERECHO A SOLICITAR Y RECIBIR INFORMACIÓN DE CUALQUIER ENTIDAD PÚBLICA, EN EL PLAZO:.', 'LEGAL', 'ART. 2. Num. 5. Párrafo 1', '180971'),
    (135, 'SUB-0135', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA LIBERTAD Y A LA SEGURIDAD PERSONALES, EN CONSECUENCIA NO SE PERMITE FORMA ALGUNA DE RESTRICCIÓN DE LA LIBERTAD PERSONAL, SALVO EN:.', 'LOS CASOS PREVISTOS POR LA LEY.', 'ART. 2. Num. 24. Literal B', '180972'),
    (136, 'SUB-0136', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA LIBERTAD Y A LA SEGURIDAD PERSONALES. EN CONSECUENCIA:.', 'TODA PERSONA ES CONSIDERADA INOCENTE MIENTRAS NO SE HAYA DECLARADO JUDICIALMENTE SU RESPONSABILIDAD.', 'ART. 2. Num. 24. Literal E', '180973'),
    (137, 'SUB-0137', 'SBM1', 'SON CIUDADANOS LOS PERUANOS MAYORES DE:.', 'DIECIOCHO AÑOS.', 'ART. 30', '180974'),
    (138, 'SUB-0138', 'SBM1', 'PUEDEN SER SOMETIDAS A REFERÉNDUM:.', 'LA REFORMA TOTAL O PARCIAL DE LA CONSTITUCIÓN.', 'ART. 32', '180975'),
    (139, 'SUB-0139', 'SBM1', 'ES DEBER DEL ESTADO ESTABLECER Y EJECUTAR LA POLÍTICA DE:.', 'FRONTERAS', 'ART. 44', '180976'),
    (140, 'SUB-0140', 'SBM1', 'LA EXTRADICIÓN SÓLO SE CONCEDE POR EL PODER EJECUTIVO PREVIO INFORME DE LA:.', 'CORTE SUPREMA.', 'ART. 37', '180977'),
    (141, 'SUB-0141', 'SBM1', 'UNO DE LOS DEBERES PRIMORDIALES DEL ESTADO ES:.', 'GARANTIZAR LA PLENA VIGENCIA DE LOS DERECHOS HUMANOS.', 'ART. 44', '180978'),
    (142, 'SUB-0142', 'SBM1', 'ES ESTADO DE EMERGENCIA SE PRODUCE EN CASO DE :.', 'PERTURBACIÓN DE LA PAZ O DEL ORDEN INTERNO.', 'ART. 137, Num. 1', '180979'),
    (143, 'SUB-0143', 'SBM1', 'REGULADOS POR LEY, LOS MIEMBROS DE LAS FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL TIENEN DERECHO A LA:.', 'PARTICIPACIÓN CIUDADANA.', 'ART. 34', '180980'),
    (144, 'SUB-0144', 'SBM1', 'PARTICIPAR EN EL GOBIERNO MUNICIPAL DE SU JURISDICCIÓN, ES DERECHO Y DEBER DE LOS:.', 'VECINOS', 'ART. 31', '180981'),
    (145, 'SUB-0145', 'SBM1', 'EL DETENIDO DEBE SER PUESTO A DISPOSICIÓN DEL JUZGADO CORRESPONDIENTE, DENTRO DEL PLAZO MÁXIMO DE CUARENTA Y OCHO HORAS O EN EL TÉRMINO DE LA DISTANCIA:.', 'ESTOS PLAZOS NO SE APLICAN A LOS CASOS DE TERRORISMO, ESPIONAJE, TRÁFICO ILÍCITO DE DROGAS Y A LOS DELITOS COMETIDOS POR ORGANIZACIONES CRIMINALES.', 'ART. 2. Num. 24. Literal F', '180982'),
    (146, 'SUB-0146', 'SBM1', 'ES ESENCIAL PARA LA VIGENCIA DE TODA NORMA DEL ESTADO:.', 'LA PUBLICIDAD.', 'ART. 51', '180983'),
    (147, 'SUB-0147', 'SBM1', 'SU GOBIERNO DEL PERÚ ES UNITARIO, REPRESENTATIVO Y:.', 'DESCENTRALIZADO', 'ART. 43', '180984'),
    (148, 'SUB-0148', 'SBM1', 'NADIE PUEDE SER DESPOJADO DE ELLA, TAMPOCO PUEDE SER PRIVADO DEL DERECHO DE OBTENER O DE RENOVAR SU PASAPORTE DENTRO O FUERA DEL TERRITORIO DE LA REPÚBLICA.CORRESPONDE AL:.', 'DERECHO A SU NACIONALIDAD.', 'ART. 2. Num. 21', '180985'),
    (149, 'SUB-0149', 'SBM1', 'EJERCICIO DEL PODER DEL ESTADO.-NINGUNA PERSONA, ORGANIZACIÓN, FUERZA ARMADA, POLICÍA NACIONAL O SECTOR DE LA POBLACIÓN PUEDE ARROGARSE EL EJERCICIO DE ESE PODER. HACERLO CONSTITUYE SEDICIÓN O.', 'REBELIÓN', 'ART. 45', '180986'),
    (150, 'SUB-0150', 'SBM1', 'PUEDE LEVANTARSE A PEDIDO DEL FISCAL DE LA NACIÓN Y CONFORME A LEY:.', 'RESERVA TRIBUTARIA.', 'ART. 2. Num. 5', '180987'),
    (151, 'SUB-0151', 'SBM1', 'QUEDAN EXCLUIDOS DE LA EXTRADICIÓN LOS PERSEGUIDOS POR DELITOS:.', 'POLÍTICOS O POR HECHOS CONEXOS CON ELLOS.', 'ART. 37', '180988'),
    (152, 'SUB-0152', 'SBM1', 'NO PUEDEN SOMETERSE A REFERÉNDUM LOS TRATADOS:. Constitución Política del Perú', 'INTERNACIONALES EN VIGOR.', 'ART. 32', '180989'),
    (153, 'SUB-0153', 'SBM1', 'ES UNA FINALIDAD FUNDAMENTAL DE LA POLICÍA NACIONAL:.', 'VIGILA Y CONTROLA LAS FRONTERAS.', 'ART. 166', '180990'),
    (154, 'SUB-0154', 'SBM1', 'LOS FUNCIONARIOS Y SERVIDORES PÚBLICOS QUE SEÑALA LA LEY O QUE ADMINISTRAN O MANEJAN FONDOS DEL ESTADO O DE ORGANISMOS SOSTENIDOS POR ÉSTE DEBEN HACER DECLARACIÓN JURADA DE:.', 'BIENES Y RENTAS.', 'ART. 41', '180991'),
    (155, 'SUB-0155', 'SBM1', 'PROCEDE CONTRA EL HECHO U OMISIÓN POR PARTE DE CUALQUIER AUTORIDAD, FUNCIONARIO O PERSONA, QUE VULNERA O AMENAZA LOS DERECHOS A QUE SE REFIERE EL ARTÍCULO 2º, INCISOS 5 Y 6 DE LA CONSTITUCIÓN:.', 'HÁBEAS DATA.', 'ART. 200. Num. 3', '180992'),
    (156, 'SUB-0156', 'SBM1', 'NADIE DEBE OBEDIENCIA A UN GOBIERNO:.', 'USURPADOR', 'ART. 46', '180993'),
    (157, 'SUB-0157', 'SBM1', 'TIENEN DERECHO AL VOTO LOS CIUDADANOS EN GOCE DE SU CAPACIDAD CIVIL. PARA EL EJERCICIO DE ESTE DERECHO SE REQUIERE ESTAR:.', 'INSCRITO EN EL REGISTRO CORRESPONDIENTE.', 'ART. 31', '180994'),
    (158, 'SUB-0158', 'SBM1', 'DE LOS VECINOS DE PARTICIPAR EN EL GOBIERNO MUNICIPAL DE SU JURISDICCIÓN, ES:. Constitución Política del Perú', 'DERECHO Y DEBER.', 'ART. 31', '180995'),
    (159, 'SUB-0159', 'SBM1', 'PREVIO INFORME DE LA CORTE SUPREMA, EN CUMPLIMIENTO DE LA LEY Y DE LOS TRATADOS, Y SEGÚN EL PRINCIPIO DE RECIPROCIDAD, LA EXTRADICIÓN SÓLO SE CONCEDE POR EL PODER:.', 'EJECUTIVO', 'ART. 37', '180996'),
    (160, 'SUB-0160', 'SBM1', 'LOS GRADOS Y HONORES, LAS REMUNERACIONES Y LAS PENSIONES INHERENTES A LA JERARQUÍA DE OFICIALES DE LAS FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL SON EQUIVALENTES, SÓLO PUEDEN RETIRARSE A SUS TITULARES POR:.', 'SENTENCIA JUDICIAL.', 'ART. 174', '180997'),
    (161, 'SUB-0161', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA LIBERTAD Y A LA SEGURIDAD PERSONALES, EN CONSECUENCIA:.', 'NADIE PUEDE SER DETENIDO SINO POR MANDAMIENTO ESCRITO Y MOTIVADO DEL JUEZ O POR LAS AUTORIDADES POLICIALES EN CASO DE FLAGRANTE DELITO.', 'ART. 2. Num. 24. Literal F', '180998'),
    (162, 'SUB-0162', 'SBM1', 'LA LEY REGULA LAS FORMAS EN QUE SE ADQUIERE O RECUPERA:.', 'LA NACIONALIDAD.', 'ART. 53', '180999'),
    (163, 'SUB-0163', 'SBM1', 'DURANTE LOS PROCESOS ELECTORALES Y DE PARTICIPACIÓN CIUDADANA LA LEY ESTABLECE LOS MECANISMOS PARA GARANTIZAR LA :.', 'NEUTRALIDAD ESTATAL. Constitución Política del Perú', 'ART. 31', '181000'),
    (164, 'SUB-0164', 'SBM1', 'ES DEBER PRIMORDIAL DEL ESTADO: PROMOVER EL BIENESTAR GENERAL QUE SE FUNDAMENTA EN LA JUSTICIA Y EL DESARROLLO INTEGRAL Y EQUILIBRADO DE LA:.', 'NACIÓN', 'ART. 44', '181001'),
    (165, 'SUB-0165', 'SBM1', 'LA POLICÍA NACIONAL TIENE POR FINALIDAD FUNDAMENTAL VIGILAR Y CONTROLAR:.', 'LAS FRONTERAS.', 'ART. 166', '181002'),
    (166, 'SUB-0166', 'SBM1', 'LA LEY REGULA EL INGRESO A LA CARRERA ADMINISTRATIVA, Y LOS DERECHOS, DEBERES Y RESPONSABILIDADES DE LOS SERVIDORES PÚBLICOS. NO ESTÁN COMPRENDIDOS EN DICHA CARRERA LOS FUNCIONARIOS QUE DESEMPEÑAN CARGOS:.', 'POLÍTICOS O DE CONFIANZA.', 'ART. 40', '181003'),
    (167, 'SUB-0167', 'SBM1', 'EL BANCO CENTRAL DE RESERVA ES GOBERNADO POR UN DIRECTORIO DE', 'SIETE MIEMBROS', 'ART: 86', '181004'),
    (168, 'SUB-0168', 'SBM1', 'EN CUANTO A LOS DERECHOS FUNDAMENTALES DE LA PERSONA:', 'NADIE DEBE SER DISCRIMINADO POR MOTIVO DE CUALQUIER OTRA ÍNDOLE', 'ART. 2. Num. 2', '181005'),
    (169, 'SUB-0169', 'SBM1', 'UNO DE LOS DEBERES PRIMORDIALES DEL ESTADO ES:', 'GARANTIZAR LA PLENA VIGENCIA DE LOS DERECHOS HUMANOS', 'ART. 44', '181006'),
    (170, 'SUB-0170', 'SBM1', 'EL PODER DEL ESTADO EMANA DEL:', 'PUEBLO', 'ART. 45', '181007'),
    (171, 'SUB-0171', 'SBM1', 'TODA PERSONA TIENE DERECHO AL SECRETO BANCARIO Y TRIBUTARIO. SU LEVANTAMIENTO PUEDE EFECTUARSE A PEDIDO:', 'DE UNA COMISIÓN INVESTIGADORA DE LA CÁMARA DE DIPUTADOS CON ARREGLO A LEY.', 'ART. 2. Num. 5', '181008'),
    (172, 'SUB-0172', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA LIBERTAD DE CONCIENCIA Y RELIGIÓN, EN FORMA INDIVIDUAL Y ASOCIADA. NO HAY PERSECUCIÓN POR RAZÓN DE:', 'IDEAS O CREENCIAS', 'ART. 2. Num. 3', '181009'),
    (173, 'SUB-0173', 'SBM1', 'LA COMUNIDAD Y EL ESTADO PROTEGEN ESPECIALMENTE AL:', 'A LA MADRE', 'ART. 4', '181010'),
    (174, 'SUB-0174', 'SBM1', 'LA UNIÓN ESTABLE DE UN VARON Y UNA MUJER, LIBRES DE IMPEDIMENTO MATRIMONIAL, QUE FORMAN UN HOGAR DE HECHO, DA LUGAR A UNA COMUNIDAD DE BIENES SUJETA AL REGIMEN DE LA:', 'SOCIEDAD DE GANANCIALES', 'ART. 5', '181011'),
    (175, 'SUB-0175', 'SBM1', 'LA POLÍTICA NACIONAL DE POBLACIÓN TIENE COMO OBJETIVO DIFUNDIR Y PROMOVER:', 'LA PATERNIDAD Y MATERNIDAD RESPONSABLE', 'ART. 6. Párrafo 1', '181012'),
    (176, 'SUB-0176', 'SBM1', 'ES DEBER Y DERECHO DE LOS PADRES ALIMENTAR, EDUCAR Y DAR: Constitución Política del Perú', 'SEGURIDAD A SUS HIJOS', 'ART. 6. Párrafo 4', '181013'),
    (177, 'SUB-0177', 'SBM1', 'TODOS LOS HIJOS TIENEN IGUALES DERECHOS Y DEBERES. ESTA PROHIBIDA TODA MENCIÓN SOBRE EL ESTADO CIVIL DE LOS PADRES Y SOBRE LA NATURALEZA DE LA FILIACIÓN EN LOS REGISTROS:', 'CIVILES', 'ART. 6. Párrafo 4', '181014'),
    (178, 'SUB-0178', 'SBM1', 'TODOS TIENEN DERECHO A LA PROTECCIÓN DE SU SALUD, LA DEL MEDIO FAMILIAR Y LA DE LA:', 'COMUNIDAD', 'ART. 7', '181015'),
    (179, 'SUB-0179', 'SBM1', 'LA PERSONA INCAPACITADA PARA VALER POR SÍ MISMA A CAUSA DE UNA DEFICIENCIA FÍSICA O MENTAL TIENE DERECHO AL RESPETO DE:', 'SU DIGNIDAD', 'ART. 7', '181016'),
    (180, 'SUB-0180', 'SBM1', 'EL ESTADO RECONOCE EL DERECHO DE TODA PERSONA A ACCEDER DE FORMA PROGRESIVA Y UNIVERSAL A:', 'AGUA POTABLE', 'ART. 7-A', '181017'),
    (181, 'SUB-0181', 'SBM1', 'EL ESTADO PROMUEVE EL MANEJO SOSTENIBLE DEL AGUA. SU DOMINIO ES INALIENABLE E:', 'IMPRESCRIPTIBLE', 'ART. 7-A. Párrafo 2', '181018'),
    (182, 'SUB-0182', 'SBM1', 'POLÍTICA NACIONAL DE SALUD. EL PODER EJECUTIVO NORMA Y SUPERVISA SU APLICACIÓN. ES RESPONSABLE DE DISEÑARLA Y CONDUCIRLA EN FORMA PLURAL Y:', 'DESCENTRALIZADORA', 'ART. 9', '181019'),
    (183, 'SUB-0183', 'SBM1', 'DERECHO A LA SEGURIDAD SOCIAL: EL ESTADO RECONOCE EL DERECHO UNIVERSAL Y PROGRESIVO A TODA PERSONA A LA:', 'SEGURIDAD SOCIAL', 'ART. 10', '181020'),
    (184, 'SUB-0184', 'SBM1', 'LOS FONDOS Y LAS RESERVAS DE LA SEGURIDAD SOCIAL SON:', 'INTANGIBLES', 'ART. 12', '181021'),
    (185, 'SUB-0185', 'SBM1', 'LA EDUCACIÓN PROMUEVE EL CONOCIMIENTO, PREPARA PARA LA VIDA Y EL TRABAJO Y FOMENTA:', 'LA SOLIDARIDAD', 'ART. 14', '181022'),
    (186, 'SUB-0186', 'SBM1', 'EDUCACIÓN PARA LA VIDA Y EL TRABAJO: ES DEBER DEL ESTADO EN EL PAÍS PROMOVER EL DESARROLLO CIENTÍFICO Y:', 'TECNOLÓGICO', 'ART. 14. Párrafo 2', '181023'),
    (187, 'SUB-0187', 'SBM1', 'SON OBLIGATORIOS EN TODO EL PROCESO EDUCATIVO, LA FORMACIÓN ÉTICA Y CÍVICA Y LA ENSEÑANZA DE:', 'LA CONSTITUCIÓN Y DERECHOS HUMANOS', 'ART. 14. Párrafo 3', '181024'),
    (188, 'SUB-0188', 'SBM1', 'LA EDUCACIÓN PARA LA VIDA Y EL TRABAJO: LOS MEDIOS DE COMUNICACIÓN SOCIAL DEBEN COLABORAR CON EL ESTADO EN LA EDUCACIÓN Y EN LA FORMACIÓN:', 'MORAL Y CULTURAL', 'ART. 14. Párrafo 5', '181025'),
    (189, 'SUB-0189', 'SBM1', 'EDUCACIÓN PARA LA VIDA Y EL TRABAJO. EL ESTADO GARANTIZA A TRAVÉS DE LA INVERSIÓN PÚBLICA O PRIVADA, EN TODO EL TERRITORIO NACIONAL EL ACCESO A:', 'INTERNET LIBRE', 'ART. 14-A', '181026'),
    (190, 'SUB-0190', 'SBM1', 'EL PROFESORADO EN LA ENSEÑANZA OFICIAL ES CARRERA PÚBLICA. ESTABLECE LOS REQUISITOS PARA DESEMPEÑARSE COMO DIRECTOR O PROFESOR DE UN CENTRO EDUCATIVO.', 'LA LEY', 'ART. 15', '181027'),
    (191, 'SUB-0191', 'SBM1', 'PROFESORADO, CARRERA PÚBLICA: EL ESTADO Y LA SOCIEDAD PROCURAN SU EVALUACIÓN, CAPACITACIÓN, PROFESIONALIZACIÓN Y:', 'PROMOCIÓN PERMANENTES', 'ART. 15. Párrafo 1', '181028'),
    (192, 'SUB-0192', 'SBM1', 'PROFESORADO, CARRERA PÚBLICA: TODA PERSONA NATURAL O JURÍDICA TIENE EL DERECHO DE PROMOVER Y CONDUCIR:', 'INSTITUCIONES EDUCATIVAS', 'ART. 15. Párrafo 3', '181029'),
    (193, 'SUB-0193', 'SBM1', 'DESCENTRALIZACIÓN DEL SISTEMA EDUCATIVA: TANTO EL SISTEMA COMO EL RÉGIMEN EDUCATIVO SON:', 'DESCENTRALIZADOS', 'ART. 16', '181030'),
    (194, 'SUB-0194', 'SBM1', 'DESCENTRALIZACIÓN DEL SISTEMA EDUCATIVO: EL ESTADO SUPERVISA SU CUMPLIMIENTO Y:', 'LA CALIDAD DE LA EDUCACIÓN', 'ART. 16', '181031'),
    (195, 'SUB-0195', 'SBM1', 'DESCENTRALIZACIÓN DEL SISTEMA EDUCATIVO: ES DEBER DEL ESTADO ASEGURAR QUE NADIE SE VEA IMPEDIDO DE RECIBIR EDUCACIÓN ADECUADA POR RAZÓN DE SU SITUACIÓN:', 'ECONÓMICA', 'ART. 16. Párrafo 4', '181032'),
    (196, 'SUB-0196', 'SBM1', 'DESCENTRALIZACIÓN DEL SISTEMA EDUCATIVO: ES DEBER DEL ESTADO ASEGURAR QUE NADIE SE VEA IMPEDIDO DE RECIBIR EDUCACIÓN ADECUADA POR RAZÓN DE:', 'LIMITACIONES MENTALES', 'ART. 16. Párrafo 4', '181033'),
    (197, 'SUB-0197', 'SBM1', 'DESCENTRALIZACIÓN DEL SISTEMA EDUCATIVO: ES DEBER DEL ESTADO ASEGURAR QUE NADIE SE VEA IMPEDIDO DE RECIBIR EDUCACIÓN ADECUADA POR RAZÓN DE:', 'LIMITACIONES FÍSICAS', 'ART. 16. Párrafo 4', '181034'),
    (198, 'SUB-0198', 'SBM1', 'DESCENTRALIZACIÓN DEL SISTEMA EDUCATIVO: LA EDUCACIÓN ES UN DERECHO HUMANO FUNDAMENTAL QUE GARANTIZA EL DESARROLLO DE LA PERSONA Y LA SOCIEDAD, POR LO QUE EL ESTADO INVIERTE ANUALMENTE NO MENOS DEL:', '6% DEL PBI', 'ART. 16. Párrafo 5', '181035'),
    (199, 'SUB-0199', 'SBM1', 'OBLIGATORIEDAD DE LA EDUCACIÓN INICIAL, PRIMARIA Y SECUNDARIA. LA LEY FIJA EL MODO DE SUBVENCIONAR LA EDUCACIÓN PRIVADA EN CUALQUIERA DE SUS MODALIDADES INCLUYENDO LA:', 'COMUNAL Y COOPERATIVA', 'ART. 17. Párrafo 2', '181036'),
    (200, 'SUB-0200', 'SBM1', 'OBLIGATORIEDAD DE LA EDUCACIÓN: EL ESTADO GARANTIZA LA ERRADICACIÓN:', 'DEL ANALFABETISMO', 'ART. 17. Párrafo 4', '181037')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

