INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 201 a 300
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (201, 'SUB-0201', 'SBM1', 'TODA PERSONA TIENE DEBERES RESPECTO A LA COMUNIDAD, PUESTO QUE SÓLO EN ELLA PUEDE DESARROLLAR LIBRE Y PLENAMENTE SU:.', 'PERSONALIDAD.', 'ART. 29. Num. 1', '181052'),
    (202, 'SUB-0202', 'SBM1', 'TODO INDIVIDUO TIENE DERECHO A RECIBIR INFORMACIONES Y OPINIONES, Y EL DE DIFUNDIRLAS, SIN LIMITACIÓN DE FRONTERAS, UTILIZANDO:.', 'CUALQUIER MEDIO DE EXPRESIÓN.', 'ART. 19', '181053'),
    (203, 'SUB-0203', 'SBM1', 'LA DECLARACIÓN UNIVERSAL DE LOS DERECHOS HUMANOS, INDICA QUE A NADIE SE LE PRIVARA ARBITRARIAMENTE DE SU NACIONALIDAD NI:', 'DEL DERECHO DE CAMBIAR DE NACIONALIDAD.', 'ART. 15. Num. 2', '181054'),
    (204, 'SUB-0204', 'SBM1', 'LA FAMILIA ES EL ELEMENTO NATURAL Y FUNDAMENTAL DE LA:.', 'SOCIEDAD.', 'ART. 16. Num. 3', '181055'),
    (205, 'SUB-0205', 'SBM1', 'LA VOLUNTAD DEL PUEBLO ES LA BASE DE LA AUTORIDAD DEL PODER PÚBLICO; ESTA VOLUNTAD SE EXPRESARÁ MEDIANTE ELECCIONES AUTÉNTICAS QUE HABRÁN DE CELEBRARSE', 'PERIÓDICAMENTE', 'ART. 21. Num. 3', '181056'),
    (206, 'SUB-0206', 'SBM1', 'TODA PERSONA, COMO MIEMBRO DE LA SOCIEDAD, TIENE DERECHO:.', 'A LA SEGURIDAD SOCIAL.', 'ART. 22', '181057'),
    (207, 'SUB-0207', 'SBM1', 'NADIE SERÁ CONDENADO POR ACTOS U OMISIONES QUE EN EL MOMENTO DE COMETERSE:.', 'NO FUERON DELICTIVOS.', 'ART. 11. Num. 2', '181058'),
    (208, 'SUB-0208', 'SBM1', 'TODA PERSONA TIENE DERECHO, A SER OÍDA PÚBLICAMENTE Y CON JUSTICIA POR UN TRIBUNAL INDEPENDIENTE E IMPARCIAL, PARA EL EXAMEN DE CUALQUIER ACUSACIÓN CONTRA ELLA EN:.', 'MATERIA PENAL.', 'ART. 10', '181059'),
    (209, 'SUB-0209', 'SBM1', 'PARA QUE LOS DERECHOS Y LIBERTADES PROCLAMADOS EN ESTA DECLARACIÓN SE HAGAN PLENAMENTE EFECTIVOS, TODA PERSONA TIENE DERECHO A QUE SE ESTABLEZCA UN ORDEN:.', 'SOCIAL E INTERNACIONAL.', 'ART. 28', '181060'),
    (210, 'SUB-0210', 'SBM1', 'EL ACCESO A LOS ESTUDIOS SUPERIORES SERA IGUAL PARA TODOS, EN FUNCION DE LOS:.', 'MÉRITOS RESPECTIVOS.', 'ART. 26. Num. 1', '181061'),
    (211, 'SUB-0211', 'SBM1', 'TODA PERSONA TIENE DERECHO A SALIR DE CUALQUIER:.', 'PAÍS.', 'ART. 13. Num. 2', '181062'),
    (212, 'SUB-0212', 'SBM1', 'LA MATERNIDAD Y LA INFANCIA TIENEN DERECHO A CUIDADOS Y ASISTENCIA ESPECIALES. TODOS LOS NIÑOS, NACIDOS DE MATRIMONIO O FUERA DE MATRIMONIO, TIENEN DERECHO.', 'IGUAL PROTECCIÓN SOCIAL', 'ART. 25. Num. 2', '181063'),
    (213, 'SUB-0213', 'SBM1', 'TODA PERSONA TIENE DERECHO AL TRABAJO, A LA LIBRE ELECCIÓN DE SU TRABAJO, ACONDICIONES EQUITATIVAS Y SATISFACTORIAS DE TRABAJO Y A LA PROTECCIÓN CONTRA:', 'EL DESEMPLEO', 'ART. 23. Num. 1', '181064'),
    (214, 'SUB-0214', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA LIBERTAD DE MANIFESTAR SU RELIGIÓN O SU CREENCIA, INDIVIDUAL Y COLECTIVAMENTE, TANTO EN PUBLICO COMO EN PRIVADO, POR LA:.', 'ENSEÑANZA.', 'ART. 18', '181065'),
    (215, 'SUB-0215', 'SBM1', 'TODA PERSONA TIENE DERECHO AL TRABAJO, A LA LIBRE ELECCIÓN DE SU TRABAJO, A CONDICIONES EQUITATIVAS Y SATISFACTORIAS DE TRABAJO Y A LA PROTECCIÓN CONTRA:.', 'EL DESEMPLEO.', 'ART. 23. Num. 1', '181066'),
    (216, 'SUB-0216', 'SBM1', 'TODO INDIVIDUO TIENE DERECHO A LA VIDA, A LA LIBERTAD Y A LA:.', 'SEGURIDAD DE SU PERSONA.', 'ART. 3', '181067'),
    (217, 'SUB-0217', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA PROTECCIÓN DE LOS INTERESES MORALES Y MATERIALES QUE LE CORRESPONDAN POR RAZÓN DE:.', 'LAS PRODUCCIONES CIENTÍFICAS, LITERARIAS O ARTÍSTICAS DE QUE SEA AUTORA', 'ART. 27. Num. 2', '181068'),
    (218, 'SUB-0218', 'SBM1', 'ANTE LOS TRIBUNALES NACIONALES COMPETENTES, QUE LA AMPARE CONTRA ACTOS QUE VIOLEN SUS DERECHOS FUNDAMENTALES RECONOCIDOS POR LA CONSTITUCIÓN O POR LA LEY, TODA PERSONA TIENE DERECHO A UN RECURSO:.', 'EFECTIVO.', 'ART. 8 Declaración Universal de los Derechos Humanos', '181069'),
    (219, 'SUB-0219', 'SBM1', 'NADIE PODRÁ SER ARBITRARIAMENTE:.', 'DETENIDO, PRESO NI DESTERRADO.', 'ART. 9', '181070'),
    (220, 'SUB-0220', 'SBM1', 'TODOS LOS SERES HUMANOS DEBEN_____________________ FRATERNALMENTE LOS UNOS CON LOS OTROS.', 'COMPORTARSE.', 'ART. 1', '181071'),
    (221, 'SUB-0221', 'SBM1', 'NADA EN ESTA DECLARACIÓN PODRÁ INTERPRETARSE EN EL SENTIDO DE QUE CONFIERE DERECHO ALGUNO:', 'AL ESTADO', 'ART. 30', '181072'),
    (222, 'SUB-0222', 'SBM1', 'TODA PERSONA TIENE DERECHO AL DESCANSO, AL DISFRUTE DEL TIEMPO LIBRE, A UNA LIMITACIÓN RAZONABLE DE LA DURACIÓN DEL TRABAJO Y A:', 'VACACIONES PERIODICAS PAGADAS', 'ART. 24', '181073'),
    (223, 'SUB-0223', 'SBM1', 'TODOS TIENEN DERECHO A IGUAL PROTECCIÓN CONTRA TODA DISCRIMINACIÓN QUE INFRINJA ESTA DECLARACIÓN, CORRESPONDE A:', 'IGUALDAD ANTE LA LEY', 'ART. 7', '181074'),
    (224, 'SUB-0224', 'SBM1', 'EN UNA ASOCIACIÓN, NADIE PODRÁ SER OBLIGADO A:', 'PERTENECER', 'ART. 20. Num. 2', '181075'),
    (225, 'SUB-0225', 'SBM1', 'TODA PERSONA TIENE DERECHO A LA PROPIEDAD: Declaración Universal de los Derechos Humanos', 'INDIVIDUAL Y COLECTIVAMENTE', 'ART. 17. Num.1', '181076'),
    (226, 'SUB-0226', 'SBM1', 'LA ESCLAVITUD Y LA TRATA DE ESCLAVOS ESTÁN:', 'PROHIBIDAS EN TODAS SUS FORMAS', 'ART. 4', '181077'),
