    (228, 'SUB-0228', 'SBM1', 'NADIE SERA OBJETO DE INJERENCIAS ARBITRARIAS EN SU:', 'DOMICILIO', 'ART. 12', '181079'),
    (229, 'SUB-0229', 'SBM1', 'TODA PERSONA TIENE DERECHO A BUSCAR ASILO, EN CASO DE:', 'PERSECUCIÓN', 'ART. 14. Num. 1', '181080'),
    (230, 'SUB-0230', 'SBM1', 'TODA PERSONA TIENE TODOS LOS DERECHOS Y LIBERTADES PROCLAMADOS EN ESTA DECLARACIÓN, SIN DISTINCIÓN ALGUNA DE:', 'RAZA', 'ART. 2. Num. 1', '181081'),
    (231, 'SUB-0231', 'SBM1', 'INDIQUE QUIENES TIENEN DERECHO PREFERENTE A LA PRESTACIÓN DE LOS SERVICIOS OFRECIDOS POR EL RÉGIMEN DE BIENESTAR DE LA POLICÍA NACIONAL DEL PERÚ:.', 'LOS POLICÍAS AFECTADOS EN CIRCUNSTANCIAS DE SERVICIO, SUS FAMILIARES Y HEREDEROS.', 'ART. 34', '181082'),
    (232, 'SUB-0232', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'HONOR.', 'ART. PRELIMINAR VIII. Num. 1', '181083'),
    (233, 'SUB-0233', 'SBM1', 'ACATAR CONSCIENTE Y VOLUNTARIAMENTE LAS ÓRDENES IMPARTIDAS CON ARREGLO A LEY, ASÍ COMO LA NORMATIVIDAD INSTITUCIONAL, A QUE VALOR INSTITUCIONAL CORRESPONDE:.', 'DISCIPLINA.', 'ART. PRELIMINAR VIII. Num. 6', '181084'),
    (234, 'SUB-0234', 'SBM1', 'ES UNA ATRIBUCIÓN INTERVENIR, CITAR, CONDUCIR COMPULSIVAMENTE, RETENER Y DETENER A LAS PERSONAS DE CONFORMIDAD CON:.', 'LA CONSTITUCIÓN Y LA LEY.', 'ART. 3', '181085'),
    (235, 'SUB-0235', 'SBM1', 'VELAR POR LA SEGURIDAD DE LOS BIENES Y SERVICIOS PÚBLICOS EN COORDINACIÓN CON LAS ENTIDADES ESTATALES CORRESPONDIENTES; ES:.', 'FUNCIONES.', 'ART. 2. Num. 18', '181087'),
    (236, 'SUB-0236', 'SBM1', 'CONDUCTA RESPETUOSA, AMABLE, OPORTUNA, DEFERENTE Y PREDISPUESTA AL SERVICIO DEL CIUDADANO, A QUE VALOR INSTITUCIONAL CORRESPONDE:.', 'CORTESÍA.', 'ART. PRELIMINAR VIII. Num. 5 Decreto Legislativo 1267', '181088'),
    (237, 'SUB-0237', 'SBM1', 'ES UN VALOR INSTITUCIONAL :.', 'JUSTICIA.', 'ART. PRELIMINAR VIII. Num. 3', '181089'),
    (238, 'SUB-0238', 'SBM1', 'CONSTITUYEN SÍMBOLOS DE LA POLICÍA NACIONAL DEL PERÚ:.', 'EL ESTANDARTE, EMBLEMA E HIMNO INSTITUCIONAL.', 'ART. PRELIMINAR IX', '181090'),
    (239, 'SUB-0239', 'SBM1', 'LAS ESCUELAS DE FORMACION PROFESIONAL POLICIAL ESTAN FACULTADOS A OTORGAR A NOMBRE DE LA NACION, LOS GRADOS ACADEMICOS Y LOS TÍTULOS PROFESIONALES EQUIVALENTES A LOS OTORGADOS POR LAS UNIVERSIDADES Y:.', 'LAS ESCUELAS E INSTITUTOS DE EDUCACION SUPERIOR DEL SISTEMA EDUCATIVO.', 'ART. 33', '181091'),
    (240, 'SUB-0240', 'SBM1', 'EL RÉGIMEN DE BIENESTAR TIENE COMO FINALIDAD ORGANIZAR, DESARROLLAR, DIRIGIR, EJECUTAR PROGRAMAS, PROYECTOS Y ACTIVIDADES DE BIENESTAR DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ Y SU:.', 'FAMILIA.', 'ART. 34', '181092'),
    (241, 'SUB-0241', 'SBM1', 'EL EJERCICIO DE LA FUNCIÓN POLICIAL REQUIERE CONOCIMIENTOS ESPECIALIZADOS; LOS CUALES SON ADQUIRIDOS A TRAVÉS DE:.', 'FORMACIÓN PROFESIONAL Y TÉCNICA.', 'ART. PRELIMINAR IV', '181093'),
    (242, 'SUB-0242', 'SBM1', 'VALORES INSTITUCIONALES.- IDENTIFICACIÓN CON UN COLECTIVO HUMANO UNIDO POR LAZOS INSTITUCIONALES Y DE COMPAÑERISMO, BASADOS EN VALORES Y BUENAS PRÁCTICAS QUE DIGNIFICAN LA FUNCIÓN POLICIAL, CORRESPONDE A:.', 'PERTENENCIA INSTITUCIONAL.', 'ART. PRELIMINAR VIII. Num. 3', '181094'),
    (243, 'SUB-0243', 'SBM1', 'LA FORMACIÓN PROFESIONAL POLICIAL, COMO PARTE DE LA ETAPA DE EDUCACIÓN SUPERIOR DEL SISTEMA EDUCATIVO, ES EL PROCESO QUE TIENE COMO FINALIDAD LA:.', 'PREPARACIÓN.', 'ART. 32', '181095'),
    (244, 'SUB-0244', 'SBM1', 'OBTENCIÓN Y REGISTRO DE GRADOS Y TÍTULOS.- ESTAN FACULTADAS A OTORGAR A NOMBRE DE LA NACIÓN LOS GRADOS ACADÉMICOS Y LOS TÍTULOS PROFESIONALES', 'LAS ESCUELAS DE FORMACION PROFESIONAL POLICIAL.', 'ART. 33', '181096'),
    (245, 'SUB-0245', 'SBM1', 'EL SERVICIO POLICIAL DEMANDA LA ACTUACIÓN ÉTICA, PROBA Y CORRECTA, A QUE VALOR INSTITUCIONAL CORRESPONDE:.', 'INTEGRIDAD.', 'ART. PRELIMINAR VIII. Num. 4', '181097'),
    (246, 'SUB-0246', 'SBM1', 'ES LA CONDICIÓN EN LA QUE SE ENCUENTRA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, DENTRO O FUERA DEL SERVICIO. LAS SITUACIONES DEL PERSONAL SON:.', 'ACTIVIDAD.', 'ART. 27', '181098'),
    (247, 'SUB-0247', 'SBM1', 'MANTENER LA PAZ Y LA CONVIVENCIA SOCIAL PACÍFICA, GARANTIZANDO LA SEGURIDAD, TRANQUILIDAD Y ORDEN PÚBLICO; CORRESPONDE A UNA:.', 'FUNCIÓN.', 'ART. 2. Num. 2', '181099'),
    (248, 'SUB-0248', 'SBM1', 'EL PRESUPUESTO DE LA POLICÍA NACIONAL DEL PERÚ ES FIJADO PARA__________________________DENTRO DE LA ESTRUCTURA PRESUPUESTAL DEL PLIEGO DEL MINISTERIO DEL INTERIOR', 'CADA EJERCICIO FISCAL.', 'ART. 41', '181100'),
    (249, 'SUB-0249', 'SBM1', '¿QUÉ ÓRGANO FORMA PARTE DE LA ESTRUCTURA ORGÁNICA DE LA POLICÍA NACIONAL DEL PERÚ?.', 'ÓRGANO DE CONTROL INSTITUCIONAL.', 'ART. 7. Num. 3', '181101'),
    (250, 'SUB-0250', 'SBM1', 'LOS GRADOS, HONORES, TRATAMIENTO, PREEMINENCIAS, PRERROGATIVAS, REMUNERACIONES Y LAS PENSIONES INHERENTES A LOS OFICIALES Y SUBOFICIALES DE LAS FUERZAS ARMADAS Y DE LA POLICÍA NACIONAL SON:', 'EQUIVALENTES.', 'ART. 27', '181102'),
    (251, 'SUB-0251', 'SBM1', 'SON SÍMBOLOS DE LA POLICÍA NACIONAL DEL PERÚ EL EMBLEMA, HIMNO INSTITUCIONAL Y:.', 'ESTANDARTE.', 'ART. PRELIMINAR IX', '181103'),
    (252, 'SUB-0252', 'SBM1', 'CONFORMAN EL ALTO MANDO DE LA POLICÍA NACIONAL DEL PERÚ:.', 'COMANDANTE GENERAL, JEFE DE ESTADO MAYOR E INSPECTOR GENERAL.', 'ART. 8', '181104'),
    (253, 'SUB-0253', 'SBM1', 'LA JUSTICIA, LA INTEGRIDAD Y LA CORTESIA, CONSTITUYEN:.', 'VALORES INSTITUCIONALES.', 'ART. PRELIMINAR VIII. Num. 3.4.5', '181105'),
    (254, 'SUB-0254', 'SBM1', 'DEPENDEN DE LA DIRECCIÓN NACIONAL DE ORDEN Y SEGURIDAD:.', 'LAS REGIONES POLICIALES.', 'ART. 22', '181106'),
    (255, 'SUB-0255', 'SBM1', 'CUMPLIR SUS FUNCIONES CON IMPARCIALIDAD, RESPONSABILIDAD, DILIGENCIA Y PRONTITUD, ASÍ COMO EJERCERLAS CON PROFESIONALISMO, LEALTAD Y ÉTICA. CORRESPONDE A:.', 'OBLIGACIONES DEL PERSONAL POLICIAL.', 'ART. 4. Num. 3', '181107'),
    (256, 'SUB-0256', 'SBM1', 'CONSTITUYE UN DERECHO DEL PERSONAL POLICIAL:.', 'NO ACATAR DISPOSICIONES QUE CONSTITUYEN UNA MANIFIESTA VIOLACIÓN A LA CONSTITUCIÓN Y LAS LEYES.', 'ART. 5. Num. 2', '181108'),
    (257, 'SUB-0257', 'SBM1', '¿ES UNA DE LAS FUNCIONES DEL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ?.', 'EJERCER EL COMANDO Y LA REPRESENTACIÓN DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 9. Num. 1', '181109'),
    (258, 'SUB-0258', 'SBM1', 'PARTICIPAR EN LA DEFENSA NACIONAL, DEFENSA CIVIL Y EN EL DESARROLLO ECONÓMICO Y SOCIAL DEL PAÍS; ES :.', 'FUNCIONES.', 'ART. 2. Num. 20', '181110'),
    (259, 'SUB-0259', 'SBM1', 'LAS SITUACIONES DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU SON:.', 'ACTIVIDAD, DISPONIBLIDAD Y RETIRO.', 'ART. 27', '181111'),
    (260, 'SUB-0260', 'SBM1', 'LA DIRECCION NACIONAL DE ORDEN Y SEGURIDAD SE ENCARGA DE SUPERVISAR LAS OPERACIONES POLICIALES EN MATERIA DE:.', 'SEGURIDAD DEL ESTADO Y SEGURIDAD INTEGRAL.', 'ART. 19', '181112'),
    (261, 'SUB-0261', 'SBM1', 'SE PUEDE CREAR, MODIFICAR, SUPRIMIR O FUSIONAR LAS SUBESPECIALIDADES Y/O DIRECCIONES POLICIALES MEDIANTE: (MARQUE LA ALTERNATIVA CORRECTA).', 'DECRETO SUPREMO.', 'ART. 28', '181113'),
    (262, 'SUB-0262', 'SBM1', 'INTERVENIR CUANDO EL EJERCICIO DE LA FUNCIÓN POLICIAL ASÍ LO REQUIERA, POR CONSIDERAR QUE SUS EFECTIVOS SE ENCUENTRAN DE SERVICIO EN TODO MOMENTO Y CIRCUNSTANCIA; CONSTITUYE.', 'UNA ATRIBUCIÓN.', 'ART. 3. Num. 1', '181114'),
    (263, 'SUB-0263', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ PLANIFICA Y EJECUTA SUS ACCIONES OPERATIVAS Y ADMINISTRATIVAS DE MANERA COORDINADA Y ALINEADAS CON LAS POLÍTICAS NACIONALES, SECTORIALES Y LOS INTERESES DEL ESTADO, GOBIERNOS REGIONALES Y LOCALES; CONSTITUYE EL PRINCIPIO INSTITUCIONAL DE:.', 'LA ARTICULACIÓN DE LAS INTERVENCIONES EN EL TERRITORIO NACIONAL.', 'ART. PRELIMINAR VII. Num. 9', '181115'),
    (264, 'SUB-0264', 'SBM1', 'LA FUNCIÓN POLICIAL SE BRINDA A TRAVÉS DE LA POLICÍA NACIONAL DEL PERÚ, COMO FUERZA PÚBLICA UNITARIA Y COHESIONADA; CORRESPONDE AL PRINCIPIO DE:.', 'UNIDAD DE LA FUNCIÓN POLICIAL.', 'ART. PRELIMINAR VII. Num. 2', '181116'),
    (265, 'SUB-0265', 'SBM1', 'CON QUIEN MANTIENE DEPENDENCIA FUNCIONAL LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ:.', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL DEL MINISTERIO DEL INTERIOR.', 'ART. 11', '181117'),
    (266, 'SUB-0266', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ, SE ORIENTA POR LOS SIGUIENTES PRINCIPIOS:. Decreto Legislativo 1267', 'UNIDAD DE LA FUNCION POLICIAL.', 'ART. PRELIMINAR VII. Num. 2', '181118'),
    (267, 'SUB-0267', 'SBM1', 'EL INGRESO, CARRERA Y TÉRMINO DE LA FUNCIÓN POLICIAL, ASÍ COMO LAS CATEGORÍAS, JERARQUÍAS Y GRADOS, SE REGULAN POR LA:.', 'LEY DE CARRERA Y SITUACIÓN DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 26', '181119'),
    (268, 'SUB-0268', 'SBM1', 'ASCENSO, DE ACUERDO A LA LEY DE CARRERA Y DE SITUACION DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU, CORRESPONDE A:.', 'UN DERECHO.', 'ART. 5. Num. 4', '181120'),
    (269, 'SUB-0269', 'SBM1', 'LA SITUACION DEL PERSONAL ES LA CONDICION EN LA QUE SE ENCUENTRA EL PERSONAL DE LA POLICIA NACIONAL DEL PERU:.', 'DENTRO O FUERA DEL SERVICIO.', 'ART. 27', '181121'),
    (270, 'SUB-0270', 'SBM1', 'EL RÉGIMEN DE BIENESTAR TIENE COMO FINALIDAD ORGANIZAR, DESARROLLAR, DIRIGIR, EJECUTAR PROGRAMAS, PROYECTOS Y ACTIVIDADES DE BIENESTAR DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ Y SU FAMILIA, A FIN DE CONTRIBUIR A SU DESARROLLO:.', 'INTEGRAL.', 'ART. 34', '181122'),
    (271, 'SUB-0271', 'SBM1', 'LA FUNCIÓN: REALIZAR INSPECCIONES DE CONTROL INTERNO A LOS ÓRGANOS Y UNIDADES ORGÁNICAS QUE CONFORMAN LA POLICÍA NACIONAL DEL PERÚ PARA VERIFICAR LA CALIDAD, EFICIENCIA Y EFICACIA EN EL EJERCICIO DE LA FUNCIÓN POLICIAL, LE CORRESPONDE AL:.', 'INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 11. Num. 5 Decreto Legislativo 1267', '181123'),
    (272, 'SUB-0272', 'SBM1', 'LAS CATEGORIAS, JERARQUIAS Y GRADOS SE REGULAN POR:.', 'LA LEY DE LA CARRERA Y SITUACIÓN DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 26', '181124'),
    (273, 'SUB-0273', 'SBM1', 'APROBAR, EN EL MARCO DE SU COMPETENCIA, LAS RESOLUCIONES, MANUALES, REGLAMENTOS, DIRECTIVAS Y DEMÁS DOCUMENTOS DE CARÁCTER INTERNO QUE REGULEN EL FUNCIONAMIENTO OPERATIVO DE LA POLICÍA NACIONAL DEL PERÚ PARA EL EJERCICIO DE LA FUNCIÓN POLICIAL; ESTA FUNCIÓN CORRESPONDE A:.', 'LA COMANDANCIA GENERAL.', 'ART. 9. Num. 15', '181125'),
    (274, 'SUB-0274', 'SBM1', 'SE CREAN DE MANERA EXCEPCIONAL Y TEMPORAL, EN EL MISMO NIVEL Y ORGANIZACIÓN FUNCIONAL DE UNA REGIÓN POLICIAL.', 'FRENTES POLICIALES', 'ART: 23', '181126'),
    (275, 'SUB-0275', 'SBM1', 'SUS INTEGRANTES SE DEBEN AL CUMPLIMIENTO DE LA LEY, EL ORDEN Y LA SEGURIDAD EN TODA LA REPÚBLICA. EL ENUNCIADO CORRESPONDE A:.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. PRELIMINAR II. Segundo párrafo', '181128'),
    (276, 'SUB-0276', 'SBM1', 'PROPONER NORMAS QUE RESULTEN NECESARIAS PARA EL EFICAZ FUNCIONAMIENTO DEL REGIMEN DISCIPLINARIO POLICIAL; ESTA FUNCIÓN CORRESPONDE A:.', 'LA INSPECTORÍA GENERAL.', 'ART. 11. Num. 8', '181129'),
    (277, 'SUB-0277', 'SBM1', 'PREVENIR, COMBATIR, INVESTIGAR Y DENUNCIAR LA COMISION DE LOS DELITOS Y FALTAS PREVISTOS EN EL CÓDIGO PENAL Y LEYES ESPECIALES; ES :.', 'FUNCIONES.', 'ART. 2. Num. 7', '181130'),
    (278, 'SUB-0278', 'SBM1', 'DE LA ASISTENCIA SOCIAL.- LA POLICÍA NACIONAL DEL PERÚ CONTRIBUYE A LA MEJORA DE LA CALIDAD DE VIDA DE SU PERSONAL EN SITUACIÓN DE:.', 'RETIRO.', 'ART. 35', '181131'),
    (279, 'SUB-0279', 'SBM1', 'PRIORIZAR Y DETERMINAR LOS RECURSOS INSTITUCIONALES PARA GARANTIZAR EL CUMPLIMIENTO OPORTUNO DE LA FUNCIÓN POLICIAL, ES UNA FUNCIÓN DEL:.', 'COMANDO DE OPERACIONES POLICIALES.', 'ART. 13', '181132'),
    (280, 'SUB-0280', 'SBM1', 'CUANDO LAS CIRCUNSTANCIAS ASI LO REQUIERAN, EN EL CUMPLIMIENTO DE SUS FUNCIONES; ESTAN OBLIGADAS A PRESTAR APOYO A LA POLICÍA NACIONAL DEL PERÚ:.', 'LAS PERSONAS NATURALES Y JURÍDICAS.', 'ART. PRELIMINAR VI', '181133'),
    (281, 'SUB-0281', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'VOCACIÓN.', 'ART. PRELIMINAR VIII. Num. 9', '181134'),
    (282, 'SUB-0282', 'SBM1', 'SE ENCUENTRAN BAJO EL REGIMEN LABORAL DEL DECRETO LEGISLATIVO N° 276 LEY DE BASES DE LA CARRERA ADMINISTRATIVA Y DE REMUNERACIONES DEL SECTOR PUBLICO Y SU REGLAMENTO:.', 'EL PERSONAL CIVIL.', 'ART. 29', '181135'),
    (283, 'SUB-0283', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ PARA EL CUMPLIMIENTO DE LA FUNCIÓN POLICIAL; REALIZA LO SIGUIENTE:.', 'PRESTA PROTECCIÓN, Y AYUDA A LAS PERSONAS Y A LA COMUNIDAD.', 'ART. PRELIMINAR III. Num. 2', '181136'),
    (284, 'SUB-0284', 'SBM1', 'DE LOS AUXILIARES DE POLICIA.- EL PERSONAL CIVIL EN LA FUNCION DE AUXILIAR DE POLICIA PODRÁ ASUMIR:.', 'FUNCIONES ADMINISTRATIVAS VINCULADAS A LAS FUNCIONES POLICIALES.', 'ART. 30', '181137'),
    (285, 'SUB-0285', 'SBM1', '¿A QUIÉN CORRESPONDE LA FUNCIÓN DE PRESERVAR Y CONTROLAR LA DISCIPLINA Y LA MORAL DEL PERSONAL, ASÍ COMO LA IMAGEN Y EL PRESTIGIO INSTITUCIONAL:', 'AL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 9. Num. 9', '181138'),
    (286, 'SUB-0286', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ PROMUEVE SERVICIOS EDUCATIVOS PARA LOS HIJOS DE SU PERSONAL, GARANTIZANDO LA BUENA MARCHA:.', 'ADMINISTRATIVA Y PEDAGÓGICA DE LAS INSTITUCIONES EDUCATIVAS.', 'ART. 37', '181139'),
    (287, 'SUB-0287', 'SBM1', 'ESTÁN OBLIGADAS A PRESTAR APOYO A LA POLICÍA NACIONAL DEL PERÚ, CUANDO LAS CIRCUNSTANCIAS ASÍ LO REQUIERAN, EN EL CUMPLIMIENTO DE SUS FUNCIONES; ESTAN REFERIDAS A:.', 'LAS AUTORIDADES.', 'ART. PRELIMINAR VI', '181140'),
    (288, 'SUB-0288', 'SBM1', 'NO FORMA PARTE DE LA CARRERA DEL PERSONAL POLICIAL DE LA POLICÍA NACIONAL DEL PERÚ:.', 'EL PERSONAL CIVIL.', 'ART. 29', '181141'),
    (289, 'SUB-0289', 'SBM1', 'SON SÍMBOLOS DE LA POLICÍA NACIONAL DEL PERÚ EL EMBLEMA, ESTANDARTE E HIMNO:.', 'INSTITUCIONAL.', 'ART. PRELIMINAR IX', '181142'),
    (290, 'SUB-0290', 'SBM1', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EJERCE LA FUNCIÓN POLICIAL A DEDICACIÓN:.', 'EXCLUSIVA.', 'ART. PRELIMINAR III', '181143'),
    (291, 'SUB-0291', 'SBM1', 'HACER USO DE LA FUERZA DE ACUERDO A LA NORMATIVIDAD VIGENTE, CÓDIGO DE CONDUCTA PARA FUNCIONARIOS ENCARGADOS DE HACER CUMPLIR LA LEY ES UNA :.', 'ATRIBUCIÓN.', 'ART. 3. Num. 8', '181144'),
    (292, 'SUB-0292', 'SBM1', 'PRACTICAR Y EMITIR PERITAJES OFICIALES DE CRIMINALISTICA PARA EFECTOS DE PROCESOS JUDICIALES Y OTROS DERIVADOS DE LA FUNCION POLICIAL :.', 'FUNCIONES.', 'ART. 2', '181145'),
    (293, 'SUB-0293', 'SBM1', 'LA FORMACIÓN PROFESIONAL POLICIAL, COMO PARTE DE LA ETAPA DE EDUCACIÓN SUPERIOR DEL SISTEMA EDUCATIVO, ES EL PROCESO QUE TIENE COMO FINALIDAD LA:.', 'ESPECIALIZACIÓN.', 'ART. 32', '181146'),
    (294, 'SUB-0294', 'SBM1', 'DEPENDEN DE LA DIRECCIÓN NACIONAL DE ORDEN Y SEGURIDAD:.', 'LOS FRENTES POLICIALES.', 'ART. 23', '181147'),
    (295, 'SUB-0295', 'SBM1', 'RECURSOS DIRECTAMENTE RECAUDADOS.- LOS PROCEDIMIENTOS ADMINISTRATIVOS Y SERVICIOS PRESTADOS EN EXCLUSIVIDAD QUE SE BRINDEN A TRAVÉS DE LA POLICÍA NACIONAL DEL PERÚ SON APROBADOS POR EL:.', 'MINISTERIO DEL INTERIOR.', 'DISP. COMP. FIN. SEGUNDA.- RECURSOS DIRECTAMENTE RECAUDADOS', '181148'),
    (296, 'SUB-0296', 'SBM1', 'EFICIENCIA Y EFICACIA.- TODA ACTUACIÓN POLICIAL PROCURA SER EFICIENTE, EFICAZ, Y SE ORIENTA A UNA PERMANENTE OPTIMIZACIÓN DE LA CALIDAD DEL SERVICIO POLICIAL; CORRESPONDE A:.', 'UN PRINCIPIO.', 'ART. PRELIMINAR VII. Num. 8', '181149'),
    (297, 'SUB-0297', 'SBM1', 'ES UNA FUNCIÓN DE LA COMANDANCIA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ:.', 'ADMINISTRAR LA INSTITUCIÓN POLICIAL A TRAVÉS DE SUS ÓRGANOS COMPETENTES Y LOS RECURSOS QUE SE LE ASIGNE A LA POLICIA NACIONAL.', 'ART. 9. Num. 2', '181150'),
    (298, 'SUB-0298', 'SBM1', 'EL INGRESO, CARRERA, EVALUACIÓN DESEMPEÑO Y TÉRMINO DE LA FUNCIÓN POLICIAL, ASÍ COMO LAS CATEGORÍAS, JERARQUÍAS Y GRADOS SE REGULAN POR:.', 'LA LEY DE CARRERA Y SITUACIÓN DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 26', '181151'),
    (299, 'SUB-0299', 'SBM1', 'ES UN VALOR INSTITUCIONAL:.', 'INTEGRIDAD.', 'ART. PRELIMINAR VIII. Num. 4', '181152'),
    (300, 'SUB-0300', 'SBM1', 'ES UNA ESPECIALIDAD FUNCIONAL DEL PERSONAL DE ARMAS:.', 'INVESTIGACIÓN CRIMINAL', 'ART. 28. Num. 5', '181153')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

