INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 301 a 400
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (301, 'SUB-0301', 'SBM1', 'PARA EL EJERCICIO DE SUS FUNCIONES Y ATRIBUCIONES, LA POLICÍA NACIONAL DEL PERÚ SE ORIENTA POR EL SIGUIENTE PRINCIPIO:.', 'UNIDAD DE LA FUNCIÓN POLICIAL.', 'ART. PRELIMINAR VII. Num. 2', '181154'),
    (302, 'SUB-0302', 'SBM1', 'SON DESIGNADOS Y CONVOCADOS POR EL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ:.', 'LOS INTEGRANTES DE LOS ORGANOS CONSULTIVOS.', 'ART. 15', '181155'),
    (303, 'SUB-0303', 'SBM1', 'EL ORGANO DE ASESORAMIENTO ES RESPONSABLE DE:.', 'ORIENTAR LA LABOR DE LA POLICÍA NACIONAL DEL PERU MEDIANTE EL CUMPLIMIENTO DE ACTIVIDADES DE ASESORIA JURIDICA Y PLANEAMIENTO.', 'ART. 16. Num. 1', '181156'),
    (304, 'SUB-0304', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ, CELEBRA SU ANIVERSARIO INSTITUCIONAL, CON LA FINALIDAD DE:.', 'FORTALECER LA VOCACIÓN PROFESIONAL,IDENTIDAD, DOCTRINA Y MISTICA INSTITUCIONAL.', 'ART. PRELIMINAR X', '181157'),
    (305, 'SUB-0305', 'SBM1', 'ESTABLECE LAS NORMAS Y PROCEDIMIENTOS DISCIPLINARIOS DESTINADOS A REGULAR, PREVENIR, INVESTIGAR Y SANCIONAR LAS INFRACCIONES EN LAS QUE INCURRE EL PERSONAL DE LA POLICIA NACIONAL DEL PERU:.', 'EL SISTEMA DISCIPLINARIO POLICIAL.', 'ART. 31', '181158'),
    (306, 'SUB-0306', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'CORTESÍA.', 'ART. PRELIMINAR VIII. Num. 5', '181159'),
    (307, 'SUB-0307', 'SBM1', 'ES UN DERECHO DEL PERSONAL POLICIAL:. Decreto Legislativo 1267', 'PERMISOS, LICENCIAS Y GOCE DE VACACIONES ANUALES, CONFORME A LEY.', 'ART. 5. Num. 10', '181160'),
    (308, 'SUB-0308', 'SBM1', 'LA POLICIA NACIONAL DEL PERU PROPONE AL MINISTERIO DEL INTERIOR LA CELEBRACION DE CONVENIOS Y/O:.', 'ACUERDOS DE COOPERACION INSTITUCIONAL.', 'ART. 45', '181161'),
    (309, 'SUB-0309', 'SBM1', 'LOS INTEGRANTES DE LOS ÓRGANOS CONSULTIVOS SON DESIGNADOS Y CONVOCADOS POR EL:.', 'COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 15', '181162'),
    (310, 'SUB-0310', 'SBM1', 'EL UNIFORME REGLAMENTARIO, LA PLACA INSIGNIA Y EL CARNÉ DE IDENTIDAD; SON DISTINTIVOS DE AUTORIDAD Y MANDO DEL:.', 'PERSONAL DE ARMAS.', 'ART. PRELIMINAR IX', '181163'),
    (311, 'SUB-0311', 'SBM1', 'ARTICULA DE MODO SISTÉMICO LA INVESTIGACIÓN CRIMINAL CON ESPECIALIZADAS, DIVISIONES Y UNIDADES ORGÁNICAS DE LOS ÓRGANOS DESCONCENTRADOS QUE REALIZAN FUNCIONES DE INVESTIGACIÓN, A NIVEL NACIONAL.', 'LAS DIRECCIONES.', 'ART. 18', '181164'),
    (312, 'SUB-0312', 'SBM1', 'DIOS, PATRIA Y LEY ES:.', 'LEMA DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. PRELIMINAR X', '181165'),
    (313, 'SUB-0313', 'SBM1', 'GERENCIAR EL DESARROLLO INSTITUCIONAL, DE CONFORMIDAD CON LA CONSTITUCIÓN POLÍTICA DEL PERÚ Y LA NORMATIVIDAD LEGAL Y ADMINISTRATIVA VIGENTE, ESTA FUNCIÓN CORRESPONDE A:.', 'LA COMANDANCIA GENERAL.', 'ART. 9. Num. 7', '181166'),
    (314, 'SUB-0314', 'SBM1', 'INVESTIGAR LA DESAPARICIÓN Y TRATA DE PERSONAS; CORRESPONDE A:.', 'FUNCIONES.', 'ART. 2. Num. 11', '181167'),
    (315, 'SUB-0315', 'SBM1', 'DE SER NECESARIO, LAS PERSONAS Y VEHÍCULOS AUTOMOTORES PODRÁN SER CONDUCIDOS A LA UNIDAD POLICIAL PARA:.', 'SU PLENA IDENTIFICACIÓN.', 'ART. 3. Num. 3', '181168'),
    (316, 'SUB-0316', 'SBM1', 'EL ESTADO MAYOR GENERAL, ESTÁ A CARGO DE UN OFICIAL GENERAL DE ARMAS DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD EN EL GRADO DE:.', 'TENIENTE GENERAL.', 'ART. 10', '181169'),
    (317, 'SUB-0317', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ EJERCE COMPETENCIA FUNCIONAL Y EXCLUSIVA A NIVEL NACIONAL; EN MATERIA DE:.', 'ORDEN INTERNO Y ORDEN PÚBLICO; Y COMPETENCIA COMPARTIDA EN MATERIA DE SEGURIDAD CIUDADANA.', 'ART. 1', '181170'),
    (318, 'SUB-0318', 'SBM1', 'LOS UNIFORMES, DISTINTIVOS Y LAS DIVISAS DE LA POLICÍA NACIONAL DEL PERÚ SE ESPECIFICAN EN EL REGLAMENTO RESPECTIVO Y SON DE USO EXCLUSIVO DE:.', 'SUS INTEGRANTES.', 'ART. PRELIMINAR IX Decreto Legislativo 1267', '181171'),
    (319, 'SUB-0319', 'SBM1', 'PARTICIPA EN LA DEFENSA NACIONAL, MOVILIZACION Y DEFENSA CIVIL:', 'LA POLICIA NACIONAL DEL PERU.', 'ART. 42', '181173'),
