    (322, 'SUB-0322', 'SBM1', 'EL PERSONAL POLICIAL ACCEDE A LA ESPECIALIDAD FUNCIONAL DE CONTROL ADMINISTRATIVO DISCIPLINARIO COMO SEGUNDA ESPECIALIDAD:.', 'EN LA JERARQUIA DE OFICIAL SUPERIOR.', 'ART. 28', '181176'),
    (323, 'SUB-0323', 'SBM1', 'EMPLEO DE SISTEMAS TECNOLÓGICOS Y REGISTROS CON FINES POLICIALES.- INDIQUE CUAL DE LAS SIGUIENTES ALTERNATIVAS FORMA PARTE DEL REGISTRO NACIONAL DE SEGURIDAD PÚBLICA:.', 'REFERENCIAS POLICIALES.', 'ART. 43', '181177'),
    (324, 'SUB-0324', 'SBM1', 'SERVICIO DE SALUD: LA POLICIA NACIONAL DEL PERU CUENTA CON UN REGIMEN DE SALUD PARA:.', 'EL PERSONAL POLICIAL Y FAMILIARES BENEFICIARIOS.', 'ART. 36', '181179'),
    (325, 'SUB-0325', 'SBM1', 'COMPORTARSE CON HONORABILIDAD Y DIGNIDAD ES UNA:. Decreto Legislativo 1267', 'OBLIGACIÓN.', 'ART. 4. Num. 4', '181180'),
    (326, 'SUB-0326', 'SBM1', 'EL CONSEJO DE CALIFICACION ES UN:.', 'ORGANO CONSULTIVO.', 'ART. 15. Num. 2', '181181'),
    (327, 'SUB-0327', 'SBM1', 'A QUIÉN CORRESPONDE LA FUNCIÓN DE DETERMINAR LOS OBJETIVOS Y ESTRATEGIAS PARA MANTENER LA DISCIPLINA, LA IMAGEN INSTITUCIONAL, LA ÉTICA Y LA CALIDAD DEL SERVICIO POLICIAL, EN CONCORDANCIA CON LAS POLÍTICAS Y LINEAMIENTOS ESTABLECIDOS POR LA COMANDANCIA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ Y EL MINISTERIO DEL INTERIOR:.', 'INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 11. Num. 1', '181182'),
    (328, 'SUB-0328', 'SBM1', 'LA POLICIA NACIONAL DEL PERU A TRAVES DEL FONDO DE VIVIENDA POLICIAL, ADMINISTRA LOS FONDOS PROVENIENTES DEL ESTADO Y DE APORTACIONES DE SU PERSONAL, CON LA FINALIDAD DE CONTRIBUIR AL ACCESO__________________AL PERSONAL APORTANTE Y A SUS FAMILIARES CON DERECHO.', 'A UNA VIVIENDA DIGNA.', 'ART. 38', '181183'),
    (329, 'SUB-0329', 'SBM1', 'VALORES INSTITUCIONALES.-SERVIR A LA INSTITUCIÓN POLICIAL, CUYA DOCTRINA, ORGANIZACIÓN Y PRÁCTICA SON PROPIAS DE LA POLICÍA NACIONAL DEL PERÚ, DESTINADA A PROTEGER Y GARANTIZAR EL LIBRE EJERCICIO DE LOS DERECHOS Y LAS LIBERTADES DE LAS PERSONAS, PREVENIR Y CONTROLAR TODA CLASE DE DELITOS Y FALTAS, ASÍ COMO A MANTENER LA PAZ INTERNA, LA TRANQUILIDAD, EL ORDEN INTERNO, EL ORDEN PÚBLICO Y LA SEGURIDAD CIUDADANA, CORRESPONDE A:.', 'SERVICIO.', 'ART. PRELIMINAR VIII. Num. 10', '181184'),
    (330, 'SUB-0330', 'SBM1', 'ES UNA ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ REALIZAR LA INSPECCIÓN FÍSICO O QUÍMICA DE LOS VEHÍCULOS SINIESTRADOS Y EMITIR PROTOCOLOS PERICIALES PARA LAS ACCIONES :', 'ADMINISTRATIVAS O JUDICIALES.', 'ART. 3. Num. 6', '181185'),
    (331, 'SUB-0331', 'SBM1', 'PROMOVER LAS RELACIONES INTERINSTITUCIONALES E INTERSECTORIALES, NACIONALES Y EXTRANJERAS, QUE COADYUVEN AL DESARROLLO DE LA FUNCIÓN POLICIAL; ES UNA FUNCIÓN DE:.', 'COMANDANCIA GENERAL.', 'ART. 9. Num. 10', '181186'),
    (332, 'SUB-0332', 'SBM1', '¿QUIENES PUEDEN PARTICIPAR EN TAREAS DE APOYO DE SEGURIDAD CIUDADANA?.', 'LOS COMITES CIVICOS DE APOYO.', 'ART. 44', '181187'),
    (333, 'SUB-0333', 'SBM1', 'LA DIRECCION NACIONAL DE ORDEN Y SEGURIDAD ES :.', 'UN ORGANO DE LINEA', 'ART. 17', '181188'),
    (334, 'SUB-0334', 'SBM1', 'ESTA SOMETIDO A LA CONSTITUCIÓN POLÍTICA EL PERÚ LOS TRATADOS INTERNACIONALES RATIFICADO POR EL ESTADO PERUANO, LAS LEYES, EL CÓDIGO PENAL MILITAR POLICIAL Y LAS NORMAS REGLAMENTARIAS:.', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU.', 'ART. 25', '181189'),
    (335, 'SUB-0335', 'SBM1', 'EL ORGANO DE CONTROL INSTITUCIONAL PROMUEVE', 'LA CORRECTA Y TRANSPARENTE GESTION DE LOS RECURSOS Y BIENES DEL ESTADO ASIGNADOS', 'ART. 14', '181190'),
