    (337, 'SUB-0337', 'SBM1', 'PROPORCIONAR INFORMACIÓN OPORTUNA AL MINISTRO DEL INTERIOR SOBRE ASUNTOS DE CONFLICTIVIDAD SOCIAL Y GRAVES ALTERACIONES AL ORDEN INTERNO O SEGURIDAD PÚBLICA, CONSTITUYE UNA FUNCIÓN DEL:.', 'COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 9. Num. 12', '181192'),
    (338, 'SUB-0338', 'SBM1', 'LA FORMACIÓN PROFESIONAL POLICIAL SE OFRECE A TRAVÉS DE:.', 'ESCUELAS DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 32', '181193'),
    (339, 'SUB-0339', 'SBM1', 'LA ORIENTACIÓN AL CIUDADANO CONSTITUYE: (MARQUE LA ALTERNATIVA CORRECTA).', 'UN PRINCIPIO INSTITUCIONAL.', 'ART. PRELIMINAR VII. Num. 5', '181194'),
    (340, 'SUB-0340', 'SBM1', 'PARA EFECTOS DEL EJERCICIO DE SUS FUNCIONES Y DE IDENTIFICACIÓN ANTE LA SOCIEDAD Y AUTORIDADES, LA DENOMINACIÓN DE POLICÍA ES UN TÉRMINO DISTINTIVO Y EXCLUSIVO DE:', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. PRELIMINAR IX. Tercer párrafo', '181195'),
    (341, 'SUB-0341', 'SBM1', 'BRINDAR SEGURIDAD AL PRESIDENTE DE LA REPUBLICA EN EJERCICIO O ELECTO, A LOS JEFES DE ESTADO EN VISITA OFICIAL; ES UNA:.', 'FUNCIÓN.', 'ART. 2. Num. 6', '181196'),
