    (343, 'SUB-0343', 'SBM1', '¿ES UNA DE LAS FUNCIONES DEL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ?.', 'ADMINISTRAR LA INSTITUCIÓN POLICIAL A TRAVÉS DE SUS ÓRGANOS COMPETENTES Y LOS RECURSOS QUE SE LE ASIGNE A LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 9. Num. 2', '181198'),
    (344, 'SUB-0344', 'SBM1', 'ESTÁN OBLIGADAS A PRESTAR APOYO A LA POLICÍA NACIONAL DEL PERÚ, CUANDO LAS CIRCUNSTANCIAS ASÍ LO REQUIERAN, EN EL CUMPLIMIENTO DE SUS FUNCIONES; ESTAN REFERIDAS A:.', 'LAS ENTIDADES PÚBLICAS Y PRIVADAS.', 'ART. PRELIMINAR VI', '181199'),
