    (346, 'SUB-0346', 'SBM1', 'POSEER, PORTAR Y USAR ARMAS DE FUEGO, DE CONFORMIDAD CON LA CONSTITUCIÓN Y LA LEY; ES UNA.', 'ATRIBUCIÓN.', 'ART. 3. Num. 9', '181201'),
    (347, 'SUB-0347', 'SBM1', 'LA DENOMINACIÓN DE POLICÍA ES UN SIGNO DISTINTIVO DE USO EXCLUSIVO DE LA POLICÍA NACIONAL DEL PERÚ PARA EFECTOS DE :.', 'IDENTIFICACIÓN ANTE LA SOCIEDAD Y AUTORIDADES.', 'ART. PRELIMINAR IX', '181202'),
