    (349, 'SUB-0349', 'SBM1', 'LA AFECTACIÓN DE ARMAMENTO, VESTUARIO Y EQUIPO QUE GARANTICEN EL EFICIENTE CUMPLIMIENTO DE SUS FUNCIONES, CORRESPONDE A:', 'UN DERECHO.', 'ART. 5. Num. 5', '181204'),
    (350, 'SUB-0350', 'SBM1', 'ES UNA ATRIBUCIÓN : REALIZAR CONSTATACIONES POLICIALES DE :.', 'ACUERDO A LEY.', 'ART. 3. Num. 10', '181205'),
    (351, 'SUB-0351', 'SBM1', 'LAS REMUNERACIONES QUE LE CORRESPONDEN DE ACUERDO A LEY; SON.', 'DERECHOS.', 'ART. 5. Num. 6', '181206'),
    (352, 'SUB-0352', 'SBM1', 'LA FORMACIÓN PROFESIONAL POLICIAL, COMO PARTE DE LA ETAPA DE LA EDUCACIÓN SUPERIOR DEL SISTEMA EDUCATIVO, ES EL PROCESO QUE TIENE COMO FINALIDAD:.', 'LA PREPARACION, ACTUALIZACION, ESPECIALIZACION Y PERFECCIONAMIENTO DEL CUERPO POLICIAL.', 'ART. 32', '181207'),
    (353, 'SUB-0353', 'SBM1', 'REQUERIR EL REGISTRO DE INGRESO DE VEHÍCULOS A TALLERES DE MECÁNICA, ES UNA:.', 'ATRIBUCIÓN.', 'ART. 3. Num. 5', '181208'),
    (354, 'SUB-0354', 'SBM1', 'INTERVENIR EN LA EJECUCIÓN DE LOS PROCEDIMIENTOS DE EXTINCIÓN DE DOMINIO, DE CONFORMIDAD CON LAS NORMAS LEGALES VIGENTES; CONSTITUYE:.', 'UNA FUNCIÓN.', 'ART. 2. Num. 10', '181209'),
    (355, 'SUB-0355', 'SBM1', 'RESPETAR Y CUMPLIR LOS MANDATOS ESTABLECIDOS EN LA CONSTITUCIÓN; ES UNA:.', 'OBLIGACIÓN.', 'ART. 4', '181210'),
    (356, 'SUB-0356', 'SBM1', 'COORDINAR, SUPERVISAR LAS ACTIVIDADES Y OPERACIONES DE INTELIGENCIA Y CONTRAINTELIGENCIA EN LA POLICÍA NACIONAL DEL PERÚ ; ESTA FUNCIÓN CORRESPONDE A:.', 'COMANDO DE OPERACIONES POLICIALES.', 'ART. 13', '181211'),
    (357, 'SUB-0357', 'SBM1', 'LA DIRECCION NACIONAL DE INVESTIGACION CRIMINAL Y LA DIRECCION NACIONAL DE ORDEN Y SEGURIDAD, SON:.', 'ÓRGANOS DE LÍNEA.', 'ART. 17', '181212'),
    (358, 'SUB-0358', 'SBM1', 'ES EL ORGANO DE CARACTER TECNICO, NORMATIVO Y OPERATIVO, QUE TIENE COMPETENCIA A NIVEL NACIONAL:.', 'LA DIRECCION NACIONAL DE ORDEN Y SEGURIDAD.', 'ART. 19', '181213'),
    (359, 'SUB-0359', 'SBM1', 'ES LA CÉLULA BÁSICA DE LA ORGANIZACIÓN DE LA POLICÍA NACIONAL DEL PERÚ, QUE MANTIENE UNA ESTRECHA RELACIÓN CON LA COMUNIDAD Y LOS GOBIERNOS LOCALES Y REGIONALES COADYUVANDO AL DESARROLLO ECONÓMICO Y SOCIAL DE LA JURISDICCIÓN:.', 'LA COMISARIA.', 'ART. 24', '181214'),
    (360, 'SUB-0360', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ PARA EL CUMPLIMIENTO DE LA FUNCIÓN POLICIAL; REALIZA LO SIGUIENTE:.', 'GARANTIZA EL CUMPLIMIENTO DE LAS LEYES Y LA SEGURIDAD DEL PATRIMONIO PÚBLICO Y PRIVADO.', 'ART. PRELIMINAR III. Num. 3', '181215'),
    (361, 'SUB-0361', 'SBM1', 'SE CELEBRA UNA EFEMÉRIDE INSTITUCIONAL EL:.', '30 DE AGOSTO.', 'ART. PRELIMINAR X', '181216'),
    (362, 'SUB-0362', 'SBM1', 'ASESORAR AL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ EN EL DISEÑO DE DIAGNÓSTICO Y PROSPECTIVA EN COORDINACIÓN CON LOS ÓRGANOS RESPONSABLES COMPETENTES ; ESTA FUNCIÓN CORRESPONDE A:.', 'ESTADO MAYOR GENERAL.', 'ART. 10. Num. 3', '181217'),
    (363, 'SUB-0363', 'SBM1', 'OBTENER, CUSTODIAR, ASEGURAR, TRASLADAR Y PROCESAR INDICIOS EVIDENCIAS Y ELEMENTOS PROBATORIOS RELACIONADOS CON LA PREVENCIÓN E INVESTIGACIÓN DEL DELITO; ES:.', 'FUNCIONES.', 'ART. 2', '181218'),
    (364, 'SUB-0364', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'HONESTIDAD.', 'ART. PRELIMINAR VIII. Num. 2', '181219'),
    (365, 'SUB-0365', 'SBM1', 'QUIENES NO FORMAN PARTE DE LA CARRERA DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ Y SE ENCUENTRAN BAJO EL RÉGIMEN DEL DECRETO LEGISLATIVO 276, EN TANTO SE IMPLEMENTEN LAS DISPOSICIONES DE LA LEY N° 30057 LEY DEL SERVICIO CIVIL:.', 'EL PERSONAL CIVIL.', 'ART. 29', '181220'),
    (366, 'SUB-0366', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'PATRIOTISMO.', 'ART. PRELIMINAR VIII. Num. 7', '181222'),
    (367, 'SUB-0367', 'SBM1', 'EL 6 DE DICIEMBRE ES EL DÍA DE LA:.', 'POLICÍA NACIONAL DEL PERÚ.', 'ART. PRELIMINAR X.', '181223'),
    (368, 'SUB-0368', 'SBM1', 'SON DISTINTIVOS DE AUTORIDAD Y MANDO DEL PERSONAL DE ARMAS, LA PLACA INSIGNIA, CARNÉ DE IDENTIDAD Y:.', 'UNIFORME REGLAMENTARIO.', 'ART. PRELIMINAR IX', '181224'),
    (369, 'SUB-0369', 'SBM1', 'PARA EL EJERCICIO DE SUS FUNCIONES Y ATRIBUCIONES, LA POLICÍA NACIONAL DEL PERÚ SE ORIENTA POR EL SIGUIENTE PRINCIPIO:.', 'UNIDAD DE COMANDO.', 'ART. PRELIMINAR VII. Num. 3', '181225'),
    (370, 'SUB-0370', 'SBM1', 'LOS ÓRGANOS DE LÍNEA ESTÁN CONFORMADOS POR: (MARQUE LA ALTERNATIVA CORRECTA).', 'DIRECCIÓN NACIONAL DE INVESTIGACIÓN CRIMINAL, DIRECCIÓN NACIONAL DE ORDEN Y SEGURIDAD.', 'ART. 7. Num. 7', '181226'),
    (371, 'SUB-0371', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'SERVICIO.', 'ART. PRELIMINAR VIII. Num. 10', '181227'),
    (372, 'SUB-0372', 'SBM1', 'ES LA CONDICIÓN EN QUE SE ENCUENTRA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, DENTRO O FUERA DEL SERVICIO:.', 'SITUACIÓN DEL PERSONAL.', 'ART. 27', '181228'),
    (373, 'SUB-0373', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ, A TRAVÉS DEL FONDO DE VIVIENDA POLICIAL, ADMINISTRA LOS FONDOS PROVENIENTES DEL ESTADO Y DE LOS APORTES DE SU PERSONAL, CON LA FINALIDAD DE CONTRIBUIR AL ACCESO A UNA:.', 'VIVIENDA DIGNA.', 'ART. 38', '181229'),
    (374, 'SUB-0374', 'SBM1', 'APROBAR, DIRIGIR Y SUPERVISAR EL DESARROLLO DE LAS ESTRATEGIAS INSTITUCIONALES EN EL AMBITO DE SU COMPETENCIA; ESTA FUNCIÓN CORRESPONDE A:.', 'LA COMANDANCIA GENERAL.', 'ART. 9. Num. 5', '181230'),
    (375, 'SUB-0375', 'SBM1', 'POSEER, PORTAR Y USAR ARMAS DE FUEGO, DE CONFORMIDAD CON LA CONSTITUCIÓN Y LA LEY; ES UNA :.', 'ATRIBUCIÓN.', 'ART. 3. Num. 9', '181231'),
