    (381, 'SUB-0381', 'SBM1', 'DENTRO DE LOS VALORES QUE RIGEN AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. SEÑALE UN VALOR INSTITUCIONAL:.', 'PERTENENCIA INSTITUCIONAL.', 'ART. PRELIMINAR VIII. Num. 8', '181238'),
    (382, 'SUB-0382', 'SBM1', 'SON DISTINTIVOS DE AUTORIDAD Y MANDO DEL PERSONAL DE ARMAS DE LA POLICÍA NACIONAL DEL PERÚ:.', 'EL UNIFORME REGLAMENTARIO, LA PLACA INSIGNIA Y EL CARNÉ DE IDENTIDAD.', 'ART. PRELIMINAR IX', '181239'),
    (383, 'SUB-0383', 'SBM1', 'DE LAS SIGUIENTES ALTERNATIVAS, INDIQUE CUAL ES UN PRINCIPIO INSTITUCIONAL:.', 'PRIMACÍA DE LA PERSONA HUMANA Y SUS DERECHOS FUNDAMENTALES.', 'ART. PRELIMINAR VII. Num. 1', '181240'),
    (384, 'SUB-0384', 'SBM1', 'TRANSPARENCIA Y RENDICIÓN DE CUENTAS.- LA POLICÍA NACIONAL DEL PERÚ ES TRANSPARENTE EN SU ACTUACIÓN Y PROMUEVE LA RENDICIÓN DE CUENTAS DE SU GESTIÓN A LA CIUDADANIA; CORRESPONDE A:. Decreto Legislativo 1267', 'PRINCIPIO.', 'ART. PRELIMINAR VII. Num. 6', '181241'),
    (385, 'SUB-0385', 'SBM1', 'EL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, RECIBE LA DENOMINACIÓN HONORÍFICA DE:.', 'GENERAL DE POLICÍA.', 'ART. 8', '181242'),
    (386, 'SUB-0386', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ SE ORIENTA POR LOS SIGUIENTES PRINCIPIOS:.', 'PRIMACIA DE LA PERSONA HUMANA Y SUS DERECHOS FUNDAMENTALES.', 'ART. PRELIMINAR VII.', '181243'),
    (387, 'SUB-0387', 'SBM1', 'FUNCIÓN POLICIAL.- EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EJERCE LA FUNCIÓN POLICIAL A DEDICACIÓN EXCLUSIVA, EN TODO MOMENTO, LUGAR Y:.', 'CIRCUNSTANCIA.', 'ART. PRELIMINAR III', '181244'),
    (388, 'SUB-0388', 'SBM1', 'LAS AUTORIDADES, ENTIDADES PÚBLICAS Y PRIVADAS, ASÍ COMO LAS PERSONAS NATURALES Y JURÍDICAS ESTAN OBLIGADAS A PRESTAR APOYO A:.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. PRELIMINAR VI', '181245'),
    (389, 'SUB-0389', 'SBM1', 'PROPONER A TRAVES DEL MINISTERIO DEL INTERIOR INICIATIVAS LEGISLATIVAS Y NORMAS EN MATERIA DE SU COMPETENCIA; ES UNA FUNCIÓN DE:.', 'LA COMANDANCIA GENERAL.', 'ART. 9. Num. 13', '181246'),
    (390, 'SUB-0390', 'SBM1', 'LA POLICÍA NACIONAL DEL PERÚ BRINDA ASESORÍA Y DEFENSA LEGAL, AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ SOMETIDO A UN PROCESO PENAL Y CIVIL DERIVADO DEL CUMPLIMIENTO DE LA FUNCIÓN POLICIAL:.', 'GRATUITA.', 'ART. 39', '181247'),
    (391, 'SUB-0391', 'SBM1', 'QUE ENTIDAD ESTABLECE LOS LINEAMIENTOS DE LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ EN CONCORDANCIA CON LA NORMATIVA LEGAL VIGENTE:.', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL DEL MINISTERIO DEL INTERIOR.', 'ART. 11', '181248'),
