    (394, 'SUB-0394', 'SBM1', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ CAMBIADO DE COLOCACIÓN FUERA DE SU LUGAR DE ORIGEN, PUEDE ACCEDER, DE ACUERDO A LA DISPONIBILIDAD, A UNA VIVIENDA EN FORMA TEMPORAL, A TRAVÉS DEL PROGRAMA DE VIVIENDAS ADMINISTRADAS POR LA DIRECCIÓN DE:', 'BIENESTAR', 'ART. 38', '181251'),
    (395, 'SUB-0395', 'SBM1', 'GARANTIZAR, MANTENER Y RESTABLECER EL ORDEN INTERNO, ORDEN PUBLICO Y SEGURIDAD CIUDADANA;ES :', 'FUNCIONES.', 'ART. 2', '181252'),
