INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 401 a 500
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (401, 'SUB-0401', 'SBM1', 'EL 30 DE AGOSTO, ES DÍA DE:', 'SANTA ROSA DE LIMA, PATRONA DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. PRELIMINAR X Decreto Legislativo 1267', '181258'),
    (402, 'SUB-0402', 'SBM1', 'EL PERSONAL POLICIAL DE ARMAS Y SERVICIOS NO PUEDE PERTENECER NI ESTAR AFILIADO O TENER VÍNCULO ALGUNO CON:', 'AGRUPACIONES POLITICAS.', 'ART. 25', '181259'),
    (403, 'SUB-0403', 'SBM1', 'SE BASA EN UN CONJUNTO DE PRINCIPIOS, NORMAS, PROCESOS Y CONDICIONES QUE PERMITEN CONVOCATORIAS, SELECCIÓN SUCESIVA A CADA GRADO:', 'LA CARRERA POLICIAL.', 'ART. 26', '181260'),
    (404, 'SUB-0404', 'SBM1', 'SON AQUELLOS ÓRGANOS DE ADMINISTRACIÓN INTERNA QUE CUMPLEN ACTIVIDADES DE APOYO EN MATERIA DE CRIMINALÍSTICA INTELIGENCIA Y FORMACIÓN PROFESIONAL', 'ÓRGANOS DE APOYO POLICIAL', 'ART. 16', '181261'),
    (405, 'SUB-0405', 'SBM1', 'REALIZAN FUNCIONES TÉCNICAS, NORMATIVAS Y OPERATIVAS NECESARIAS PARA EL CUMPLIMIENTO DE LOS OBJETIVOS ENCOMENDADOS A LA POLICÍA NACIONAL DEL PERÚ:', 'LOS ÓRGANOS DE LÍNEA', 'ART. 17', '181262'),
    (406, 'SUB-0406', 'SBM1', 'SON AQUELLOS ÓRGANOS DE ADMINISTRACIÓN INTERNA QUE CUMPLEN ACTIVIDADES DE APOYO EN MATERIA DE DOCTRINA Y SALUD POLICIAL, PARA EL EJERCICIO EFICIENTE Y OPORTUNO DE LA FUNCIÓN POLICIAL.:', 'ÓRGANOS DE APOYO POLICIAL', 'ART. 16', '181263'),
    (407, 'SUB-0407', 'SBM1', 'SON AQUELLOS ÓRGANOS DE ADMINISTRACIÓN INTERNA QUE CUMPLEN ACTIVIDADES DE APOYO EN MATERIA DE ASUNTOS INTERNACIONALES:', 'ÓRGANOS DE APOYO POLICIAL', 'ART. 16', '181264'),
    (408, 'SUB-0408', 'SBM1', 'SON ÓRGANOS DE ADMINISTRACIÓN INTERNA QUE DESARROLLAN ACTIVIDADES EN MATERIA DE TECNOLOGÍA DE LA INFORMACIÓN:', 'ÓRGANOS DE APOYO ADMINISTRATIVO', 'ART. 16', '181265'),
    (409, 'SUB-0409', 'SBM1', 'LOS ORGANOS DE ADMINISTRACION INTERNA SE CLASIFICAN EN:', 'ORGANOS DE ASESORAMIENTO.', 'ART. 16. Num. 1', '181266'),
    (410, 'SUB-0410', 'SBM1', 'MANTIENE UNA DEPENDENCIA FUNCIONAL CON LA CONTRALORIA GENERAL DE LA REPUBLICA Y DEPENDENCIA ADMINISTRATIVA CON LA POLICIA NACIONAL DEL PERU:', 'EL ORGANO DE CONTROL INSTITUCIONAL', 'ART. 14', '181267'),
    (411, 'SUB-0411', 'SBM1', 'ES EL PERÍODO DE TIEMPO EN QUE EL PERSONAL PRESTA SERVICIOS DESDE LA FECHA DE ALTA COMO OFICIAL O SUBOFICIAL DE ARMAS AL EGRESO DE SU RESPECTIVA ESCUELA Y DESDE LA FECHA DE ALTA A LA INSTITUCIÓN PARA OFICIALES SERVICIOS Y SUBOFICIALES DE SERVICIOS.:.', 'TIEMPO DE SERVICIOS REALES Y EFECTIVOS.', 'ART. 3 Num. 31', '181269'),
    (412, 'SUB-0412', 'SBM1', 'ES EL PERÍODO DE DESCANSO REMUNERADO DE TREINTA (30) DÍAS NATURALES AL AÑO Y COMPRENDE AL PERSONAL POLICIAL EN ACTIVIDAD.', 'VACACIONES.', 'ART. 42', '181271'),
    (413, 'SUB-0413', 'SBM1', 'ES LA DEFINICION DE CUADRO DE ORGANIZACIÓN.', 'DOCUMENTO QUE CONTIENE EL LISTADO DE LOS CARGOS QUE EXISTEN EN LA POLICIA NACIONAL DEL PERU.', 'ART. 3 Num. 7', '181272'),
    (414, 'SUB-0414', 'SBM1', 'ES LA DEFINICION DE OFICIAL DE ARMAS.', 'PROFESIONAL EGRESADO DE LA ESCUELA DE OFICIALES DE LA POLICIA NACIONAL DEL PERU.', 'ART. 3 Num. 21', '181273'),
    (415, 'SUB-0415', 'SBM1', 'ES DE CARÁCTER OBLIGATORIO E IRRENUNCIABLE Y NO PUEDE SER SUSTITUIDO POR COMPENSACIÓN ECONÓMICA:.', 'VACACIONES.', 'ART. 42', '181274'),
    (416, 'SUB-0416', 'SBM1', 'TÍTULO UNIVERSITARIO REGISTRADO EN LA ASAMBLEA NACIONAL DE RECTORES Y COLEGIADO, SEGÚN CORRESPONDA. ES UNO DE LOS REQUISITOS QUE SE REQUIEREN PARA LA ASIMILACIÓN A:.', 'OFICIAL DE SERVICIOS.', 'ART. 19', '181275'),
    (417, 'SUB-0417', 'SBM1', 'ESTA CONSIDERADO COMO UNA CAUSAL DE ASIGNACION Y REASIGNACION DE CARGO:.', 'ESPECIALIDAD FUNCIONAL.', 'ART. 30', '181276'),
    (418, 'SUB-0418', 'SBM1', 'EVALUACIÓN DEL DESEMPEÑO DEL PERSONAL. - SUS OBJETIVOS SON:', 'UBICAR AL PERSONAL EN EL NIVEL QUE LE CORRESPONDA EN LA LISTA DE RENDIMIENTO PROFESIONAL Y TÉCNICO', 'ART. 36 Num. 1', '181277'),
    (419, 'SUB-0419', 'SBM1', 'LOS CARGOS EN LAS AGREGADURIAS POLICIALES, SON LOS SIGUIENTES: AGREGADO POLICIAL ADJUNTO, PERSONAL AUXILIAR Y.', 'AGREGADO POLICIAL.', 'ART. 35', '181278'),
    (420, 'SUB-0420', 'SBM1', 'PASA A LA SITUACIÓN DE RETIRO EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ QUE NO APRUEBA O NO ALCANZA VACANTE AL GRADO INMEDIATO SUPERIOR DURANTE:.', 'CINCO AÑOS CONSECUTIVOS O DISCONTINUOS.', 'ART. 92', '181279'),
    (421, 'SUB-0421', 'SBM1', 'ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO:.', 'NO ESTAR SOMETIDO A PROCEDIMIENTO ADMINISTRATIVO DISCIPLINARIO COMO PRESUNTO INFRACTOR.', 'ART. 34', '181280'),
    (422, 'SUB-0422', 'SBM1', 'DE LOS PRINCIPIOS RECTORES. - SON PRINCIPIOS RECTORES LO SIGUIENTE:', 'PRINCIPIO DE IGUALDAD', 'TITULO PRELIMINAR ART. 4 Num. 1', '181281'),
    (423, 'SUB-0423', 'SBM1', 'ASIGNACION DE CARGOS EN LAS AGREGADURIAS POLICIALES: ES EL CARGO QUE PUEDE SER OCUPADO POR OFICIALES GENERALES O CORONELES DE ARMAS.', 'AGREGADO POLICIAL.', 'ART. 35', '181282'),
    (424, 'SUB-0424', 'SBM1', 'EL PERSONAL AL RETORNAR DE LA MISION DE ESTUDIOS, DEBE SER ASIGNADO A:.', 'A UNA UNIDAD ACORDE CON LA CAPACITACION RECIBIDA.', 'ART. 33', '181283'),
    (425, 'SUB-0425', 'SBM1', 'LA CONVOCATORIA, DETERMINACIÓN DE VACANTES Y REQUISITOS A LOS PROGRAMAS DE SUBESPECIALIZACIÓN, CAPACITACIÓN, REENTRENAMIENTO, MAESTRÍA INSTITUCIONAL Y PERFECCIONAMIENTO PROFESIONAL, SE ESTABLECEN EN EL:.', 'EL REGLAMENTO RESPECTIVO', 'ART. 21', '181284'),
    (426, 'SUB-0426', 'SBM1', 'ORGANIZACIÓN. – ESTRUCTURA. – LA CARRERA DEL PERSONAL POLICIAL, SE DESARROLLA EN FORMA ASCENDENTE, EN NIVELES, EN RAZÓN DE SUS…', 'CATEGORÍA, JERARQUÍAS Y GRADOS', 'ART. 12', '181285'),
    (427, 'SUB-0427', 'SBM1', 'DEBEN CUMPLIR CON EL TIEMPO MÍNIMO COMPENSATORIO DE DOS VECES LA DURACIÓN DE LA COMISIÓN, QUIENES SEAN NOMBRADOS POR UN PERÍODO MAYOR DE SEIS MESES:.', 'EL PERSONAL NOMBRADO EN COMISION DE SERVICIO EN EL EXTRANJERO.', 'ART. 67', '181286'),
    (428, 'SUB-0428', 'SBM1', 'ESTA CONSIDERADO COMO UNA CAUSAL DE ASIGNACIÓN Y REASIGNACIÓN DE CARGO:.', 'EGRESO DE LAS ESCUELAS DE FORMACION, ASIMILACION O REINGRESO A LA INSTITUCION.', 'ART. 30', '181287'),
    (429, 'SUB-0429', 'SBM1', 'PROCESOS TÉCNICOS. - SON PROCESOS TÉCNICOS DE LA CARRERA LOS SIGUIENTES:', 'INICIO DE LA CARRERA', 'ART. 14 Num. 1', '181288'),
    (430, 'SUB-0430', 'SBM1', 'ES EL DOCUMENTO OFICIAL QUE REGISTRA LA PRESENCIA FÍSICA Y EL EJERCICIO DEL EMPLEO Y CARGO DEL PERSONAL EN SITUACIÓN DE ACTIVIDAD. ES ADMINISTRADA Y APROBADA MENSUALMENTE POR LA DIRECCIÓN EJECUTIVA DE PERSONAL..', 'LISTA DE REVISTA.', 'ART. 27', '181289'),
    (431, 'SUB-0431', 'SBM1', 'SON PROCESOS TÉCNICOS DE LA CARRERA:.', 'INCENTIVOS.', 'ART. 14 Num. 5', '181290'),
    (432, 'SUB-0432', 'SBM1', 'SE EJECUTAN A TRAVÉS DE LA ESCUELA DE FORMACIÓN CONTINUA Y LA ESCUELA DE POSGRADO DE LA POLICÍA NACIONAL DEL PERÚ:.', 'LA SUBESPECIALIZACIÓN, LOS CURSOS DE CAPACITACIÓN Y REENTRENAMIENTO, LA MAESTRÍA INSTITUCIONAL Y EL PERFECCIONAMIENTO PROFESIONAL.', 'ART. 20', '181291'),
    (433, 'SUB-0433', 'SBM1', 'PROCESOS TÉCNICOS. - SON PROCESOS TÉCNICOS DE LA CARRERA LOS SIGUIENTES:', 'EVALUACIÓN DEL DESEMPEÑO', 'ART. 14 Num. 4 Decreto Legislativo 1149', '181296'),
    (434, 'SUB-0434', 'SBM1', 'LOS CARGOS EN LAS AGREGADURÍAS POLICIALES, SON LOS SIGUIENTES: AGREGADO POLICIAL, AGREGADO POLICIAL ADJUNTO Y:', 'PERSONAL AUXILIAR.', 'ART. 35', '181293'),
    (435, 'SUB-0435', 'SBM1', 'ES LA CONDICIÓN LABORAL DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD EN FUNCIÓN A SU CATEGORÍA Y GRADO.- CORRESPONDE A:.', 'EL EMPLEO.', 'ART. 23', '181294'),
    (436, 'SUB-0436', 'SBM1', 'EL PERÍODO EN CONDICIÓN DE ASIMILADO PARA OFICIALES Y SUBOFICIALES DE SERVICIOS ES DE DOS AÑOS, AL TÉRMINO DE LOS CUALES, A QUIENES APRUEBEN SATISFACTORIAMENTE LOS EXÁMENES RESPECTIVOS, SE LES OTORGARÁ LA EFECTIVIDAD EN EL GRADO QUE CORRESPONDA, CASO CONTRARIO SE:.', 'CANCELA LA ASIMILACION.', 'ART. 19', '181295'),
    (437, 'SUB-0437', 'SBM1', 'SON ATRIBUTOS INHERENTES AL GRADO DEL PERSONAL POLICIAL: LOS HONORES, TRATAMIENTO, PREEMINENCIAS, PRERROGATIVAS, REMUNERACIONES, BONIFICACIONES Y DEMAS GOCES Y BENEFICIOS DETERMINADOS POR:.', 'LAS LEYES Y REGLAMENTOS RESPECTIVOS.', 'ART. 25', '181296'),
    (438, 'SUB-0438', 'SBM1', 'EN LOS LUGARES QUE NO SE LOGRE CUBRIR COMISARIAS CON OFICIALES DE ARMAS, SE ASIGNARAN SUB OFICIALES DE ARMAS DE LA JERARQUIA DE:.', 'SUBOFICIALES SUPERIORES DE ARMAS.', 'ART. 31', '181297'),
    (439, 'SUB-0439', 'SBM1', 'LA CALIFICACION DE LAS CIRCUNSTANCIAS DEL SERVICIO EN LA QUE PARTICIPA EL PERSONAL DE LA POLICIA NACIONAL DEL PERU SON:.', 'ACCION DE ARMAS, ACTO DEL SERVICIO, CONSECUENCIA DEL SERVICIO, OCASION DEL SERVICIO Y ACTO AJENO AL SERVICIO.', 'ART. 63', '181298'),
    (440, 'SUB-0440', 'SBM1', 'CAUSALES DE ASIGNACIÓN Y REASIGNACIÓN. - LA ASIGNACIÓN Y REASIGNACIÓN DE CARGOS SE PRODUCE, SEGÚN CORRESPONDA, EN LOS CASOS SIGUIENTES', 'NECESIDAD DEL SERVICIO', 'ART. 30 Num. 2', '181299'),
    (441, 'SUB-0441', 'SBM1', 'COMPONENTES DE LA CARRERA.- ES CONSIDERADO COMO UN COMPONENTE DE LA CARRERA:.', 'LA ADMINISTRACION DE LA CARRERA.', 'ART. 7', '181300'),
    (442, 'SUB-0442', 'SBM1', 'ES LA DEFINICION DE DESPACHO.', 'DOCUMENTO QUE ACREDITA EL GRADO DEL PERSONAL.', 'TITULO PRELIMINAR ART. 3 Num. 8', '181301'),
    (443, 'SUB-0443', 'SBM1', 'PARA SER DESIGNADOS COMO AGREGADO POLICIAL ADJUNTO, EL COMANDANTE O MAYOR DE ARMAS DEBE SER EGRESADO:.', 'DEL CURSO DE OFICIAL DE ESTADO MAYOR O DE INSTITUTOS SIMILARES DEL PAÍS O EXTRANJERO.', 'ART. 35', '181302'),
    (444, 'SUB-0444', 'SBM1', 'CAMBIO DE SITUACION.-MEDIANTE RESOLUCION DE LOS ORGANOS DISCIPLINARIOS CONFORME A LA LEY DE LA MATERIA, SE DISPONDRAN LOS CASOS DE:.', 'PASE A LA SITUACION DE DISPONIBILIDAD O RETIRO POR MEDIDA DISCIPLINARIA. Decreto Legislativo 1149', 'ART. 64', '181303'),
    (445, 'SUB-0445', 'SBM1', 'ES EL ORGANO RESPONSABLE DEL PROCESO DE EVALUACION DEL DESEMPEÑO QUE SE REALIZA ANUALMENTE.', 'LA DIRECCION EJECUTIVA DE PERSONAL.', 'ART. 38', '181304'),
    (446, 'SUB-0446', 'SBM1', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PASA A LA SITUACIÓN DE RETIRO POR SENTENCIA JUDICIAL CONDENATORIA, CUANDO LA RESOLUCIÓN JUDICIAL CONSENTIDA O EJECUTORIADA SANCIONE CON PENA PRIVATIVA DE LIBERTAD EFECTIVA O INHABILITACIÓN MAYOR DE:.', 'DOS (2) AÑOS.', 'ART. 93', '181305'),
    (447, 'SUB-0447', 'SBM1', 'LA NOTA DE EVALUACIÓN ANUAL Y LA NOTA DE DISCIPLINA ANUAL, SE PUBLICAN ANUALMENTE EN EL MES DE.', 'MARZO.', 'ART. 37', '181306'),
    (448, 'SUB-0448', 'SBM1', 'SOLO PUEDE SER RETIRADO POR SENTENCIA JUDICIAL CONSENTIDA O EJECUTORIADA Y TIENE CARÁCTER VITALICIO.', 'EL GRADO.', 'ART. 25', '181307'),
    (449, 'SUB-0449', 'SBM1', 'PARA SER DESIGNADOS EN LAS AGREGADURIAS POLICIALES EN EL EXTRANJERO COMO PERSONAL AUXILIAR, LOS SUBOFICIALES SUPERIORES, BRIGADIERES O TECNICOS DE PRIMERA DE ARMAS, DEBEN CONTAR CON:.', 'CURSOS DE CAPACITACION INSTITUCIONALES DE INTELIGENCIA Y COMPUTACION.', 'ART. 35', '181308'),
    (450, 'SUB-0450', 'SBM1', 'CAUSALES DE ASIGNACIÓN Y REASIGNACIÓN. - LA ASIGNACIÓN Y REASIGNACIÓN DE CARGOS SE PRODUCE, SEGÚN CORRESPONDA, EN LOS CASOS SIGUIENTES', 'ASCENSO', 'ART. 30 Num. 4', '181309'),
    (451, 'SUB-0451', 'SBM1', 'LOS INSTRUMENTOS DE GESTIÓN ADMINISTRATIVA DETERMINAN LA ESTRUCTURA DE LA INSTITUCIÓN Y LA ASIGNACIÓN DEL PERSONAL, SON APROBADOS:.', 'ANUALMENTE.', 'ART. 27', '181310'),
    (452, 'SUB-0452', 'SBM1', 'CORRESPONDE A UN GRADO:.', 'TENIENTE GENERAL.', 'ART. 13', '181311'),
    (453, 'SUB-0453', 'SBM1', 'EL PERSONAL NOMBRADO EN MISION DE ESTUDIOS EN EL PAIS O EL EXTRANJERO CON COSTO PARA EL ESTADO, DEBE PRESTAR SERVICIO EL TIEMPO MINIMO COMPENSATORIO SIGUIENTE:.', 'EN EL EXTRANJERO: TRES VECES LA DURACIÓN DE LOS ESTUDIOS.', 'ART. 68', '181312'),
    (454, 'SUB-0454', 'SBM1', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PASARÁ A LA SITUACIÓN DE RETIRO POR LÍMITE DE EDAD EN EL GRADO, EN ATENCIÓN A LA EDAD MÁXIMA ESTABLECIDA EN EL PRESENTE ARTÍCULO. ¿A QUÉ EDAD PASARÁ A LA SITUACIÓN DE RETIRO POR ESTA CAUSAL UN CAPITÁN DE ARMAS?..', '(49) AÑOS.', 'ART. 84', '181313'),
    (455, 'SUB-0455', 'SBM1', 'PARA EL PERSONAL INCORPORADO POR ASIMILACIÓN, LA ANTIGUEDAD SE DETERMINA:.', 'EN ATENCIÓN AL ORDEN DE MÉRITO DE SU INCORPORACIÓN.', 'ART. 24', '181314'),
    (456, 'SUB-0456', 'SBM1', 'PARA EFECTO DE LA PRESENTE NORMA, LA PALABRA JERARQUÍA SE REFIERE A....', 'LOS NIVELES ALCANZADOS POR EL PERSONAL EN SU RESPECTIVA CATEGORÍA, ABARCA UNO (1) O MAS GRADOS', 'TITULO PRELIMINAR ART. 3. Num. 16', '181315'),
    (457, 'SUB-0457', 'SBM1', 'EL CAMBIO DE SITUACIÓN POLICIAL SE FORMALIZA MEDIANTE:.', 'RESOLUCIÓN DE LA COMANDANCIA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, PARA OFICIALES SUBALTERNOS DE ARMAS Y DE SERVICIOS.', 'ART. 64', '181317'),
    (458, 'SUB-0458', 'SBM1', 'ES LA DEFINICIÓN DE OFICIAL DE SERVICIOS.', 'PROFESIONAL EGRESADO DE UNA UNIVERSIDAD, CON TÍTULO REGISTRADO EN LA SUPERINTENDENCIA NACIONAL DE EDUCACIÓN SUPERIOR UNIVERSITARIA (SUNEDU) E INSCRITO EN EL COLEGIO PROFESIONAL RESPECTIVO, CUANDO CORRESPONDA, QUE SE INCORPORA A LA POLICÍA NACIONAL DEL PERÚ MEDIANTE CONCURSO PÚBLICO', 'TITULO PRELIMINAR ART. 3 Num. 22', '181318'),
    (459, 'SUB-0459', 'SBM1', 'PARA SER DESIGNADOS COMO AGREGADO POLICIAL, LOS OFICIALES GENERALES Y CORONELES DE ARMAS DEBEN SER EGRESADOS:.', 'DEL PROGRAMA DE ALTO MANDO EN ORDEN INTERNO Y DESARROLLO NACIONAL DEL INSTITUTO DE ALTOS ESTUDIOS POLICIALES O EQUIVALENTE DEL PAIS O EL EXTRANJERO.', 'ART. 35', '181319'),
    (460, 'SUB-0460', 'SBM1', 'EL GRADO DE SUBOFICIAL BRIGADIER, ESTA CONSIDERADO DENTRO DE LA JERARQUIA DE:.', 'SUBOFICIALES SUPERIORES. Decreto Legislativo 1149', 'ART. 13', '181320'),
    (461, 'SUB-0461', 'SBM1', 'LOS OFICIALES Y SUBOFICIALES DE SERVICIOS SERÁN ASIGNADOS, REASIGNADOS O DESTACADOS SEGÚN LAS NECESIDADES DEL SERVICIO EN CARGOS QUE TENGAN RELACIÓN DIRECTA CON ....', 'LA ESPECIALIDAD FUNCIONAL, PROFESIÓN O CARRERA TÉCNICA CON LA QUE FUERON DADOS DE ALTA', 'ART. 28', '181321'),
    (462, 'SUB-0462', 'SBM1', 'SITUACIÓN POLICIAL: EL PERSONAL DE LA POLICÍA NACIONAL DEL PERU SE CLASIFICA:.', 'EN ATENCION A LA NATURALEZA DE SUS FUNCIONES.', 'ART. 62', '181322'),
    (463, 'SUB-0463', 'SBM1', 'EL PERSONAL NOMBRADO EN COMISION DE SERVICIO EN EL EXTRANJERO, POR UN PERIODO MAYOR DE SEIS (6) MESES, DEBE CUMPLIR CON EL TIEMPO MINIMO COMPENSATORIO DE:.', 'DOS (02) VECES LA DURACION DE LA COMISION.', 'ART. 67', '181323'),
    (464, 'SUB-0464', 'SBM1', 'ASIGNACION DE CARGOS EN LAS AGREGADURIAS POLICIALES: ES EL CARGO QUE PUEDE SER OCUPADO POR SUBOFICIALES SUPERIORES, BRIGADIERES O TECNICO DE PRIMERA DE ARMAS:.', 'PERSONAL AUXILIAR.', 'ART. 35', '181324'),
    (465, 'SUB-0465', 'SBM1', 'ES UNO DE LOS REQUISITOS PARA SER ASIGNADO EN COMISIÓN DEL SERVICIO O MISIÓN DE ESTUDIOS EN EL EXTRANJERO:.', 'TENER LA CALIFICACIÓN EN LA LISTA ANUAL DE RENDIMIENTO PROFESIONAL O TÉCNICO DE SOBRESALIENTE EN LOS DOS (2) ÚLTIMOS AÑOS', 'ART. 34', '181325'),
    (466, 'SUB-0466', 'SBM1', 'LA ASIGNACION Y REASIGNACION DE LOS OFICIALES SUPERIORES, SE APRUEBA POR.', 'RESOLUCIÓN MINISTERIAL.', 'ART. 28', '181326'),
    (467, 'SUB-0467', 'SBM1', 'UNA DE LAS CALIFICACIONES DE LAS CIRCUNSTANCIAS DEL SERVICIO EN LA QUE PARTICIPA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ ES EL ACTO DEL SERVICIO, QUE SE DEFINE COMO:.', 'ACCION QUE DESARROLLA EL PERSONAL EN CUMPLIMIENTO DE SUS FUNCIONES, DEBERES U ORDEN SUPERIOR, EN TODO MOMENTO O CIRCUNSTANCIA.', 'ART. 63', '181327'),
    (468, 'SUB-0468', 'SBM1', 'NO ESTAR SOMETIDO A PROCEDIMIENTO ADMINISTRATIVO DISCIPLINARIO COMO PRESUNTO INFRACTOR. ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS PARA:.', 'SER ASIGNADO EN COMISIÓN DEL SERVICIO O MISIÓN DE ESTUDIOS EN EL EXTRANJERO.', 'ART. 34', '181328'),
    (469, 'SUB-0469', 'SBM1', 'ESTÁ CONSTITUIDO POR LA PLATAFORMA OPERATIVA ELECTRÓNICA A CARGO DE LA DIRECCIÓN EJECUTIVA DE PERSONAL, DESTINADA AL REGISTRO, PROCESAMIENTO Y SUMINISTRO DE INFORMACIÓN DEL PERSONAL, CON LA FINALIDAD DE APOYAR LA ADMINISTRACIÓN DE LA CARRERA. ESTE ENUNCIADO CORRESPONDE A.', 'SISTEMA INTEGRADO DE GESTIÓN DE LA CARRERA', 'ART. 8', '181329'),
    (470, 'SUB-0470', 'SBM1', 'SE CONSIDERA DESDE LA FECHA EN QUE ESTE PERSONAL ES DADO DE ALTA A LA INSTITUCIÓN POR EL PERSONAL DE ARMAS Y DE SERVICIO:.', 'EL EMPLEO REAL Y EFECTIVO DESEMPEÑADO', 'ART. 66', '181330'),
    (471, 'SUB-0471', 'SBM1', 'ESTA CONSIDERADO COMO UN INSTRUMENTO DE GESTION ADMINISTRATIVA PARA LA ASIGNACION DE CARGOS:.', 'CLASIFICADOR DE CARGOS. Decreto Legislativo 1149', 'ART. 27', '181331'),
    (472, 'SUB-0472', 'SBM1', 'TITULO TÉCNICO DE INSTITUTO SUPERIORES, ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS DE ASIMILACION PARA:.', 'SUBOFICIAL DE SERVICIOS.', 'ART. 19', '181332'),
    (473, 'SUB-0473', 'SBM1', 'NO ESTAR COMPRENDIDO EN LOS CUATRO (04) AÑOS PRÓXIMOS PARA PASAR A LA SITUACIÓN DE RETIRO POR LAS CAUSALES DE: A. LÍMITE EN EL GRADO B. CUMPLIR CUARENTA (40) AÑOS DE TIEMPO DE SERVICIOS ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS PARA:.', 'SER ASIGNADO EN COMISIÓN DEL SERVICIO O MISIÓN DE ESTUDIOS EN EL EXTRANJERO', 'ART. 34', '181333'),
    (474, 'SUB-0474', 'SBM1', 'ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO:.', 'PERTENECER A LA ESPECIALIDAD FUNCIONAL CON UN MÍNIMO DE DOS (02) AÑOS DE EXPERIENCIA, RELACIONADO CON EL OBJETO DE LA COMISIÓN O MISIÓN DE ESTUDIOS', 'ART. 34', '181334'),
    (475, 'SUB-0475', 'SBM1', 'SITUACIÓN DE ACTIVIDAD EN CUADROS. CONDICIÓN EN LA QUE EL PERSONAL DE LA POLICIA NACIONAL DEL PERU SE ENCUENTRA DENTRO DEL SERVICIO, CON EMPLEO Y CARGO, EN:.', 'EN VACACIONES, LICENCIA, PERMISO O FRANCO.', 'ART. 71', '181335'),
    (476, 'SUB-0476', 'SBM1', 'EL PERIODO DE ASIMILACION DE DOS (02) AÑOS, LE CORRESPONDE A LOS...', 'OFICIALES Y SUBOFICIALES DE SERVICIOS', 'ART. 19 Num. 2', '181336'),
    (477, 'SUB-0477', 'SBM1', 'EL PROCESO DE SELECCION SE EJECUTA EN FUNCION A LOS REQUISITOS ESTABLECIDOS EN LA PRESENTE NORMA Y AL PERFIL OCUPACIONAL DISEÑADO PARA EL CARGO, TENIENDO EN CUENTA LOS FACTORES SIGUIENTES: EVALUACION ANUAL DEL DESEMPEÑO, EVALUACION DEL DESARROLLO PROFESIONAL O TECNICO, EVALUACION DE LA FORMACION ACADEMICA Y.', 'EVALUACION ANUAL DE DISCIPLINA.', 'ART. 35', '181338'),
    (478, 'SUB-0478', 'SBM1', 'ESTUDIA, EVALUA Y EMITE OPINION PARA EL OTORGAMIENTO DE INCENTIVOS:.', 'EL CONSEJO DE INVESTIGACIÓN.', 'ART. 40', '181339'),
    (479, 'SUB-0479', 'SBM1', 'EL GRADO CONFERIDO AL PERSONAL POLICIAL TIENE...', 'CARACTER VITALICIO', 'ART. 25', '181340'),
    (480, 'SUB-0480', 'SBM1', 'LOS HONORES, TRATAMIENTO, PREEMINENCIAS, PRERROGATIVAS, REMUNERACIONES, BONIFICACIONES Y DEMAS GOCES Y BENEFICIOS DETERMINADOS POR LAS LEYES Y REGLAMENTOS RESPECTIVOS, ESTAN CONSIDERADOS COMO..', 'ATRIBUTOS INHERENTES AL GRADO DEL PERSONAL POLICIAL', 'ART. 25', '181341'),
    (481, 'SUB-0481', 'SBM1', 'EL EMPLEO ESTA CONSIDERADO COMO:.', 'LA CONDICION LABORAL DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN SITUACION DE ACTIVIDAD EN FUNCION A SU CATEGORIA Y GRADO.', 'ART. 23', '181342'),
    (482, 'SUB-0482', 'SBM1', 'ES UN REQUISITO PARA SOLICITAR EL RETORNO A LA SITUACIÓN DE ACTIVIDAD:.', 'ESTAR PSICOSOMÁTICAMENTE APTO PARA EL SERVICIO POLICIAL, ACREDITADO POR LA DIRECCIÓN DE SANIDAD DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 81', '181343'),
    (483, 'SUB-0483', 'SBM1', 'MEDIANTE LA EXPEDICION DE LA RESOLUCION ADMINISTRATIVA RESPECTIVA, POR HABER OBTENIDO LA EFECTIVIDAD EN EL GRADO DE MAYOR DE SERVICIOS ESTA CONSIDERADO COMO:.', 'INICIO DE LA CARRERA.', 'ART. 15', '181344'),
    (484, 'SUB-0484', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU SE CLASIFICA EN ATENCION A SU CONDICION POLICIAL EN:.', 'PERSONAL EFECTIVO Y PERSONAL ASIMILADO.', 'ART. 62', '181345'),
    (485, 'SUB-0485', 'SBM1', 'ES EL PROFESIONAL EGRESADO DE LA ESCUELA DE OFICIALES DE LA POLICIA NACIONAL DEL PERU, EL:.', 'OFICIAL DE ARMAS.', 'TITULO PRELIMINAR ART. 3 Num. 21', '181346'),
    (486, 'SUB-0486', 'SBM1', 'EL ESCALAFON POLICIAL, ES EL REGISTRO EN EL QUE SE INSCRIBE AL PERSONAL EN SITUACION DE ACTIVIDAD, TOMANDO EN CUENTA:', 'SU CATEGORÍA, JERARQUÍA, GRADO Y ANTIGÜEDAD.', 'ART. 26', '181347'),
    (487, 'SUB-0487', 'SBM1', 'EL FALLECIMIENTO Y EL PASE A LA SITUACIÓN DE RETIRO, SON CAUSALES DE:.', 'TÉRMINO DE LA CARRERA DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU.', 'ART. 60', '181348'),
    (488, 'SUB-0488', 'SBM1', 'ES DESEMPEÑADO EN CONDICIÓN DE TITULAR, ENCARGADO E INTERINO SEGÚN EL CASO. ESTE ENUNCIADO CORRESPONDE A:.', 'EL CARGO.', 'ART. 29', '181349'),
    (489, 'SUB-0489', 'SBM1', 'SITUACIÓN DE ACTIVIDAD FUERA DE CUADROS:.', 'ENFERMO O LESIONADO POR EL PERÍODO COMPRENDIDO ENTRE SEIS (6) MESES A DOS (2) AÑOS.', 'ART. 72', '181351'),
    (490, 'SUB-0490', 'SBM1', 'EN LA CARRERA DEL PERSONAL, LA CAPACITACIÓN, SUBESPECIALIZACIÓN Y PERFECCIONAMIENTO, ESTA CONSIDERADO COMO UN:.', 'PROCESO TÉCNICO', 'ART. 14 Num. 2', '181352'),
    (491, 'SUB-0491', 'SBM1', 'LA ASIGNACION EN MISIÓN DE ESTUDIOS SE REALIZA MEDIANTE:.', 'CONCURSO DE SELECCION ENTRE EL PERSONAL QUE CUMPLA LOS REQUISITOS PREVISTOS, DE CONFORMIDAD AL REGLAMENTO RESPECTIVO.', 'ART. 34', '181353'),
    (492, 'SUB-0492', 'SBM1', 'ES EL REGISTRO EN EL QUE SE INSCRIBE AL PERSONAL EN SITUACION DE ACTIVIDAD, TOMANDO EN CUENTA SU CATEGORIA, JERARQUIA, GRADO Y ANTIGÜEDAD', 'ESCALAFÓN POLICIAL', 'ART. 26', '181354'),
    (493, 'SUB-0493', 'SBM1', 'DEL CURSO DE ADAPTACION INSTITUCIONAL: SE DESARROLLA DURANTE LOS TRES (03) PRIMEROS MESES DEL PERIODO DE ASIMILACION CON CARACTER OBLIGATORIO. SU APROBACION CONSTITUYE:.', 'REQUISITO PARA CONTINUAR EN LA CONDICION DE ASIMILADO.', 'ART. 19', '181355'),
    (494, 'SUB-0494', 'SBM1', 'EL PERSONAL NOMBRADO EN COMISION DE SERVICIO EN EL EXTRANJERO, DEBE CUMPLIR CON EL TIEMPO MINIMO COMPENSATORIO DE DOS (02) VECES LA DURACION DE LA COMISION, CUANDO ESTA SEA POR UN PERIODO:.', 'MAYOR DE SEIS (6) MESES.', 'ART. 67', '181356'),
    (495, 'SUB-0495', 'SBM1', 'UNA DE LAS CALIFICACIONES DE LAS CIRCUNSTANCIAS DEL SERVICIO EN LA QUE PARTICIPA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ ES LA ACCIÓN DE ARMAS, QUE SE DEFINE COMO:.', 'PARTICIPACION DEL PERSONAL EN ENFRENTAMIENTO ARMADO DURANTE EL CUMPLIMIENTO DE LA FINALIDAD Y FUNCION POLICIAL.', 'ART. 63', '181358'),
    (496, 'SUB-0496', 'SBM1', 'PERTENECER A LA ESPECIALIDAD FUNCIONAL CON UN MÍNIMO DE DOS (02) AÑOS DE EXPERIENCIA, RELACIONADO CON EL OBJETO DE LA COMISIÓN O MISIÓN DE ESTUDIOS. CONSTITUYE REQUISITO PARA:', 'SER ASIGNADO EN COMISIÓN DEL SERVICIO O MISIÓN DE ESTUDIOS EN EL EXTRANJERO.', 'ART. 34', '181360'),
    (497, 'SUB-0497', 'SBM1', 'ASIGNACIÓN DE CARGOS EN LAS AGREGADURÍAS POLICIALES: ES EL CARGO QUE PUEDE SER OCUPADO POR COMANDANTES O MAYORES DE ARMAS', 'AGREGADO POLICIAL ADJUNTO', 'ART. 35', '181361'),
    (498, 'SUB-0498', 'SBM1', 'ESTA CONSIDERADO COMO UNA DE LAS SUBESPECIALIDADES DE CARÁCTER TRANSVERSAL O INMERSAS', 'INTELIGENCIA', 'ART. 16 Num. 4', '181362'),
    (499, 'SUB-0499', 'SBM1', 'DE LOS PRINCIPIOS RECTORES. EL PRINCIPIO DE IGUALDAD SE REFIERE A QUE:.', 'NINGUNA DISPOSICION DEL PRESENTE DECRETO LEGISLATIVO PUEDE, EN SU APLICACIÓN, GENERAR ACTO DE DISCRIMINACION.', 'TITULO PRELIMINAR ART. 4', '181363'),
    (500, 'SUB-0500', 'SBM1', 'DEFINICION DE SITUACION POLICIAL.-ES LA CONDICION EN QUE SE ENCUENTRA EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN SITUACION DE:.', 'RETIRO.', 'ART. 61', '181364')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

