INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 501 a 600
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (501, 'SUB-0501', 'SBM1', 'LA CARRERA DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, TERMINA POR LA SIGUIENTE CAUSAL:.', 'FALLECIMIENTO.', 'ART. 60', '181365'),
    (502, 'SUB-0502', 'SBM1', 'ESTA CONSIDERADO COMO UNA CAUSAL DE ASIGNACION Y REASIGNACION DE CARGO CUMPLIR LOS OFICIALES DE ARMAS EL LIMITE DE PERMANENCIA DE:.', 'DOS (02) AÑOS CONSECUTIVOS EN EL CARGO DE JEFE EN ZONA DE FRONTERA.', 'ART. 30', '181366'),
    (503, 'SUB-0503', 'SBM1', 'LAS LISTAS DEL RENDIMIENTO PROFESIONAL O TÉCNICO SE PUBLICAN ANUALMENTE EN:.', 'EL MES DE MARZO.', 'ART. 37', '181367'),
    (504, 'SUB-0504', 'SBM1', 'ESTA CONSIDERADO COMO UNA CAUSAL DE ASIGNACION Y REASIGNACION DE CARGO:.', 'CUMPLIR LOS OFICIALES DE ARMAS EL LIMITE DE PERMANENCIA DE DOS (02) AÑOS CONSECUTIVOS EN EL CARGO DE EDECAN O ENCONTRARSE APTO PARA EL ASCENSO AL GRADO INMEDIATO SUPERIOR, AUN CUANDO TENGA MENOS DE DOS (02) AÑOS EN EL CARGO DE EDECAN', 'ART. 30', '181368'),
    (505, 'SUB-0505', 'SBM1', 'EL CAMBIO DE SITUACION POLICIAL SE FORMALIZA MEDIANTE:.', 'RESOLUCIÓN DE LA DIRECCIÓN DE RECURSOS HUMANOS DE LA POLICÍA NACIONAL DEL PERÚ, PARA TODOS LOS GRADOS EN LAS CATEGORÍAS DE SUBOFICIALES DE ARMAS Y DE SERVICIOS.', 'ART. 64', '181369'),
    (506, 'SUB-0506', 'SBM1', 'ESTA CONSIDERADO COMO UNA DE LAS ESPECIALIDADES FUNCIONALES QUE EJERCE EL PERSONAL DE ARMAS:.', 'INVESTIGACION CRIMINAL.', 'ART. 16 Num. 2', '181370'),
    (507, 'SUB-0507', 'SBM1', 'LOS INCENTIVOS, ESTA CONSIDERADO COMO UN:.', 'PROCESO TECNICO: .', 'ART. 14 Num. 5', '181371'),
    (508, 'SUB-0508', 'SBM1', 'CUADRO DE ORGANIZACION, CUADRO DE PERSONAL Y CLASIFICADOR DE CARGOS, ESTAN CONSIDERADOS COMO:.', 'INSTRUMENTOS DE GESTION ADMINISTRATIVA PARA LA ASIGNACION DE CARGOS. Decreto Legislativo 1149', 'ART. 27', '181372'),
    (509, 'SUB-0509', 'SBM1', 'LA ASIGNACION DE CARGOS EN LAS AGREGADURIAS POLICIALES SE PRODUCE, SEGUN LA ETAPA DE EVALUACION Y SELECCION: SE SOMETE AL SIGUIENTE PROCEDIMIENTO: A) EVALUA Y PROPONE AL DIRECTOR GENERAL LA RELACION DE CANDIDATOS, PARA SER COMISIONADOS EN SERVICIO A LAS AGREGADURIAS POLICIALES. UNA COMISION PRESIDIDA POR:.', 'EL JEFE DE ESTADO MAYOR GENERAL.', 'ART. 35', '181373'),
    (510, 'SUB-0510', 'SBM1', 'LOS INCENTIVOS TIENEN CARACTER MOTIVADOR Y SON OTORGADOS POR.', 'LOS DIVERSOS NIVELES DEL COMANDO INSTITUCIONAL.', 'ART. 39', '181374'),
    (511, 'SUB-0511', 'SBM1', 'DISEÑAR LA ESTRUCTURA Y ORGANIZACIÓN DE LA CARRERA, CON EL FIN DE ESTABLECER LAS OPORTUNIDADES DEL DESARROLLO PERSONAL, PROFESIONAL Y TÉCNICO, CON ÉNFASIS EN LA DISCIPLINA Y LOS MÉRITOS.- CORRESPONDE A:.', 'FINALIDAD.', 'ART. 11', '181375'),
    (512, 'SUB-0512', 'SBM1', 'ES EL PERIODO EN EL QUE PERMANECE EL PERSONAL PROFESIONAL Y TÉCNICO QUE SE INCORPORA A LA POLICÍA NACIONAL DEL PERÚ, HASTA LA OBTENCIÓN DE LA EFECTIVIDAD EN EL GRADO.- ESTE ENUNCIADO CORRESPONDE A:.', 'ASIMILACIÓN.', 'ART. 19', '181377'),
    (513, 'SUB-0513', 'SBM1', 'LA DEFINICIÓN DE LA HOJA ANUAL DE RENDIMIENTO PROFESIONAL O TÉCNICO.', 'DOCUMENTO DE CALIFICACION INDIVIDUAL DEL PERSONAL, QUE DETALLA SU NOTA ANUAL DE RENDIMIENTO PROFESIONAL O TECNICO', 'TITULO PRELIMINAR ART. 3. Num. 13', '181378'),
    (514, 'SUB-0514', 'SBM1', 'LA LEY DE LA CARRERA Y SITUACIÓN DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, ES EL:.', 'DECRETO LEGISLATIVO 1149.', 'DECRETO LEGISLATIVO N°1149', '181379'),
    (515, 'SUB-0515', 'SBM1', 'EL EMPLEO ESTA CONSIDERADO COMO LA:.', 'CONDICION LABORAL DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN SITUACION DE ACTIVIDAD EN FUNCION A SU CATEGORIA Y GRADO.', 'ART. 23', '181380'),
    (516, 'SUB-0516', 'SBM1', 'ESTUDIA, EVALÚA Y EMITE OPINIÓN PARA EL OTORGAMIENTO DE INCENTIVO, EL:.', 'CONSEJO DE INVESTIGACIÓN.', 'ART. 40', '181381'),
    (517, 'SUB-0517', 'SBM1', 'ES LA DEFINICION DE SUBOFICIAL DE ARMAS.', 'PERSONAL EGRESADO DE LAS ESCUELAS TECNICO SUPERIORES DE SUBOFICIALES DE LA POLICIA NACIONAL DEL PERU.', 'TITULO PRELIMINAR ART. 3 Num. 29', '181382'),
    (518, 'SUB-0518', 'SBM1', 'ES LA CONDICIÓN EN QUE SE ENCUENTRA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD, DISPONIBILIDAD O RETIRO:.', 'SITUACIÓN POLICIAL.', 'ART. 61', '181383'),
    (519, 'SUB-0519', 'SBM1', 'LA DIRECCIÓN EJECUTIVA DE PERSONAL DIFUNDIRÁ A NIVEL NACIONAL EL PROGRAMA DE BECAS NACIONALES E INTERNACIONALES, QUE SERÁN ASIGNADAS MEDIANTE:.', 'CONCURSO.', 'ART. 22', '181384'),
    (520, 'SUB-0520', 'SBM1', 'ES LA CONDICIÓN DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN CUADROS Y FUERA DE CUADROS', 'SITUACIÓN DE ACTIVIDAD.', 'ART. 70', '181385'),
    (521, 'SUB-0521', 'SBM1', 'EN NINGÚN CASO PUEDEN COMANDAR UNIDADES OPERATIVAS, SE REFIERE A:.', 'OFICIALES Y SUBOFICIALES DE SERVICIOS', 'ART. 28', '181386'),
    (522, 'SUB-0522', 'SBM1', 'ÁMBITO DE APLICACIÓN.- LAS DISPOSICIONES DEL PRESENTE DECRETO LEGISLATIVO ALCANZA A TODOS:', 'LOS OFICIALES Y SUBOFICIALES DE ARMAS Y DE SERVICIOS DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD, DISPONIBILIDAD Y RETIRO', 'ART. 2', '181387'),
    (523, 'SUB-0523', 'SBM1', 'UBICAR AL PERSONAL EN EL NIVEL QUE LE CORRESPONDA EN LAS LISTAS DE RENDIMIENTO PROFESIONAL Y TECNICO, ES UNO DE LOS OBJETIVOS DE:.', 'LA EVALUACION DEL DESEMPEÑO DEL PERSONAL.', 'ART. 36', '181388'),
    (524, 'SUB-0524', 'SBM1', 'ES EL NIVEL QUE CORRESPONDE AL PERSONAL, TENIENDO EN CUENTA SU FORMACION Y PROCEDENCIA. CORRESPONDE A LA DEFINICION DE:.', 'CATEGORIA.', 'TITULO PRELIMINAR ART. 3 Num. 4', '181389'),
    (525, 'SUB-0525', 'SBM1', 'NO REGISTRAR INFRACCIONES GRAVES O MUY GRAVES EN EL GRADO, CONFORME A LO SEÑALADO EN LA LEY DE RÉGIMEN DISCIPLINARIO DE LA POLICÍA NACIONAL DEL PERÚ, NI SENTENCIA JUDICIAL CONDENATORIA EN LOS ÚLTIMOS CINCO (05) AÑOS. ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS PARA:.', 'SER ASIGNADO EN COMISIÓN DEL SERVICIO O MISIÓN DE ESTUDIOS EN EL EXTRANJERO.', 'ART. 34', '181390'),
    (526, 'SUB-0526', 'SBM1', 'ES LA DEFINICION DE CUADRO DE MERITOS DE ASCENSOS.', 'DOCUMENTO EN EL CUAL SE INSCRIBE A LOS CANDIDATOS EN ORDEN DECRECIENTE EN FUNCION AL PUNTAJE ALCANZADO EN SU RESPECTIVO GRADO.', 'TITULO PRELIMINAR ART. 3 Num. 6', '181391'),
    (527, 'SUB-0527', 'SBM1', 'ESTA CONSIDERADO COMO UNA ACCION DE DESPLAZAMIENTO DE CARGO:.', 'LA ASIGNACION.', 'ART. 28', '181392'),
    (528, 'SUB-0528', 'SBM1', 'MEDIANTE LA EXPEDICION DE LA RESOLUCION ADMINISTRATIVA RESPECTIVA, POR HABER OBTENIDO LA EFECTIVIDAD EN EL GRADO DE MAYOR DE SERVICIOS ESTA CONSIDERADO COMO', 'INICIO DE LA CARRERA', 'ART. 15', '181393'),
    (529, 'SUB-0529', 'SBM1', 'EL PASE A LA SITUACIÓN DE RETIRO DEL PERSONAL POLICIAL POR LA CAUSAL DE RENOVACIÓN, DEBE SER NOTIFICADO:', 'CONFORME A LEY', 'ART. 86', '181394'),
    (530, 'SUB-0530', 'SBM1', 'RESPECTO A LA ASIGNACIÓN DEL CARGO PARA AGREGADURÍAS POLICIALES, EL CARGO DE AGREGADO POLICIAL, ES DESEMPEÑADO POR:.', 'OFICIALES GENERALES O CORONELES DE ARMAS.', 'ART. 35', '181395'),
    (531, 'SUB-0531', 'SBM1', 'EL PRESENTE DECRETO LEGISLATIVO NORMA LA CARRERA Y SITUACIÓN DEL PERSONAL DE LA POLICIA NACIONAL DEL PERÚ, CON EL PROPÓSITO DE GARANTIZAR EL DESARROLLO PERSONAL, PROFESIONAL Y TÉCNICO DE SUS INTEGRANTES, PARA EL:.', 'CUMPLIMIENTO DE LOS OBJETIVOS INSTITUCIONALES AL SERVICIO DE LA SOCIEDAD.', 'TITULO PRELIMINAR ART. 1', '181396'),
    (532, 'SUB-0532', 'SBM1', 'MEDIANTE LA EXPEDICION DE LA RESOLUCION ADMINISTRATIVA RESPECTIVA POR HABER OBTENIDO LA EFECTIVIDAD COMO CAPITAN DE SERVICIOS ESTA CONSIDERADO COMO', 'INICIO DE LA CARRERA', 'ART. 15', '181397'),
    (533, 'SUB-0533', 'SBM1', 'SON ACCIONES DE DESPLAZAMIENTO DE CARGOS:.', 'DESTAQUE.', 'ART. 28', '181398'),
    (534, 'SUB-0534', 'SBM1', 'ESTA CONSIDERADO COMO UN INSTRUMENTO DE GESTION ADMINISTRATIVA PARA LA ASIGNACION DE CARGOS:.', 'CUADRO DE PERSONAL.', 'ART. 27', '181400'),
    (535, 'SUB-0535', 'SBM1', 'APORTAR INDICADORES OBJETIVOS PARA LOS PROCESOS DE ASCENSOS, ASIGNACION DE CARGO, OTORGAMIENTO DE INCENTIVOS Y EVALUACION PARA LA PERMANENCIA EN LA INSTITUCION, ES UNO DE LOS OBJETIVOS DE LA:.', 'EVALUACIÓN DEL DESEMPEÑO DEL PERSONAL.', 'ART. 36', '181401'),
    (536, 'SUB-0536', 'SBM1', 'ESTA CONSIDERADO COMO UN PROCESO TECNICO DE LA CARRERA:.', 'EMPLEO Y CARGO.', 'ART. 14 Num. 3', '181402'),
    (537, 'SUB-0537', 'SBM1', 'RENOVACIÓN DE CUADROS POR PROCESO REGULAR: LA PROPUESTA DE RENOVACIÓN DE OFICIALES GENERALES ES:.', 'PRESENTADA POR ESCRITO POR EL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 86', '181403'),
    (538, 'SUB-0538', 'SBM1', 'LA OBSERVANCIA DE LOS PRINCIPIOS RECTORES NO IMPIDE LA APLICACIÓN DE OTROS PRINCIPIOS FAVORABLES PARA EL DESARROLLO DEL PERSONAL Y DE LA INSTITUCION. ESTE ENUNCIADO SE REFIERE A:.', 'APLICACIÓN DE OTROS PRINCIPIOS.', 'TITULO PRELIMINAR ART. 5', '181404'),
    (539, 'SUB-0539', 'SBM1', 'LA DIRECCION EJECUTIVA DE PERSONAL ES EL ORGANO RESPONSABLE DEL PROCESO DE EVALUACION DEL DESEMPEÑO QUE SE REALIZA.', 'ANUALMENTE.', 'ART. 38', '181405'),
    (540, 'SUB-0540', 'SBM1', 'FACILITA LOS PROCESOS DE ASCENSO, ASIGNACION DE CARGO Y EVALUACION DE LA PERMANENCIA EN EL INSTITUTO, CALCULANDO EN CADA CASO EL PROMEDIO ARITMETICO DE LA NOTA DE EVALUACION ANUAL Y LA NOTA DE DISCIPLINA ANUAL. CORRESPONDE A:.', 'LAS LISTAS DEL RENDIMIENTO PROFESIONAL O TECNICO.', 'ART. 37', '181406'),
    (541, 'SUB-0541', 'SBM1', 'PROFESIONAL EGRESADO DE UNA UNIVERSIDAD, CON TÍTULO REGISTRADO EN LA SUPERINTENDENCIA NACIONAL DE EDUCACIÓN SUPERIOR UNIVERSITARIA (SUNEDU) E INSCRITO EN EL COLEGIO PROFESIONAL RESPECTIVO, CUANDO CORRESPONDA, QUE SE INCORPORA A LA POLICÍA NACIONAL DEL PERÚ MEDIANTE CONCURSO PÚBLICO, DE ACUERDO A LAS NECESIDADES INSTITUCIONALES:.', 'OFICIAL DE SERVICIOS.', 'TITULO PRELIMINAR ART. 3 Num. 22', '181407'),
    (542, 'SUB-0542', 'SBM1', 'CORRESPONDE A UNA CATEGORÍA:.', 'SUBOFICIALES DE SERVICIOS.', 'ART. 13', '181408'),
    (543, 'SUB-0543', 'SBM1', 'EL ALTA COMO ALFEREZ O SUBOFICIAL DE TERCERA DE ARMAS; O POR HABER OBTENIDO LA EFECTIVIDAD EN LOS GRADOS DE MAYOR, CAPITAN O SUBOFICIAL DE TERCERA DE SERVICIOS, SEGUN CORRESPONDA; EN AMBOS CASOS MEDIANTE LA EXPEDICION DE LA RESOLUCION ADMINISTRATIVA RESPECTIVA, CORRESPONDE AL:', 'INICIO DE LA CARRERA', 'ART. 15', '181409'),
    (544, 'SUB-0544', 'SBM1', 'EL PROCESO DE SELECCIÓN SE EJECUTA EN FUNCIÓN A LOS REQUISITOS ESTABLECIDOS EN LA PRESENTE NORMA Y AL PERFIL OCUPACIONAL DISEÑADO PARA EL CARGO, TENIENDO EN CUENTA LOS FACTORES SIGUIENTES: EVALUACIÓN ANUAL DEL DESEMPEÑO, EVALUACIÓN DE LA FORMACIÓN ACADÉMICA, EVALUACIÓN ANUAL DE DISCIPLINA Y.', 'EVALUACION DEL DESARROLLO PROFESIONAL O TECNICO.', 'ART. 35', '181410'),
    (545, 'SUB-0545', 'SBM1', 'SITUACIÓN POLICIAL: EL PERSONAL DE LA POLICÍA NACIONAL DEL PERU SE CLASIFICA:.', 'EN ATENCION A SU CONDICION POLICIAL.', 'ART. 62', '181411'),
    (546, 'SUB-0546', 'SBM1', 'SITUACIÓN DE ACTIVIDAD: ES LA CONDICIÓN DE ACTIVIDAD DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU, EN:.', 'CUADROS Y FUERA DE CUADROS.', 'ART. 70', '181412'),
    (547, 'SUB-0547', 'SBM1', 'DE LOS PRINCIPIOS RECTORES. EL PRINCIPIO DE MERITOCRACIA SE REFIERE A QUE:.', 'EL INGRESO, LA PERMANENCIA Y LOS ASCENSOS EN LA CARRERA, SE FUNDAMENTAN EN LOS MERITOS Y EN LAS CAPACIDADES PERSONALES, PROFESIONALES Y TECNICAS', 'TITULO PRELIMINAR ART. 4 Num. 3', '181413'),
    (548, 'SUB-0548', 'SBM1', 'EL INICIO DE LA CARRERA ESTA CONSIDERADO COMO UN...', 'PROCESO TECNICO', 'ART. 14 Inc. 1', '181414'),
    (549, 'SUB-0549', 'SBM1', 'DE LOS PRINCIPIOS RECTORES. EL PRINCIPIO DE IMPARCIALIDAD SE REFIERE A QUE:.', 'LAS EVALUACIONES ESTAN EXENTAS DE TODO INTERES AJENO AL INSTITUCIONAL Y SON IMPARCIALES EN SU APLICACIÓN', 'TITULO PRELIMINAR ART. 4 Num. 2', '181415'),
    (550, 'SUB-0550', 'SBM1', 'PARA EFECTO DE LA PRESENTE NORMA, LA PALABRA PERSONAL SE REFIERE:.', 'A LOS OFICIALES Y SUBOFICIALES DE ARMAS Y SERVICIOS DE LA POLICIA NACIONAL DEL PERU .', 'TITULO PRELIMINAR ART. 3 Num. 23', '181416'),
    (551, 'SUB-0551', 'SBM1', 'EL CLASIFICADOR DE CARGOS ESTA CONSIDERADO COMO UN:', 'INSTRUMENTO DE GESTION ADMINISTRATIVA PARA LA ASIGNACIÓN DE CARGOS.', 'ART. 27', '181418'),
    (552, 'SUB-0552', 'SBM1', 'CUADRO DE ORGANIZACION, CUADRO DE PERSONAL Y CLASIFICADOR DE CARGOS, ESTAN CONSIDERADOS COMO.', 'INSTRUMENTOS DE GESTION ADMINISTRATIVA PARA LA ASIGNACION DE CARGOS', 'ART. 27', '181419'),
    (553, 'SUB-0553', 'SBM1', 'SON CONSIDERADAS COMO ACCIONES DE DESPLAZAMIENTO Y FORMALIZACIÓN DE CARGOS.', 'LA ASIGNACION, LA REASIGNACION Y EL DESTAQUE.', 'ART. 28', '181420'),
    (554, 'SUB-0554', 'SBM1', 'ESTA CONSIDERADO COMO UNA ACCION DE DESPLAZAMIENTO DE CARGO:', 'LA ASIGNACION.', 'ART. 28', '181421'),
    (555, 'SUB-0555', 'SBM1', 'ESTA CONSIDERADO COMO UNA ACCION DE DESPLAZAMIENTO Y FORMALIZACIÓN DE CARGOS:', 'EL DESTAQUE.', 'ART. 28', '181422'),
    (556, 'SUB-0556', 'SBM1', 'SE APRUEBA POR RESOLUCIÓN SUPREMA', 'LA ASIGNACION Y REASIGNACION DE LOS OFICIALES GENERALES', 'ART. 28', '181423'),
    (557, 'SUB-0557', 'SBM1', 'SE APRUEBA POR RESOLUCIÓN MINISTERIAL:', 'LA ASIGNACION Y REASIGNACION DE LOS OFICIALES SUPERIORES', 'ART. 28', '181424'),
    (558, 'SUB-0558', 'SBM1', 'SERÁN ASIGNADOS, REASIGNADOS O DESTACADOS EN CARGOS QUE TENGAN RELACIÓN DIRECTA CON LA ESPECIALIDAD FUNCIONAL, PROFESIÓN O CARRERA TÉCNICA CON LA QUE FUERON DADOS DE ALTA, SE REFIERE A.', 'LOS SUBOFICIALES DE SERVICIOS.', 'ART. 28', '181425'),
    (559, 'SUB-0559', 'SBM1', 'EN NINGÚN CASO PUEDEN COMANDAR UNIDADES OPERATIVAS, SE REFIERE A:', 'OFICIALES Y SUBOFICIALES DE SERVICIOS.', 'ART. 28', '181426'),
    (560, 'SUB-0560', 'SBM1', 'ES DESEMPEÑADO EN CONDICIÓN DE TITULAR, ENCARGADO E INTERINO, SEGÚN EL CASO:', 'EL CARGO.', 'ART. 29', '181427'),
    (561, 'SUB-0561', 'SBM1', 'SEGUN LA ASIGNACION DE CARGOS. LOS CARGOS DE DIRECTORES, JEFES DE DIVISION Y EQUIVALENTES, JEFES DE UNIDADES, ASI COMO DE COMISARIOS, RECAEN EN:', 'OFICIALES DE ARMAS EGRESADOS DE LOS CURSOS DE PERFECCIONAMIENTO PROFESIONAL CORRESPONDIENTE A SU GRADO.', 'ART. 31', '181428'),
    (562, 'SUB-0562', 'SBM1', 'PARA OCUPAR LOS CARGOS DE DIRECTORES, JEFES DE DIVISION Y EQUIVALENTES, JEFES DE UNIDADES, ASI COMO DE COMISARIOS, LOS OFICIALES DE ARMAS DEBEN:', 'SER EGRESADOS DE LOS CURSOS DE PERFECCIONAMIENTO PROFESIONAL CORRESPONDIENTE A SU GRADO Y DE ACUERDO AL PERFIL DEL PUESTO FORMULADO POR LA POLICIA NACIONAL DEL PERU', 'ART. 31', '181429'),
    (563, 'SUB-0563', 'SBM1', 'EN LOS LUGARES QUE NO SE LOGRE CUBRIR COMISARIAS CON OFICIALES DE ARMAS, SE ASIGNARAN SUBOFICIALES DE ARMAS DE LA JERARQUIA DE:', 'SUBOFICIALES SUPERIORES DE ARMAS.', 'ART. 31', '181430'),
    (564, 'SUB-0564', 'SBM1', 'EL PERSONAL POLICIAL QUE SEA ASIGNADO A CARGOS EN ENTIDADES DIFERENTES A LA POLICIA NACIONAL DEL PERU Y EL MINISTERIO DEL INTERIOR. EL TIEMPO DE PERMANENCIA NO EXCEDERA DE:', 'DOS (02) AÑOS EN UN MISMO GRADO.', 'ART. 32', '181431'),
    (565, 'SUB-0565', 'SBM1', 'EL PERSONAL POLICIAL QUE SEA ASIGNADO A CARGOS EN ENTIDADES DIFERENTES A LA POLICIA NACIONAL DEL PERU Y EL MINISTERIO DEL INTERIOR. EL TIEMPO DE PERMANENCIA NO EXCEDERA DE:', 'CUATRO (04) AÑOS EN TODA LA CARRERA.', 'ART. 32', '181432'),
    (566, 'SUB-0566', 'SBM1', 'SON SERVICIOS O ESTUDIOS TEMPORALES DESEMPEÑADOS POR OFICIALES O SUBOFICIALES EN SITUACION DE ACTIVIDAD EN CUADROS, EN DELEGACION U ORGANISMOS EN EL EXTRANJERO, CON EL OBJETO DE FORTALECER LOS INTERESES INSTITUCIONALES Y REPRESENTAR AL PAÍS, HASTA:', 'UN PLAZO MAXIMO DE DOS (02) AÑOS.', 'ART. 33', '181433'),
    (567, 'SUB-0567', 'SBM1', 'LA COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO, SE REALIZA HASTA POR UN PLAZO MAXIMO DE :', 'DOS (02) AÑOS, SALVO CONVENIO, ACUERDO, PACTO O ANALOGOS DE CARACTER INTERNACIONAL.', 'ART. 33', '181434'),
    (568, 'SUB-0568', 'SBM1', 'EL PERSONAL AL RETORNAR DE LA MISIÓN DE ESTUDIOS EN EL EXTRANJERO, DEBE SER ASIGNADO A:', 'A UNA UNIDAD ACORDE CON LA CAPACITACIÓN RECIBIDA', 'ART. 33', '181435'),
    (569, 'SUB-0569', 'SBM1', 'REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO. LA ASIGNACION EN MISION DE ESTUDIOS SE REALIZARA MEDIANTE:', 'CONCURSO DE SELECCIÓN', 'ART. 34', '181436'),
    (570, 'SUB-0570', 'SBM1', 'PERTENECER A LA ESPECIALIDAD FUNCIONAL CON UN MINIMO DE DOS (02) AÑOS DE EXPERIENCIA, RELACIONADO CON EL OBJETO DE LA COMISION O MISION DE ESTUDIOS.CONSTITUYE REQUISITO PARA :', 'SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS. Decreto Legislativo 1149', 'ART. 34 Num. 1', '181437'),
    (571, 'SUB-0571', 'SBM1', 'ESTA CONSIDERADO COMO UNO DE LOS REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO.- TENER LA CALIFICACION EN LA LISTA ANUAL DE RENDIMIENTO PROFESIONAL O TECNICO DE SOBRESALIENTE EN:', 'LOS DOS (02) ULTIMOS AÑOS.', 'ART. 34 Num. 5', '181438'),
    (572, 'SUB-0572', 'SBM1', 'REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO. SON LOS SIGUIENTES:', 'NO ESTAR COMPRENDIDO EN LOS CUATRO (04) AÑOS PRÓXIMOS PARA PASAR A LA SITUACIÓN DE RETIRO', 'ART. 34 Num. 6', '181439'),
    (573, 'SUB-0573', 'SBM1', 'REQUISITOS PARA SER ASIGNADO EN COMISIÓN DEL SERVICIO O MISIÓN DE ESTUDIOS EN EL EXTRANJERO. SON LOS SIGUIENTES.- NO ESTAR COMPRENDIDO EN LOS CUATRO (04) PRÓXIMOS AÑOS PARA PASAR A LA SITUACIÓN RETIRO POR LAS CAUSALES DE:', 'LIMITE DE EDAD EN EL GRADO.', 'ART. 34 Num. 6 Lit. A', '181440'),
    (574, 'SUB-0574', 'SBM1', 'REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO. SON LOS SIGUIENTES.- NO ESTAR COMPROMETIDO EN LOS CUATRO (04) PROXIMOS AÑOS PARA PASAR A LA SITUACION RETIRO POR LAS CAUSALES DE:', 'CUMPLIR CUARENTA (40) AÑOS DE TIEMPO DE SERVICIOS.', 'ART. 34 Num. 6 Lit. B', '181441'),
    (575, 'SUB-0575', 'SBM1', 'REQUISITOS PARA SER ASIGNADO EN COMISION DEL SERVICIO O MISION DE ESTUDIOS EN EL EXTRANJERO. SON LOS SIGUIENTES:', 'NO REGISTRAR INFRACCIONES GRAVES O MUY GRAVES.', 'ART. 34 Num. 4', '181442'),
    (576, 'SUB-0576', 'SBM1', 'PRECEDENCIA EN EL GRADO.- LA PRECEDENCIA SE DETERMINA EN ATENCION A LOS CRITERIOS SIGUIENTES:', 'A MAYOR GRADO.', 'ART. 24 Num. 1', '181443'),
    (577, 'SUB-0577', 'SBM1', 'PRECEDENCIA EN EL GRADO.- LA PRECEDENCIA SE DETERMINA EN ATENCION A LOS CRITERIOS SIGUIENTES: A IGUALDAD DE GRADO:', 'PRIMA EL DE MAYOR TIEMPO DE SERVICIO.', 'ART. 24 Num. 2', '181444'),
    (578, 'SUB-0578', 'SBM1', 'PRECEDENCIA EN EL GRADO.- LA PRECEDENCIA SE DETERMINA EN ATENCION A LOS CRITERIOS SIGUIENTES: A IGUALDAD DE GRADO Y TIEMPO DE SERVICIO EN EL GRADO:', 'PREVALECE LA ANTIGUEDAD DEL GRADO ANTERIOR.', 'ART. 24 Num. 3', '181445'),
    (579, 'SUB-0579', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU SE CLASIFICA:', 'EN ATENCION A SU SITUACION POLICIAL EN EL SERVICIO.', 'ART. 62 Num. 1', '181446'),
    (580, 'SUB-0580', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU SE CLASIFICA:', 'EN ATENCION A LA NATURALEZA DE SUS FUNCIONES.', 'ART. 62 Num. 2', '181447'),
    (581, 'SUB-0581', 'SBM1', 'EL PERSONAL PASA A LA SITUACIÓN DE DISPONIBILIDAD POR LAS CAUSALES SIGUIENTES:', 'A SU SOLICITUD.', 'ART.74 Num. 1', '181448'),
    (582, 'SUB-0582', 'SBM1', 'EL PERSONAL PASA A LA SITUACIÓN DE DISPONIBILIDAD POR LAS CAUSALES SIGUIENTES:', 'MEDIDA DISCIPLINARIA.', 'ART.74 Num. 2', '181449'),
    (583, 'SUB-0583', 'SBM1', 'EL PERSONAL PASA A LA SITUACIÓN DE DISPONIBILIDAD POR LAS CAUSALES SIGUIENTES:', 'SENTENCIA JUDICIAL CONDENATORIA.', 'ART.74 Num. 3', '181450'),
    (584, 'SUB-0584', 'SBM1', 'EL PERSONAL PASA A LA SITUACIÓN DE DISPONIBILIDAD POR LAS CAUSALES SIGUIENTES:', 'ENFERMEDAD O LESION GRAVE.', 'ART.74 Num. 4', '181451'),
    (585, 'SUB-0585', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN ATENCION A SU SITUACION POLICIAL EN EL SERVICIO, SE CLASIFICA EN:', 'ACTIVIDAD.', 'ART. 62 Num. 1 Lit. A', '181452'),
    (586, 'SUB-0586', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN ATENCION A SU SITUACION POLICIAL EN EL SERVICIO, SE CLASIFICA EN:', 'ACTIVIDAD, DISPONIBILIDAD Y RETIRO.', 'ART. 62 Num. 1 Lit. A B Y C', '181453'),
    (587, 'SUB-0587', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU SE CLASIFICA EN ATENCION A LA NATURALEZA DE SUS FUNCIONES, EN:', 'PERSONAL DE ARMAS Y PERSONAL DE SERVICIOS.', 'ART. 62 Num. 2 Lit. A Y B', '181454'),
    (588, 'SUB-0588', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN ATENCION A LA NATURALEZA DE SUS FUNCIONES; EL PERSONAL DE ARMAS SE CLASIFICA EN:', 'OFICIALES DE ARMAS Y SUBOFICIALES DE ARMAS.', 'ART. 62 Num. 2 Lit. A', '181455'),
    (589, 'SUB-0589', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN ATENCION A LA NATURALEZA DE SUS FUNCIONES; EL PERSONAL DE SERVICIOS SE CLASIFICA EN:', 'OFICIALES DE SERVICIOS Y SUBOFICIALES DE SERVICIOS.', 'ART. 62 Num. 2 Lit. B', '181456'),
    (590, 'SUB-0590', 'SBM1', 'EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN ATENCION A SU CONDICION POLICIAL; SE CLASIFICA EN:', 'PERSONAL EFECTIVO Y PERSONAL ASIMILADO', 'ART. 62 Num. 3', '181457'),
    (591, 'SUB-0591', 'SBM1', 'ES LA CONDICION EN QUE SE ENCUENTRA EL PERSONAL DE LA POLICIA NACIONAL DEL PERU EN SITUACION DE ACTIVIDAD, DISPONIBILIDAD O RETIRO.', 'SITUACION POLICIAL.', 'ART.61', '181458'),
    (592, 'SUB-0592', 'SBM1', 'LA CARRERA DEL PERSONAL DE LA POLICIA NACIONAL DEL PERU, TERMINA POR LAS SIGUIENTES CAUSALES:', 'PASE A LA SITUACIÓN DE RETIRO.', 'ART. 60 Num. 2', '181459'),
    (593, 'SUB-0593', 'SBM1', 'DEFINICIÓN. - EL DESTAQUE ES:', 'ASIGNACIÓN A UN CARGO CON CARÁCTER TEMPORAL POR NECESIDAD DEL SERVICIO O A SOLICITUD DEL INTERESADO, POR UN PERÍODO NO MAYOR A NOVENTA (90) DÍAS CALENDARIOS.', 'ART. 3 Num. 9', '181460'),
    (594, 'SUB-0594', 'SBM1', 'EL GRADO DE TENIENTE GENERAL, ESTÁ CONSIDERADO EN LA JERARQUÍA DE:', 'OFICIALES GENERALES.', 'ART. 13 Num. 1 Lit. A', '181461'),
    (595, 'SUB-0595', 'SBM1', 'EL GRADO DE TENIENTE, ESTÁ CONSIDERADO EN LA JERARQUÍA DE:', 'OFICIALES SUBALTERNOS.', 'ART. 13 Num. 1 Lit. C', '181462'),
    (596, 'SUB-0596', 'SBM1', 'EL GRADO DE SUBOFICIAL SUPERIOR, ESTÁ CONSIDERADO EN LA JERARQUÍA DE:', 'SUBOFICIALES SUPERIORES.', 'ART. 13 Num. 3 Inc. 1', '181463'),
    (597, 'SUB-0597', 'SBM1', 'SEGUN LAS LISTAS DEL RENDIMIENTO PROFESIONAL O TECNICO, LA NOTA MAXIMA ES DE:', 'CIEN (100) PUNTOS.', 'ART. 37', '181464'),
    (598, 'SUB-0598', 'SBM1', 'LA CALIFICACION DE LAS CIRCUNSTANCIAS DEL SERVICIO EN LA QUE PARTICIPA EL PERSONAL DE LA POLICIA NACIONAL DEL PERU, ES UNA DE LAS SIGUIENTES', 'ACTO AJENO AL SERVICIO.', 'ART. 63 Num. 5', '181465'),
    (599, 'SUB-0599', 'SBM1', 'NORMA LA CARRERA Y LA SITUACIÓN DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, CON EL PROPÓSITO DE GARANTIZAR EL DESARROLLO PERSONAL, PROFESIONAL Y TÉCNICO DE SUS INTEGRANTES. SE REFIERE AL', 'OBJETO', 'TÍTULO PRELIMINAR ART. 1', '181466'),
    (600, 'SUB-0600', 'SBM1', 'PRELACIÓN EXISTENTE ENTRE EL PERSONAL, EN ATENCIÓN A SU CATEGORÍA, JERARQUÍA, GRADO Y TIEMPO DE SERVICIOS. CORRESPONDE A LA:', 'ANTIGÜEDAD.', 'TÍTULO PRELIMINAR ART. 3 Num. 1 Decreto Legislativo 1149', '181467')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

