    ('SUB-0887', 'A', 'SI HA TENIDO INTERVENCIÓN COMO ASESOR, PERITO O TESTIGO EN EL MISMO PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, O SI COMO INSTRUCTOR HUBIERE MANIFESTADO PREVIAMENTE SU PARECER SOBRE EL MISMO, DE MODO QUE PUDIERA ENTENDERSE QUE SE HA PRONUNCIADO SOBRE EL ASUNTO, SALVO LA RECTIFICACIÓN DE ERRORES O LA DECISIÓN DEL RECURSO DE RECONSIDERACIÓN.', FALSE, 1),
    ('SUB-0887', 'B', 'EXISTENCIA DE ENEMISTAD MANIFIESTA CON EL INVESTIGADO O DENUNCIANTE.', TRUE, 2),
    ('SUB-0887', 'C', 'SI ES CÓNYUGE, CONVIVIENTE, PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, CON CUALQUIERA DE LAS PARTES O CON SUS REPRESENTANTES.', FALSE, 3),
    ('SUB-0887', 'D', 'SI PERSONALMENTE, O BIEN SU CÓNYUGE, CONVIVIENTE O ALGÚN PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, TUVIERE INTERÉS EN EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO QUE SE INVESTIGA O EN OTRO SEMEJANTE, CUYA RESOLUCIÓN PUEDA INFLUIR EN LA SITUACIÓN DE AQUEL.', FALSE, 4),
    ('SUB-0887', 'E', 'CUANDO TUVIERE AMISTAD ÍNTIMA, ENEMISTAD MANIFIESTA O CONFLICTO DE INTERESES OBJETIVO CON CUALQUIERA DE LAS PARTES QUE INTERVIENEN EN EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, QUE SE HAGAN PATENTES MEDIANTE ACTITUDES O HECHOS EVIDENTES EN EL PROCEDIMIENTO.', FALSE, 5),
    ('SUB-0888', 'A', 'SI PERSONALMENTE, O BIEN SU CÓNYUGE, CONVIVIENTE O ALGÚN PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, TUVIERE INTERÉS EN EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO QUE SE INVESTIGA O EN OTRO SEMEJANTE, CUYA RESOLUCIÓN PUEDA INFLUIR EN LA SITUACIÓN DE AQUEL.', FALSE, 1),
    ('SUB-0888', 'B', 'SI HA TENIDO INTERVENCIÓN COMO ASESOR, PERITO O TESTIGO EN EL MISMO PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, O SI COMO INSTRUCTOR HUBIERE MANIFESTADO PREVIAMENTE SU PARECER SOBRE EL MISMO, DE MODO QUE PUDIERA ENTENDERSE QUE SE HA PRONUNCIADO SOBRE EL ASUNTO, SALVO LA RECTIFICACIÓN DE ERRORES O LA DECISIÓN DEL RECURSO DE RECONSIDERACIÓN.', FALSE, 2),
    ('SUB-0888', 'C', 'SER DEUDOR, ACREEDOR, FIADOR DEL INVESTIGADO O DEL DENUNCIANTE, O TENER INTERESES COMUNES CON ESTOS ÚLTIMOS.', TRUE, 3),
    ('SUB-0888', 'D', 'CUANDO TUVIERE AMISTAD ÍNTIMA, ENEMISTAD MANIFIESTA O CONFLICTO DE INTERESES OBJETIVO CON CUALQUIERA DE LAS PARTES QUE INTERVIENEN EN EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, QUE SE HAGAN PATENTES MEDIANTE ACTITUDES O HECHOS EVIDENTES EN EL PROCEDIMIENTO.', FALSE, 4),
    ('SUB-0888', 'E', 'SI ES CÓNYUGE, CONVIVIENTE, PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, CON CUALQUIERA DE LAS PARTES O CON SUS REPRESENTANTES.', FALSE, 5),
    ('SUB-0889', 'A', 'SI PERSONALMENTE, O BIEN SU CÓNYUGE, CONVIVIENTE O ALGÚN PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, TUVIERE INTERÉS EN EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO QUE SE INVESTIGA O EN OTRO SEMEJANTE, CUYA RESOLUCIÓN PUEDA INFLUIR EN LA SITUACIÓN DE AQUEL.', FALSE, 1),
    ('SUB-0889', 'B', 'CUANDO TUVIERE O HUBIESE TENIDO EN LOS ÚLTIMOS DOCE MESES, RELACIÓN DE SERVICIO O DE SUBORDINACIÓN CON CUALQUIERA DE LAS PARTES O TERCEROS DIRECTAMENTE INTERESADOS EN EL ACTO RESOLUTIVO.', FALSE, 2),
    ('SUB-0889', 'C', 'SI ES CÓNYUGE, CONVIVIENTE, PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, CON CUALQUIERA DE LAS PARTES O CON SUS REPRESENTANTES.', FALSE, 3),
    ('SUB-0889', 'D', 'SI HA TENIDO INTERVENCIÓN COMO ASESOR, PERITO O TESTIGO EN EL MISMO PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, O SI COMO INSTRUCTOR HUBIERE MANIFESTADO PREVIAMENTE SU PARECER SOBRE EL MISMO, DE MODO QUE PUDIERA ENTENDERSE QUE SE HA PRONUNCIADO SOBRE EL ASUNTO, SALVO LA RECTIFICACIÓN DE ERRORES O LA DECISIÓN DEL RECURSO DE RECONSIDERACIÓN.', FALSE, 4),
    ('SUB-0889', 'E', 'SER DENUNCIANTE DE LOS HECHOS O HABER SIDO DENUNCIADO ANTES POR ALGUNO DE LOS INVESTIGADOS O DENUNCIANTES.', TRUE, 5),
    ('SUB-0890', 'A', 'CUANDO TUVIERE O HUBIESE TENIDO EN LOS ÚLTIMOS DOCE MESES, RELACIÓN DE SERVICIO O DE SUBORDINACIÓN CON CUALQUIERA DE LAS PARTES O TERCEROS DIRECTAMENTE INTERESADOS EN EL ACTO RESOLUTIVO.', FALSE, 1),
    ('SUB-0890', 'B', 'HABER PARTICIPADO EN UNA INVESTIGACIÓN POLICIAL CONTRA EL INVESTIGADO O DENUNCIANTE.', TRUE, 2),
    ('SUB-0890', 'C', 'SI ES CÓNYUGE, CONVIVIENTE, PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, CON CUALQUIERA DE LAS PARTES O CON SUS REPRESENTANTES.', FALSE, 3),
    ('SUB-0890', 'D', 'SI HA TENIDO INTERVENCIÓN COMO ASESOR, PERITO O TESTIGO EN EL MISMO PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, O SI COMO INSTRUCTOR HUBIERE MANIFESTADO PREVIAMENTE SU PARECER SOBRE EL MISMO, DE MODO QUE PUDIERA ENTENDERSE QUE SE HA PRONUNCIADO SOBRE EL ASUNTO, SALVO LA RECTIFICACIÓN DE ERRORES O LA DECISIÓN DEL RECURSO DE RECONSIDERACIÓN.', FALSE, 4),
    ('SUB-0890', 'E', 'SI PERSONALMENTE, O BIEN SU CÓNYUGE, CONVIVIENTE O ALGÚN PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, TUVIERE INTERÉS EN EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO QUE SE INVESTIGA O EN OTRO SEMEJANTE, CUYA RESOLUCIÓN PUEDA INFLUIR EN LA SITUACIÓN DE AQUEL.', FALSE, 5),
    ('SUB-0891', 'A', 'SI ES CÓNYUGE, CONVIVIENTE, PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, CON CUALQUIERA DE LAS PARTES O CON SUS REPRESENTANTES.', FALSE, 1),
    ('SUB-0891', 'B', 'PARENTESCO CON EL PERSONAL SUJETO A INVESTIGACIÓN, CON EL DENUNCIANTE O CON LOS MIEMBROS DEL MISMO ÓRGANO DISCIPLINARIO, EN CALIDAD DE CÓNYUGE, CONVIVIENTE O HASTA EL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO GRADO DE AFINIDAD.', TRUE, 2),
