INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1201 a 1300
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1201, 'SUB-1201', 'SBM3', 'ES LA PROMOCIÓN DEL OFICIAL Y SUBOFICIAL EN SITUACIÓN DE ACTIVIDAD AL GRADO POLICIAL INMEDIATO SUPERIOR. NOS REFERIMOS A:', 'ASCENSO', 'ART. 4', '186717'),
    (1202, 'SUB-1202', 'SBM3', 'ES CONFERIDO EN ESTRICTA OBSERVANCIA DE LOS PRINCIPIOS, REQUISITOS, ESPECIALIDADES Y PROCEDIMIENTOS ESTABLECIDOS EN LA PRESENTE LEY:', 'EL ASCENSO', 'ART. 4', '186718'),
    (1203, 'SUB-1203', 'SBM3', 'LOS PROCESOS DE ASCENSO SON ANUALES. EL CRONOGRAMA DE SUS ETAPAS PARA OFICIALES Y SUBOFICIALES ES APROBADO Y PUBLICADO ANUALMENTE. ÚNICAMENTE SE AGREGA AL LEGAJO DE ASCENSO LA INFORMACIÓN QUE CORRESPONDA AL AÑO ANTERIOR A LA CONVOCATORIA AL PROCESO HASTA EL ÚLTIMO DÍA HÁBIL DEL MES DE....:', 'MARZO DEL AÑO DEL PROCESO', 'ART.5', '186719'),
    (1204, 'SUB-1204', 'SBM3', 'CONSTITUYE UNA DE LAS ETAPAS DEL PROCESO DE ASCENSO:', 'DETERMINACIÓN DE CANDIDATOS.', 'ART. 5', '186720'),
    (1205, 'SUB-1205', 'SBM3', 'CONSTITUYE UNA DE LAS ETAPAS DEL PROCESO DE ASCENSO:', 'DECLARACIÓN DE APTITUD', 'ART. 5', '186721'),
    (1206, 'SUB-1206', 'SBM3', 'CONSTITUYE UNA DE LAS ETAPAS DEL PROCESO DE ASCENSO:', 'FORMULACIÓN DEL CUADRO DE APTITUD Y NOTAS', 'ART. 5', '186724'),
    (1207, 'SUB-1207', 'SBM3', 'CONSTITUYE UNA DE LAS ETAPAS DEL PROCESO DE ASCENSO:', 'PRESENTACIÓN Y FORMALIZACIÓN DEL ASCENSO', 'ART. 5', '186727'),
    (1208, 'SUB-1208', 'SBM3', 'CONSTITUYE LAS MODALIDADES DE ASCENSO AL GRADO INMEDIATO SUPERIOR:', 'ASCENSO POR CONCURSO, ASCENSO PÓSTUMO', 'ART. 6', '186729'),
    (1209, 'SUB-1209', 'SBM3', 'ES EL PROCESO SELECTIVO PARA CUBRIR LAS VACANTES:', 'ASCENSO POR CONCURSO', 'ART. 6', '186730'),
    (1210, 'SUB-1210', 'SBM3', 'PODRÁN ASCENDER AL GRADO DE GENERAL DE SERVICIOS ÚNICAMENTE LOS OFICIALES DE SERVICIOS...:', 'ABOGADOS Y MÉDICOS', 'ART. 6', '186731'),
    (1211, 'SUB-1211', 'SBM3', 'EL OFICIAL O SUBOFICIAL DE LA POLICÍA NACIONAL DEL PERÚ (PNP), PREVIA CALIFICACIÓN, ASCIENDE DE MANERA PÓSTUMA AL GRADO INMEDIATO SUPERIOR POR...:', 'ACCIÓN DE ARMAS O POR ACTO DEL SERVICIO EN EL CUMPLIMIENTO DEL DEBER', 'ART. 6', '186732'),
    (1212, 'SUB-1212', 'SBM3', 'CONSTITUYE UNA DE LAS APTITUDES QUE LOS CANDIDATOS AL ASCENSO DEBEN CUMPLIR Y APROBAR:', 'APTITUD PSICOSOMÁTICA', 'ART. 7', '186733'),
    (1213, 'SUB-1213', 'SBM3', 'CONSTITUYE UNA DE LAS APTITUDES QUE LOS CANDIDATOS AL ASCENSO DEBEN CUMPLIR Y APROBAR:', 'APTITUD PROFESIONAL', 'ART. 7', '186734'),
    (1214, 'SUB-1214', 'SBM3', 'CONSTITUYE UNA DE LAS APTITUDES QUE LOS CANDIDATOS AL ASCENSO DEBEN CUMPLIR Y APROBAR:', 'APTITUD FÍSICA', 'ART. 7', '186736'),
    (1215, 'SUB-1215', 'SBM3', 'CONSTITUYE UNA DE LAS APTITUDES QUE LOS CANDIDATOS AL ASCENSO DEBEN CUMPLIR Y APROBAR:', 'APTITUD EN DESTREZA TÉCNICA PARA EL TIRO', 'ART. 7', '186737'),
    (1216, 'SUB-1216', 'SBM3', 'COMPRENDE LA EVALUACIÓN DE LA CONDICIÓN DE LA NATURALEZA FÍSICA, MÉDICA, FISIOLÓGICA Y PSICOLÓGICA DEL OFICIAL O SUBOFICIAL NECESARIA PARA EL CUMPLIMIENTO DE LA CAPACIDAD REQUERIDA PARA EL DESARROLLO DE SU FUNCIÓN, DE CONFORMIDAD CON EL REGLAMENTO GENERAL VIGENTE:', 'APTITUD PSICOSOMÁTICA', 'ART. 7', '186738'),
    (1217, 'SUB-1217', 'SBM3', 'APTITUD PROFESIONAL COMPRENDE:', 'FORMACIÓN ACADÉMICA, EXPERIENCIA EN EL SERVICIO POLICIAL Y DESEMPEÑO PERSONAL PROFESIONAL O TÉCNICO, Y POTENCIAL PROFESIONAL O TÉCNICO POLICIAL', 'ART. 7', '186739'),
    (1218, 'SUB-1218', 'SBM3', 'SE DEFINE COMO LA EVALUACIÓN DE LOS ANTECEDENTES DISCIPLINARIOS, MÉRITOS Y DEMÉRITOS DURANTE LA CARRERA POLICIAL DEL CANDIDATO AL ASCENSO. NOS REFERIMOS A:', 'APTITUD DISCIPLINARIA', 'ART. 7', '186740'),
    (1219, 'SUB-1219', 'SBM3', 'CONDICIONES FÍSICAS DEL CANDIDATO PARA EL SERVICIO POLICIAL, CONSIDERANDO LAS PRUEBAS DE ESFUERZO FÍSICO. LA EVALUACIÓN SE REALIZA TENIENDO EN CUENTA LAS DISPOSICIONES SOBRE LA MATERIA, DE CONFORMIDAD CON LAS CONDICIONES DE ALTITUD Y CLIMA DEL LUGAR DONDE SE DESARROLLA EL EXAMEN, ASÍ COMO LA EDAD Y EL SEXO DEL CANDIDATO', 'APTITUD FÍSICA', 'ART. 7', '186741'),
    (1220, 'SUB-1220', 'SBM3', 'PERMITE MEDIR LA HABILIDAD DEL CANDIDATO AL ASCENSO EN EL USO DEL ARMA DE PUÑO ASIGNADA POR EL ESTADO PARA EL CUMPLIMIENTO DE SUS FUNCIONES. NOS REFERIMOS A:', 'APTITUD EN DESTREZA TÉCNICA PARA EL TIRO', 'ART. 7', '186742'),
    (1221, 'SUB-1221', 'SBM3', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN GENERAL DE ARMAS PARA SER CANDIDATO AL ASCENSO?', '4 AÑOS', 'ART. 8', '186744'),
    (1222, 'SUB-1222', 'SBM3', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN CAPITÁN DE SERVICIOS PARA SER CANDIDATO AL ASCENSO?', '6 AÑOS', 'ART. 8', '186745'),
    (1223, 'SUB-1223', 'SBM3', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN CORONEL DE SERVICIOS PARA SER CANDIDATO AL ASCENSO?', '6 AÑOS', 'ART. 8', '186748'),
    (1224, 'SUB-1224', 'SBM3', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN SUBOFICIAL DE TERCERA PARA SER CANDIDATO AL ASCENSO?', '5 AÑOS', 'ART. 8', '186749'),
