    ('SUB-1497', 'A', 'LA EXPRESIÓN DE LOS LINEAMIENTOS QUE PROCEDEN, EL ÓRGANO ANTE EL CUÁL DEBEN SOLICITAR LOS RECURSOS Y EL PLAZO ESTABLECIDO.', FALSE, 1),
    ('SUB-1497', 'B', 'LA SOLICITUD DE LOS RECURSOS QUE PROCEDEN, EL ÓRGANO ANTE EL CUÁL NO DEBEN PRESENTARSE LOS RECURSOS Y EL PLAZO PARA INTERPONERLOS.', FALSE, 2),
    ('SUB-1497', 'C', 'LA DOCUMENTACIÓN DE LOS RECURSOS QUE INTERPONEN, EL ÓRGANO ANTE EL CUÁL DEBEN PRESENTARSE LOS RECURSOS Y EL PLAZO NO ESTABLECIDO PARA INTERPONERLOS.', FALSE, 3),
    ('SUB-1497', 'D', 'LA EXPRESIÓN DE LOS RECURSOS QUE PROCEDEN, EL ÓRGANO ANTE EL CUÁL DEBEN PRESENTARSE LOS RECURSOS Y EL PLAZO PARA INTERPONERLOS.', TRUE, 4),
    ('SUB-1497', 'E', 'LA EXPRESIÓN DE LOS PETITORIOS QUE PROCEDEN, ANTE EL CUÁL DEBEN PRESENTARSE LOS RECURSOS Y EL PLAZO PARA EVALUARLOS.', FALSE, 5),
    ('SUB-1498', 'A', 'LA CONDICIÓN DEL PROCEDIMIENTO DENTRO DEL CUÁL HAYA SIDO VERIFICADO.', FALSE, 1),
    ('SUB-1498', 'B', 'LA IDENTIFICACIÓN DEL PROCEDIMIENTO DENTRO DEL CUÁL HAYA SIDO DICTADO.', TRUE, 2),
    ('SUB-1498', 'C', 'LA VERIFICACIÓN DEL PROCESO DENTRO DEL CUÁL HAYA SIDO SOLUCIONADO.', FALSE, 3),
    ('SUB-1498', 'D', 'LA IDENTIDAD DE LA RESOLUCIÓN DENTRO DEL CUÁL HAYA SIDO SOLICITADO.', FALSE, 4),
    ('SUB-1498', 'E', 'LA SOLICITUD DEL PROCEDIMIENTO FUERA DE LA CUÁL HAYA SIDO DICTADO.', FALSE, 5),
    ('SUB-1499', 'A', 'LA FECHA DE NO VIGENCIA DEL ACTO NOTIFICADO, Y CON LA MENCIÓN DEL AGOTAMIENTO DE LA VÍA ADMINISTRATIVA', FALSE, 1),
    ('SUB-1499', 'B', 'LA FECHA DE VIGENCIA DEL ACTO NOTIFICADO, Y CON LA MENCIÓN DEL NO AGOTAMIENTO DE LA VÍA JUDICIAL.', FALSE, 2),
    ('SUB-1499', 'C', 'LA FECHA DE VIGENCIA DEL ACTO REGISTRADO, Y CON LA MENCIÓN DE SI AGOTARE LA VÍA PENAL.', FALSE, 3),
    ('SUB-1499', 'D', 'LA FECHA DE VIGENCIA DEL ACTO NOTIFICADO, Y CON LA MENCIÓN DE SI AGOTARE LA VÍA ADMINISTRATIVA.', TRUE, 4),
    ('SUB-1499', 'E', 'LA FECHA DEL DÍA DEL ACTO NOTIFICADO, Y CON LA MENCIÓN DE LA RESOLUCIÓN DE LA VÍA ADMINISTRATIVA.', FALSE, 5),
    ('SUB-1500', 'A', 'ANTICIPADA.', TRUE, 1),
