INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1501 a 1600
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1501, 'SUB-1501', 'SBM3', 'LA POLICÍA PODRÁ INFORMAR A LOS MEDIOS DE COMUNICACIÓN SOCIAL ACERCA DE LA IDENTIDAD DE LOS IMPUTADOS. CUANDO SE TRATE DE LA VÍCTIMA, REQUERIRÁ:.', 'PREVIA AUTORIZACIÓN DEL FISCAL.', 'ART. 70', '184330'),
    (1502, 'SUB-1502', 'SBM3', '¿A TRAVÉS DE QUIÉN EL IMPUTADO PUEDE HACER VALER LOS DERECHOS QUE LA CONSTITUCIÓN Y LAS LEYES LA CONCEDEN?.', 'DE SU ABOGADO DEFENSOR.', 'ART. 71. Num. 1', '184331'),
    (1503, 'SUB-1503', 'SBM3', 'CONOCER LOS CARGOS FORMULADOS EN SU CONTRA Y, EN CASO DE DETENCIÓN, A QUE SE LE EXPRESE LA CAUSA O MOTIVO DE DICHA MEDIDA, ES UN:.', 'DERECHO DEL IMPUTADO.', 'ART. 71. Num. 2. a)', '184332'),
    (1504, 'SUB-1504', 'SBM3', 'CUANDO EL IMPUTADO CONSIDERE QUE DURANTE LAS DILIGENCIAS PRELIMINARES O EN LA INVESTIGACIÓN PREPARATORIA NO SE HAN DADO CUMPLIMIENTO A ESTAS DISPOSICIONES, O QUE SUS DERECHOS NO SON RESPETADOS O QUE ES OBJETO DE MEDIDAS LIMITATIVAS DE DERECHOS INDEBIDAS O DE REQUERIMIENTOS ILEGALES; PUEDE ACUDIR:.', 'EN VÍA DE TUTELA AL JUEZ DE LA INVESTIGACIÓN PREPARATORIA.', 'ART. 71. Num. 4', '184333'),
    (1505, 'SUB-1505', 'SBM3', '¿QUIÉN DEBE SER ASISTIDO DESDE LOS ACTOS INICIALES DE INVESTIGACIÓN POR UN ABOGADO DEFENSOR?.', 'EL IMPUTADO.', 'ART. 71. Num. 2. c)', '184334'),
    (1506, 'SUB-1506', 'SBM3', 'EL IMPUTADO TIENE DERECHO A ABSTENERSE DE DECLARAR; Y, SI ACEPTA HACERLO, A QUE SU ABOGADO DEFENSOR ESTÉ PRESENTE EN SU DECLARACIÓN Y EN TODAS LAS DILIGENCIAS EN QUE:.', 'SE REQUIERE SU PRESENCIA. Código Procesal Penal', 'ART. 71. Num. 2. d)', '184335'),
    (1507, 'SUB-1507', 'SBM3', 'EL IMPUTADO TIENE DERECHO A QUE NO SE EMPLEE EN SU CONTRA MEDIOS COACTIVOS, INTIMIDATORIOS O CONTRARIOS A SU DIGNIDAD, NI A SER SOMETIDO A TÉCNICAS O MÉTODOS QUE INDUZCAN O ALTEREN:.', 'SU LIBRE VOLUNTAD O A SUFRIR UNA RESTRICCIÓN NO AUTORIZADA.', 'ART. 71. Num. 2. e)', '184336'),
    (1508, 'SUB-1508', 'SBM3', 'EL IMPUTADO CUANDO SU ESTADO DE SALUD ASÍ LO REQUIERA, TIENE DERECHO A SER EXAMINADO POR MÉDICO LEGISTA O EN SU DEFECTO POR:.', 'OTRO PROFESIONAL DE LA SALUD.', 'ART. 71. Num. 2. f)', '184337'),
    (1509, 'SUB-1509', 'SBM3', '¿QUIÉNES FIRMAN EN EL ACTA SOBRE EL CUMPLIMIENTO DE LOS DERECHOS DEL IMPUTADO?.', 'EL IMPUTADO Y LA AUTORIDAD CORRESPONDIENTE.', 'ART. 71. Num. 3', '184338'),
    (1510, 'SUB-1510', 'SBM3', '¿QUÉ DEBERÁ DE REALIZARSE, SI EL IMPUTADO SE REHUSA A FIRMAR EN ACTA?.', 'SE HARÁ CONSTAR LA ABSTENCIÓN, Y SE CONSIGNARÁ EL MOTIVO SI LO EXPRESARE.', 'ART. 71. Num. 3', '184339'),
    (1511, 'SUB-1511', 'SBM3', '¿QUIÉN PUEDE ACUDIR EN VÍA DE TUTELA AL JUEZ DE LA INVESTIGACIÓN PREPARATORIA, PARA QUE SUBSANE LA OMISIÓN, O DICTE LA MEDIDA DE CORRECCIÓN O DE PROTECCIÓN QUE CORRESPONDA?.', 'EL IMPUTADO CUANDO CONSIDERE QUE SUS DERECHOS NO SON RESPETADOS, O QUE ES OBJETO DE MEDIDAS LIMITATIVAS.', 'ART. 71. Num. 4', '184340'),
    (1512, 'SUB-1512', 'SBM3', '¿QUIÉN SERÁ IDENTIFICADO POR SU NOMBRE, DATOS PERSONALES, SEÑAS PARTICULARES Y, CUANDO CORRESPONDA, POR SUS IMPRESIONES DIGITALES A TRAVÉS DE LA OFICINA TÉCNICA RESPECTIVA?.', 'EL IMPUTADO.', 'ART. 72. Num. 1', '184341'),
    (1513, 'SUB-1513', 'SBM3', '¿QUÉ SE DEBERÁ REALIZAR SI EL IMPUTADO SE ABSTIENE DE PROPORCIONAR DATOS QUE LO IDENTIFICAN O LO HAGA FALSAMENTE?.', 'SE LE IDENTIFICARÁ POR TESTIGOS O POR OTROS MEDIOS ÚTILES, AUN CONTRA SU VOLUNTAD.', 'ART. 72. Num. 2', '184342'),
    (1514, 'SUB-1514', 'SBM3', '¿QUÉ SUCEDERÁ SI HUBIERA DUDA SOBRE LOS DATOS OBTENIDOS EN LA IDENTIFICACIÓN DEL IMPUTADO?.', 'NO ALTERARÁ EL CURSO DE LAS ACTUACIONES PROCESALES Y LOS ERRORES SOBRE ELLOS PODRÁN SER CORREGIDOS EN CUALQUIER OPORTUNIDAD.', 'ART. 72. Num. 3', '184343'),
    (1515, 'SUB-1515', 'SBM3', 'LOS JUECES, LOS FISCALES O LA POLICÍA NACIONAL DEBEN HACER SABER AL IMPUTADO DE MANERA INMEDIATA Y COMPRENSIBLE, QUE TIENE DERECHO A:.', 'SER ASISTIDO DESDE LOS ACTOS INICIALES POR UN ABOGADO DEFENSOR.', 'ART. 71. Num. 2. c)', '184344'),
    (1516, 'SUB-1516', 'SBM3', 'LOS JUECES, LOS FISCALES O LA POLICÍA NACIONAL DEBEN HACER SABER AL IMPUTADO DE MANERA INMEDIATA Y COMPRENSIBLE, QUE TIENE DERECHO A:.', 'ABSTENERSE DE DECLARAR; Y, SI ACEPTA HACERLO, A QUE SU ABOGADO DEFENSOR ESTÉ PRESENTE.', 'ART. 71. Num. 2. d)', '184345'),
    (1517, 'SUB-1517', 'SBM3', 'LOS JUECES, LOS FISCALES O LA POLICÍA NACIONAL DEBEN HACER SABER AL IMPUTADO DE MANERA INMEDIATA Y COMPRENSIBLE QUE TIENE DERECHO A:.', 'QUE NO SE EMPLEE EN SU CONTRA MEDIOS COACTIVOS, INTIMIDATORIOS O CONTRARIOS A SU DIGNIDAD.', 'ART. 71. Num. 2. e)', '184346'),
    (1518, 'SUB-1518', 'SBM3', 'AL PROCESADO QUE ALTERE EL ORDEN EN UN ACTO PROCESAL, SE LE APERCIBIRÁ CON LA SUSPENSIÓN DE LA DILIGENCIA Y DE CONTINUARLA', 'CON LA SOLA INTERVENCIÓN DE SU ABOGADO DEFENSOR Y DEMÁS SUJETOS PROCESALES.', 'ART. 73. Num. 1', '184347'),
    (1519, 'SUB-1519', 'SBM3', '¿QUÉ SUCEDERÍA SI EL ABOGADO DEFENSOR SE SOLIDARIZA Y ABANDONA LA DILIGENCIA?.', 'SERÁ SUSTITUIDO POR UNO NOMBRADO DE OFICIO.', 'ART. 73. Num. 2', '184348'),
    (1520, 'SUB-1520', 'SBM3', 'CUANDO SE ESTABLEZCA LA MINORÍA DE EDAD DEL IMPUTADO, ¿QUIÉN PUEDE SOLICITAR AL JUEZ DE LA INVESTIGACIÓN PREPARATORIA, CORTE LA SECUELA DEL PROCESO Y PONGA AL ADOLESCENTE A DISPOSICIÓN DEL FISCAL DE FAMILIA?.', 'EL FISCAL O CUALQUIERA DE LAS PARTES.', 'ART. 74. Num. 1', '184349'),
    (1521, 'SUB-1521', 'SBM3', '¿QUÉ ACCIONES DICTARÁ EL JUEZ CUANDO SE ACREDITA LA MINORÍA DE EDAD EN LA ETAPA INTERMEDIA O EN EL JUICIO ORAL, PREVIA AUDIENCIA Y CON LA INTERVENCIÓN DE LAS PARTES?.', 'DICTARÁ LA RESOLUCIÓN CORRESPONDIENTE.', 'ART. 74. Num. 2', '184350'),
    (1522, 'SUB-1522', 'SBM3', 'CUANDO SE ESTABLEZCA LA MINORÍA DE EDAD DEL IMPUTADO, EN TODOS LOS CASOS:', 'SE DEJARÁ A SALVO EL DERECHO DEL ACTOR CIVIL PARA QUE LO HAGA VALER EN LA VÍA PERTINENTE.', 'ART. 74. Num. 3', '184351'),
    (1523, 'SUB-1523', 'SBM3', 'EL JUEZ, A REQUERIMIENTO DEL FISCAL O DE LAS DEMÁS PARTES, PREVIA CONSTATACIÓN, DECLARARÁ CONTUMAZ AL IMPUTADO CUANDO:.', 'NO OBEDEZCA, PESE A TENER CONOCIMIENTO DE SU EMISIÓN, UNA ORDEN DE DETENCIÓN O PRISIÓN.', 'ART. 79. Num. 1. c)', '184352'),
    (1524, 'SUB-1524', 'SBM3', 'EN CASO DE INIMPUTABILIDAD DEL PROCESADO,¿CUÁNDO DISPONDRÁ EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA LA PRÁCTICA DE UN EXAMEN POR UN PERITO ESPECIALIZADO?.', 'SEGÚN EL ESTADO DE LA CAUSA, DISPONDRÁ, DE OFICIO O A PEDIDO DE PARTE', 'ART. 75. Num. 1', '184353'),
    (1525, 'SUB-1525', 'SBM3', 'RECIBIDO EL INFORME PERICIAL, PREVIA AUDIENCIA, CON INTERVENCIÓN DE LAS PARTES Y DEL PERITO, SI EL JUEZ CONSIDERA SI EXISTEN INDICIOS SUFICIENTES PARA ESTIMAR ACREDITADO EL ESTADO DE INIMPUTABILIDAD DEL PROCESADO:.', 'DICTARÁ LA RESOLUCIÓN CORRESPONDIENTE INSTANDO LA INCOACIÓN DEL PROCEDIMIENTO DE SEGURIDAD.', 'ART. 75. Num. 2', '184354'),
    (1526, 'SUB-1526', 'SBM3', '¿EN QUÉ CONSISTE LA ANOMALÍA PSÍQUICA SOBREVENIDA?.', 'CUANDO DESPUÉS DE COMETIDO EL DELITO LE SOBREVIENE ANOMALÍA PSÍQUICA GRAVE AL IMPUTADO.', 'ART. 76. Num. 1', '184355'),
    (1527, 'SUB-1527', 'SBM3', 'ANOMALÍA PSÍQUICA SOBREVENIDA.- SI DEL ANÁLISIS DE LO ACTUADO, EL ÓRGANO JURISDICCIONAL ADVIERTE QUE EL IMPUTADO PRESENTA ANOMALÍA PSÍQUICA GRAVE QUE LE IMPIDE CONTINUAR CON LA CAUSA:.', 'DISPONDRÁ LA SUSPENSIÓN DEL PROCESO HASTA QUE EL TRATAMIENTO DE LA DOLENCIA HAGA POSIBLE REINICIARLO.', 'ART. 76. Num. 2', '184356'),
    (1528, 'SUB-1528', 'SBM3', 'ANOMALÍA PSÍQUICA SOBREVENIDA.- ¿CUÁNDO SE IMPEDIRÁ LA DECLARACIÓN DEL IMPUTADO O EL JUICIO?. Código Procesal Penal', 'CUANDO SE SUSPENDA EL PROCESO, SIN PERJUICIO DE QUE SE PROSIGA CON LA INVESTIGACIÓN DEL HECHO', 'ART. 76. Num. 3', '184357'),
    (1529, 'SUB-1529', 'SBM3', '¿QUÉ DISPONDRÁ EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA CUANDO EL IMPUTADO ENFERMARA DURANTE LA PRIVACIÓN DE SU LIBERTAD?.', 'DISPONDRÁ SU INMEDIATA EVALUACIÓN POR PARTE DEL MÉDICO LEGISTA O, EN SU DEFECTO, DEL PERITO MÉDICO QUE DESIGNE.', 'ART. 77. Num. 1', '184358'),
    (1530, 'SUB-1530', 'SBM3', 'ENFERMEDAD DEL IMPUTADO.- EVACUADO EL DICTAMEN, SE PODRÁ ORDENAR, SI FUERE NECESARIO:.', 'EL INGRESO DEL IMPUTADO A UN CENTRO HOSPITALARIO.', 'ART. 77. Num. 2', '184359'),
    (1531, 'SUB-1531', 'SBM3', 'ENFERMEDAD DEL IMPUTADO.- CUANDO SE REQUIERA DE INFRAESTRUCTURA Y ATENCIÓN MÉDICA ESPECIALIZADA QUE NO EXISTA EN UN CENTRO HOSPITALARIO ESTATAL', 'EN CASOS EXCEPCIONALES, SE PODRÁ AUTORIZAR SU INTERNAMIENTO EN UNA CLINICA PRIVADA.', 'ART. 77. Num. 2', '184360'),
    (1532, 'SUB-1532', 'SBM3', 'EL DIRECTOR DEL CENTRO HOSPITALARIO EN DONDE EL PROCESADO RECIBA ASISTENCIA MÉDICA O PSIQUIÁTRICA, DEBERÁ:.', 'INFORMAR TRIMESTRALMENTE AL FISCAL Y AL JUEZ ACERCA DEL ESTADO DE SALUD DEL PACIENTE', 'ART. 78', '184361'),
    (1533, 'SUB-1533', 'SBM3', 'LA JUSTICIA PENAL ES GRATUITA, SALVO EL:', 'PAGO DE LAS COSTAS PROCESALES', 'TÍTULO PRELIMINAR ART. I', '184362'),
    (1534, 'SUB-1534', 'SBM3', 'UN JUICIO PREVIO, ORAL, PÚBLICO Y CONTRADICTORIO, ES UN DERECHO QUE LE CORRESPONDE:', 'A TODA PERSONA', 'TÍTULO PRELIMINAR ART. I', '184363'),
    (1535, 'SUB-1535', 'SBM3', 'LA CONSTITUCIÓN Y ESTE CÓDIGO, PREVÉN QUE:', 'LAS PARTES INTERVENDRÁN EN EL PROCESO CON IGUALES POSIBILIDADES DE EJERCER LAS FACULTADES Y DERECHOS', 'TÍTULO PRELIMINAR ART. I', '184364'),
    (1536, 'SUB-1536', 'SBM3', '¿QUIÉNES PRESERVARÁN EL PRINCIPIO DE IGUALDAD PROCESAL?', 'LOS JUECES', 'TÍTULO PRELIMINAR ART. I', '184365'),
    (1537, 'SUB-1537', 'SBM3', 'EL ESTADO, ES QUIEN GARANTIZA LA:', 'INDEMNIZACIÓN POR LOS ERRORES JUDICIALES', 'TÍTULO PRELIMINAR ART. I', '184366'),
    (1538, 'SUB-1538', 'SBM3', 'LAS RESOLUCIONES SON RECURRIBLES, EN:', 'LOS CASOS Y MODOS PREVISTOS POR LEY', 'TÍTULO PRELIMINAR ART. I', '184367'),
    (1539, 'SUB-1539', 'SBM3', '¿A QUIÉNES SE CONSIDERA INOCENTE? Código Procesal Penal', 'A TODA PERSONA IMPUTADA DE LA COMISIÓN DE UN HECHO PUNIBLE Y DEBE SER TRATADA COMO TAL, MIENTRAS NO SE DEMUESTRE LO CONTRARIO', 'TÍTULO PRELIMINAR ART. II', '184368'),
    (1540, 'SUB-1540', 'SBM3', 'NINGÚN FUNCIONARIO O AUTORIDAD PÚBLICA PUEDE PRESENTAR A UNA PERSONA COMO:', 'CULPABLE O BRINDAR INFORMACIÓN EN TAL SENTIDO', 'TÍTULO PRELIMINAR ART. II', '184369'),
    (1541, 'SUB-1541', 'SBM3', '¿EN QUE CASO PROCEDERÁ EL ARRESTO CIUDADANO?.', 'EN ESTADO DE FLAGRANCIA DELICTIVA.', 'ART. 260. Num. 1', '184370'),
    (1542, 'SUB-1542', 'SBM3', 'EL MINISTERIO PÚBLICO ES EL TITULAR DEL EJERCICIO PÚBLICO DE LA ACCIÓN PENAL EN LOS DELITOS Y TIENE EL DEBER DE:', 'LA CARGA DE LA PRUEBA', 'TÍTULO PRELIMINAR ART. IV', '184371'),
    (1543, 'SUB-1543', 'SBM3', 'DEBE RESOLVERSE A FAVOR DEL IMPUTADO EN CASO DE:', 'DUDA SOBRE LA RESPONSABILIDAD PENAL', 'TÍTULO PRELIMINAR ART. II', '184372'),
    (1544, 'SUB-1544', 'SBM3', 'EL AGRAVIADO TIENE DERECHO A SER INFORMADO DEL RESULTADO DEL PROCEDIMIENTO, AUN CUANDO NO HAYA INTERVENIDO EN ÉL:.', 'SIEMPRE QUE LO SOLICITE.', 'ART. 95. Num. 1. a)', '184373'),
    (1545, 'SUB-1545', 'SBM3', 'INTERDICCIÓN DE LA PERSECUCIÓN PENAL MÚLTIPLE, SE REFIERE A:', 'QUE NADIE PODRÁ SER PROCESADO NI SANCIONADO MÁS DE UNA VEZ POR UN MISMO HECHO', 'TÍTULO PRELIMINAR ART. III', '184374'),
    (1546, 'SUB-1546', 'SBM3', '¿LA POLICIA QUÉ DOCUMENTO REDACTARÁ DONDE SE HAGA CONSTAR LA ENTREGA Y LAS DEMÁS CIRCUNSTANCIAS DE LA INTERVENCIÓN?.', 'UN ACTA.', 'ART. 260. Num. 2', '184375'),
    (1547, 'SUB-1547', 'SBM3', 'ES UNO DE LOS DERECHOS DEL AGRAVIADO, A SER ESCUCHADO ANTES DE CADA DECISIÓN QUE:.', 'IMPLIQUE LA EXTINCIÓN O SUSPENSIÓN DE LA ACCIÓN PENAL.', 'ART. 95. Num. 1. b)', '184376'),
    (1548, 'SUB-1548', 'SBM3', 'SALVO LAS EXCEPCIONES PREVISTAS EN LA CONSTITUCIÓN, SOLO PODRÁN DICTARSE POR LA AUTORIDAD JUDICIAL:', 'LAS MEDIDAS QUE LIMITAN DERECHOS FUNDAMENTALES', 'TÍTULO PRELIMINAR ART. VI', '184377'),
    (1549, 'SUB-1549', 'SBM3', 'EL AGRAVIADO TIENE DERECHO A RECIBIR UN TRATO DIGNO Y RESPETUOSO POR PARTE DE LAS AUTORIDADES COMPETENTES, Y A LA PROTECCIÓN DE SU INTEGRIDAD, INCLUYENDO LA DE SU FAMILIA. EN LOS PROCESOS POR DELITOS CONTRA LA LIBERTAD SEXUAL SE:.', 'PRESERVARÁ SU IDENTIDAD', 'ART. 95. Num. 1. c)', '184378'),
    (1550, 'SUB-1550', 'SBM3', 'SERÁ INTERPRETADA RESTRICTIVAMENTE:', 'LA LEY QUE COACTE LA LIBERTAD O EL EJERCICIO DE LOS DERECHOS PROCESALES', 'TÍTULO PRELIMINAR ART. VII', '184379'),
    (1551, 'SUB-1551', 'SBM3', 'LAS PRUEBAS OBTENIDAS, DIRECTA O INDIRECTAMENTE, CON VIOLACIÓN DEL CONTENIDO ESENCIAL DE LOS DERECHOS FUNDAMENTALES DE LA PERSONA:', 'CARECEN DE EFECTO LEGAL', 'TÍTULO PRELIMINAR ART. VIII', '184380'),
    (1552, 'SUB-1552', 'SBM3', 'EL MINISTERIO PÚBLICO ES TITULAR DEL EJERCICIO DE LA ACCIÓN PENAL EN LOS DELITOS Y TIENE EL DEBER DE LA CARGA DE LA PRUEBA, ADEMÁS:', 'ASUME LA CONDUCCIÓN DE LA INVESTIGACIÓN', 'TÍTULO PRELIMINAR ART. IV', '184381'),
    (1553, 'SUB-1553', 'SBM3', 'CONTRA SÍ MISMO, CONTRA SU CÓNYUGE, O SUS PARIENTES DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD:', 'NADIE PUEDE SER OBLIGADO O INDUCIDO A DECLARAR O A RECONOCER CULPABILIDAD', 'TÍTULO PRELIMINAR ART. IX', '184382'),
    (1554, 'SUB-1554', 'SBM3', '¿POR QUÉ EL AGRAVIADO PUEDE IMPUGNAR EL SOBRESEIMIENTO Y LA SENTENCIA ABSOLUTORIA?.', 'PORQUE ES UN DERECHO.', 'ART. 95. Num. 1. d)', '184383'),
    (1555, 'SUB-1555', 'SBM3', '¿CUÁNDO SERÁ INFORMADO EL AGRAVIADO SOBRE SUS DERECHOS?.', 'CUANDO INTERPONGA LA DENUNCIA, AL DECLARAR PREVENTIVAMENTE O EN SU PRIMERA INTERVENCIÓN EN LA CAUSA.', 'ART. 95. Num. 2', '184385'),
    (1556, 'SUB-1556', 'SBM3', 'LA CITACIÓN AL IMPUTADO CON DOMICILIO CONOCIDO Y PROCESAL, SERÁ REQUERIDO PARA SU CONCURRENCIA AL JUICIO BAJO APERCIBIMIENTO DE:', 'SER DECLARADO CONTUMAZ', 'ART. 367', '184386'),
    (1557, 'SUB-1557', 'SBM3', 'SI UN SOLO ACUSADO O SIENDO VARIOS NINGUNO CONCURRE A LA APERTURA DE LA AUDIENCIA, SIN JUSTIFICAR SU INASISTENCIA, SE:', 'SEÑALARÁ NUEVO DÍA Y HORA, SIN PERJUICIO DE DECLARARLOS CONTUMACES', 'ART. 367', '184387'),
    (1558, 'SUB-1558', 'SBM3', 'LAS MEDIDAS QUE LIMITAN DERECHOS FUNDAMENTALES, SE IMPONDRÁN MEDIANTE RESOLUCIÓN MOTIVADA, A INSTANCIA DE:', 'LA PARTE PROCESAL LEGITIMADA', 'TÍTULO PRELIMINAR ART. VI', '184388'),
    (1559, 'SUB-1559', 'SBM3', 'EN QUE CASOS NO PODRÁ REALIZARSE LA AUDIENCIA:', 'SIN PRESENCIA DEL ACUSADO Y SU DEFENSOR', 'ART. 367', '184389'),
    (1560, 'SUB-1560', 'SBM3', 'EL SUPERIOR JERÁRQUICO DE UN FISCAL, DE OFICIO O A INSTANCIA DEL AFECTADO, PODRÁ REEMPLAZARLO CUANDO NO CUMPLE ADECUADAMENTE CON SUS FUNCIONES O INCURRE EN IRREGULARIDADES. TAMBIÉN PODRÁ HACERLO PREVIA LAS INDAGACIONES QUE CONSIDERE CONVENIENTE, CUANDO:.', 'ESTÉ INCURSO EN LAS CAUSALES DE RECUSACIÓN ESTABLECIDAS.', 'ART. 62. Num. 1', '184390'),
    (1561, 'SUB-1561', 'SBM3', 'DE CONFORMIDAD CON LA LEY, AL FISCAL DE LA NACIÓN LE CORRESPONDE ESTABLECER LA:.', 'DISTRIBUCIÓN DE FUNCIONES DE LOS MIEMBROS DEL MINISTERIO PÚBLICO.', 'ART. 63. Num. 2', '184391'),
    (1562, 'SUB-1562', 'SBM3', 'TODO MEDIO DE PRUEBA SERÁ VALORADO SÓLO SI HA SIDO OBTENIDO E INCORPORADO AL PROCESO POR UN PROCEDIMIENTO:', 'CONSTITUCIONALMENTE LEGÍTIMO', 'TÍTULO PRELIMINAR ART. VIII', '184392'),
    (1563, 'SUB-1563', 'SBM3', 'CUANDO SON VARIOS LOS ACUSADOS, Y ALGUNO DE ELLOS NO CONCURRA, LA AUDIENCIA SE:', 'INICIARÁ CON LOS ASISTENTES', 'ART. 367', '184393'),
    (1564, 'SUB-1564', 'SBM3', 'TODA PERSONA TIENE DERECHO INVIOLABLE E IRRESTRICTO, A QUE SE LE CONCEDA UN TIEMPO RAZONABLE PARA:', 'QUE PREPARE SU DEFENSA', 'TÍTULO PRELIMINAR ART. IX', '184394'),
    (1565, 'SUB-1565', 'SBM3', 'TODA PERSONA TIENE DERECHO INVIOLABLE E IRRESTRICTO, A:', 'EJERCER SU AUTODEFENSA MATERIAL', 'TÍTULO PRELIMINAR ART. IX', '184395'),
    (1566, 'SUB-1566', 'SBM3', 'TODA PERSONA TIENE DERECHO INVIOLABLE E IRRESTRICTO, A:', 'INTERVENIR, EN PLENA IGUALDAD, EN LA ACTIVIDAD PROBATORIA', 'TÍTULO PRELIMINAR ART. IX', '184396'),
    (1567, 'SUB-1567', 'SBM3', 'EN QUÉ CASO AL ACUSADO AUSENTE O CONTUMAZ, SE LE INCORPORARÁ A LA AUDIENCIA:', 'CUANDO SEA CAPTURADO', 'ART. 367', '184397'),
    (1568, 'SUB-1568', 'SBM3', 'TODA PERSONA TIENE DERECHO INVIOLABLE E IRRESTRICTO, A:', 'UTILIZAR LOS MEDIOS DE PRUEBA PERTINENTES Código Procesal Penal', 'TÍTULO PRELIMINAR ART. IX', '184398'),
    (1569, 'SUB-1569', 'SBM3', 'EN QUÉ CASO AL ACUSADO AUSENTE O CONTUMAZ, SE LE INCORPORARÁ A LA AUDIENCIA:', 'CUANDO SE PRESENTE VOLUNTARIAMENTE', 'ART. 367', '184399'),
    (1570, 'SUB-1570', 'SBM3', 'CÓMO COMPARECERÁ EL IMPUTADO PRESO PREVENTIVO, EN TODO EL CURSO DEL JUICIO:', 'SIN LIGADURAS NI PRISIONES, ACOMPAÑADO DE EFECTIVOS POLICIALES', 'ART. 367', '184400'),
    (1571, 'SUB-1571', 'SBM3', 'EL PROCESO PENAL GARANTIZA, TAMBIÉN, EL EJERCICIO DE LOS DERECHOS DE INFORMACIÓN Y DE PARTICIPACIÓN PROCESAL A LA PERSONA AGRAVIADA O:', 'PERJUDICADA POR EL DELITO', 'TÍTULO PRELIMINAR ART. IX', '184401'),
    (1572, 'SUB-1572', 'SBM3', 'PRECISE EN QUÉ LUGAR SE REALIZARÁ EL JUZGAMIENTO:', 'LA SALA DE AUDIENCIAS', 'ART. 368', '184402'),
    (1573, 'SUB-1573', 'SBM3', 'EL MINISTERIO PÚBLICO, FORMULARÁ SUS DISPOSICIONES, REQUERIMIENTOS Y CONCLUSIONES EN FORMA MOTIVADA Y LA ESPECÍFICA, DE MANERA QUE SE BASTEN A SÍ MISMOS, SIN REMITIRSE A LAS DECISIONES DEL:.', 'JUEZ', 'ART. 64. Num. 1', '184403'),
    (1574, 'SUB-1574', 'SBM3', 'QUÉ AUTORIDAD DESIGNA LA SALA DE AUDIENCIAS PARA EL JUZGAMIENTO:', 'EL JUZGADO PENAL', 'ART. 368', '184404'),
    (1575, 'SUB-1575', 'SBM3', 'CUANDO EL ACUSADO POR RAZONES DE ENFERMEDAD U OTRA CAUSAL JUSTIFICADA SEA IMPOSIBLE SU CONCURRENCIA A LA SALA DE AUDIENCIAS, DÓNDE PODRÁ REALIZARSE EL JUZGAMIENTO:', 'EN EL LUGAR DONDE ÉSTE SE ENCUENTRE', 'ART. 368', '184405'),
    (1576, 'SUB-1576', 'SBM3', 'EN EL DESARROLLO DE LA DECLARACIÓN. DURANTE LA INVESTIGACIÓN PREPARATORIA, DE QUÉ MODO SE REPRODUCIRÁ EN EL ACTA QUE CONTENGA LA DECLARACIÓN DEL IMPUTADO, LO QUE SUCEDA EN LA DILIGENCIA:', 'EL JUEZ PENAL', 'ART. 369', '184406'),
    (1577, 'SUB-1577', 'SBM3', '¿QUIÉN PODRÁ DISPONER LA CONDUCCIÓN COMPULSIVA DEL OMISO POR LA POLICÍA NACIONAL, EN CASO DE INCONCURRENCIA A UNA CITACIÓN DEBIDAMENTE NOTIFICADA BAJO APERCIBIMIENTO?.', 'EL MINISTERIO PÚBLICO', 'ART. 66. Num. 1', '184407'),
    (1578, 'SUB-1578', 'SBM3', 'RECIBIR LAS DENUNCIAS ESCRITAS O SENTAR EL ACTA DE LAS VERBALES, ASÍ COMO TOMAR DECLARACIONES A LOS DENUNCIANTES, ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. A', '184408'),
    (1579, 'SUB-1579', 'SBM3', 'AISLAR, PROTEGER Y VIGILAR EL LUGAR DE LOS HECHOS A FIN DE QUE NO SEAN SUSTRAÍDOS, ALTERADOS Y CONTAMINADOS LOS INDICIOS Y EVIDENCIAS DEL DELITO. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. B', '184409'),
    (1580, 'SUB-1580', 'SBM3', 'PRACTICAR EL REGISTRO DE LAS PERSONAS, ASÍ COMO PRESTAR EL AUXILIO QUE REQUIERAN LAS VÍCTIMAS DEL DELITO. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ Código Procesal Penal', 'ART. 68. Num. 1. inc. C', '184410'),
    (1581, 'SUB-1581', 'SBM3', 'RECOGER Y CONSERVAR LOS INDICIOS Y EVIDENCIAS DE INTERÉS CRIMINALÍSTICO RELACIONADAS A LOS HECHOS QUE PUEDAN SERVIR A LA INVESTIGACIÓN, CONFORME AL PROTOCOLO INTERINSTITUCIONAL QUE CORRESPONDA. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. D', '184411'),
    (1582, 'SUB-1582', 'SBM3', 'PRACTICAR LAS DILIGENCIAS ORIENTADAS A LA IDENTIFICACIÓN FÍSICA DE LOS AUTORES Y PARTÍCIPES DEL DELITO Y LAS FALTAS. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. E', '184412'),
    (1583, 'SUB-1583', 'SBM3', 'REALIZAR ENTREVISTAS E IDENTIFICAR A POSIBLES TESTIGOS QUE HAYAN PRESENCIADO LA COMISIÓN DE LOS HECHOS. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. F', '184413'),
    (1584, 'SUB-1584', 'SBM3', 'LEVANTAR PLANOS, TOMAR FOTOGRAFÍAS, REALIZAR GRABACIONES EN VIDEO Y DEMÁS OPERACIONES TÉCNICAS O CIENTÍFICAS. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. G', '184414'),
    (1585, 'SUB-1585', 'SBM3', 'INTERVENIR Y DETENER A LOS PRESUNTOS AUTORES Y PARTÍCIPES EN CASO DE FLAGRANCIA, INFORMÁNDOLES DE INMEDIATO SOBRE SUS DERECHOS. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. H', '184415'),
    (1586, 'SUB-1586', 'SBM3', 'ASEGURAR LOS DOCUMENTOS PRIVADOS, E INSTRUMENTOS DE TELECOMUNICACIONES QUE PUEDAN SERVIR A LA INVESTIGACIÓN. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. I', '184416'),
    (1587, 'SUB-1587', 'SBM3', 'ALLANAR LOCALES DE USO PÚBLICO O ABIERTOS AL PÚBLICO, MEDIANTE OPERATIVOS DEBIDAMENTE PLANIFICADOS, HACIENDO USO RACIONAL DE LA FUERZA CONFORME CON LA NORMATIVA DE LA MATERIA. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. J', '184417'),
    (1588, 'SUB-1588', 'SBM3', 'EFECTUAR, BAJO INVENTARIO, LOS SECUESTROS E INCAUTACIONES NECESARIOS EN LOS CASOS DE DELITOS FLAGRANTES O DE PELIGRO INMINENTE DE SU PERPETRACIÓN. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. K', '184418'),
    (1589, 'SUB-1589', 'SBM3', 'RECIBIR LA MANIFESTACIÓN DE LOS PRESUNTOS AUTORES O PARTÍCIPES DE DELITOS, CON PRESENCIA OBLIGATORIA DEL ABOGADO DEFENSOR DE SU ELECCIÓN O DEL DEFENSOR PÚBLICO QUE CORRESPONDA, DEBIÉNDOSE REGISTRAR LAS DECLARACIONES EN DISPOSITIVOS O EQUIPOS AUDIOVISUALES. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. L', '184419'),
    (1590, 'SUB-1590', 'SBM3', 'REUNIR CUANTA INFORMACIÓN ADICIONAL DE URGENCIA PERMITA LA CRIMINALÍSTICA PARA PONERLA A DISPOSICIÓN DEL FISCAL. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. M', '184420'),
    (1591, 'SUB-1591', 'SBM3', 'LAS DEMÁS DILIGENCIAS Y PROCEDIMIENTOS DE INVESTIGACIÓN NECESARIOS PARA EL MEJOR ESCLARECIMIENTO DE LOS HECHOS INVESTIGADOS. ES UNA:', 'ATRIBUCIÓN DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 68. Num. 1. inc. N', '184421'),
    (1592, 'SUB-1592', 'SBM3', 'QUIÉN, ESCUCHANDO A LAS PARTES, DECIDIRÁ EL ORDEN EN QUE DEBEN ACTUARSE LAS DECLARACIONES DE LOS IMPUTADOS, SI FUERAN VARIOS: Código Procesal Penal', 'JUEZ PENAL', 'ART. 375', '184423'),
    (1593, 'SUB-1593', 'SBM3', 'A QUIÉN LE CORRESPONDE EL INTERROGATORIO DIRECTO DE LOS ÓRGANOS DE PRUEBA:', 'AL FISCAL Y A LOS ABOGADOS DE LAS PARTES', 'ART. 375', '184424'),
    (1594, 'SUB-1594', 'SBM3', 'EN EL DEBATE PROBATORIO, EN QUÉ ORDEN SE ENCUENTRA EL EXAMEN DEL ACUSADO:', 'PRIMER ORDEN', 'ART. 375', '184425'),
    (1595, 'SUB-1595', 'SBM3', 'EN EL DEBATE PROBATORIO, EN QUÉ ORDEN SE ENCUENTRA LA ACTUACIÓN DE LOS MEDIOS DE PRUEBA ADMITIDOS:', 'SEGUNDO ORDEN', 'ART. 375', '184426'),
    (1596, 'SUB-1596', 'SBM3', 'EN EL DEBATE PROBATORIO, EN QUÉ ORDEN SE ENCUENTRA LA ORALIZACIÓN DE LOS MEDIOS PROBATORIOS:', 'TERCER ORDEN', 'ART. 375', '184427'),
    (1597, 'SUB-1597', 'SBM3', 'PRESTAR ASESORAMIENTO DESDE QUE SU PATROCINADO FUERE CITADO O DETENIDO POR LA AUTORIDAD POLICIAL; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 1', '184428'),
    (1598, 'SUB-1598', 'SBM3', 'INTERROGAR DIRECTAMENTE A SU DEFENDIDO, ASÍ COMO A LOS DEMÁS PROCESADOS, TESTIGOS Y PERITOS; ES UN DERECHO Y UN DEBER DEL: Código Procesal Penal', 'ABOGADO DEFENSOR', 'ART. 84. Num. 2', '184429'),
    (1599, 'SUB-1599', 'SBM3', 'RECURRIR A LA ASISTENCIA RESERVADA DE UN EXPERTO EN CIENCIA, TÉCNICA O ARTE DURANTE EL DESARROLLO DE UNA DILIGENCIA, SIEMPRE QUE SUS CONOCIMIENTOS SEAN REQUERIDOS PARA MEJOR DEFENDER. EL ASISTENTE DEBERÁ ABSTENERSE DE INTERVENIR DE MANERA DIRECTA; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 3', '184430'),
    (1600, 'SUB-1600', 'SBM3', 'PARTICIPAR EN TODAS LAS DILIGENCIAS, EXCEPTO EN LA DECLARACIÓN PRESTADA DURANTE LA ETAPA DE INVESTIGACIÓN POR EL IMPUTADO QUE NO DEFIENDA; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 4', '184431')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

