INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1601 a 1700
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1601, 'SUB-1601', 'SBM3', 'APORTAR LOS MEDIOS DE INVESTIGACIÓN Y DE PRUEBA QUE ESTIME PERTINENTES;', 'ABOGADO DEFENSOR', 'ART. 84. Num. 5', '184432'),
    (1602, 'SUB-1602', 'SBM3', 'PRESENTAR PETICIONES ORALES O ESCRITAS PARA ASUNTOS DE SIMPLE TRÁMITE; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 6', '184433'),
    (1603, 'SUB-1603', 'SBM3', 'TENER ACCESO EN TODO EL DESARROLLO DEL PROCESO A LOS DOCUMENTOS DE ÁMBITO POLICIAL Y A LOS EXPEDIENTES DE ÁMBITO FISCAL Y JUDICIAL PARA INFORMARSE DEL PROCESO, SIN MÁS LIMITACIÓN QUE LA PREVISTA EN LA LEY, ASÍ COMO A OBTENER COPIA SIMPLE DE LAS ACTUACIONES EN CUALQUIER ESTADO O GRADO DEL PROCEDIMIENTO;', 'ABOGADO DEFENSOR Código Procesal Penal', 'ART. 84. Num. 7', '184434'),
    (1604, 'SUB-1604', 'SBM3', 'INGRESAR A LOS ESTABLECIMIENTOS PENALES Y DEPENDENCIAS POLICIALES, PREVIA IDENTIFICACIÓN, PARA ENTREVISTARSE CON SU PATROCINADO; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 8', '184435'),
    (1605, 'SUB-1605', 'SBM3', 'EXPRESARSE CON AMPLIA LIBERTAD EN EL CURSO DE LA DEFENSA, ORALMENTE Y POR ESCRITO, SIEMPRE QUE NO SE OFENDA EL HONOR DE LAS PERSONAS, YA SEAN NATURALES O JURÍDICAS; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 9', '184436'),
    (1606, 'SUB-1606', 'SBM3', 'INTERPONER CUESTIONES PREVIAS, CUESTIONES PREJUDICIALES, EXCEPCIONES, RECURSOS IMPUGNATORIOS Y LOS DEMÁS MEDIOS DE DEFENSA PERMITIDOS POR LA LEY; ES UN DERECHO Y UN DEBER DEL:', 'ABOGADO DEFENSOR', 'ART. 84. Num. 10', '184437'),
    (1607, 'SUB-1607', 'SBM3', 'EL JUEZ, DESPUÉS DE IDENTIFICARLOS ADECUADAMENTE, A QUIÉN, DISPONDRÁ QUE PRESTE JURAMENTO O PROMESA DE DECIR LA VERDAD:', 'TESTIGO O PERITO', 'ART. 378', '184438'),
    (1608, 'SUB-1608', 'SBM3', 'CUANDO EL IMPUTADO NO OBEDEZCA, PESE A TENER CONOCIMIENTO DE SU EMISIÓN, UNA ORDEN DE DETENCIÓN O PRISIÓN; EL JUEZ, A REQUERIMIENTO DEL FISCAL O DE LAS DEMÁS PARTES, PREVIA CONSTATACIÓN LO DECLARARÁ, COMO:.', 'CONTUMAZ', 'ART. 79. Num. 1. c)', '184439'),
    (1609, 'SUB-1609', 'SBM3', 'CUANDO EL IMPUTADO SE AUSENTE, SIN AUTORIZACIÓN DEL FISCAL O DEL JUEZ, DEL LUGAR DE SU RESIDENCIA O DEL ASIGNADO PARA RESIDIR; EL JUEZ, A REQUERIMIENTO DEL FISCAL O DE LAS DEMÁS PARTES, PREVIA CONSTATACIÓN LO DECLARARÁ, COMO:.', 'CONTUMAZ', 'ART. 79. Num. 1. c)', '184440'),
    (1610, 'SUB-1610', 'SBM3', 'NO SE SUSPENDE LA INVESTIGACIÓN PREPARATORIA NI LA ETAPA INTERMEDIA RESPECTO DEL CONTUMAZ O AUSENTE, POR LA:.', 'DECLARACIÓN DE CONTUMACIA O AUSENCIA.', 'ART. 79. Num. 4', '184441'),
    (1611, 'SUB-1611', 'SBM3', 'EL TEXTO: EL SERVICIO NACIONAL DE LA DEFENSA DE OFICIO, A CARGO DEL MINISTERIO DE JUSTICIA, PROVEERÁ LA DEFENSA GRATUITA A TODOS AQUELLOS QUE DENTRO DEL PROCESO PENAL, POR SUS ESCASOS RECURSOS NO PUEDAN DESIGNAR UN ABOGADO, SE REFIERE A:.', 'DERECHO A LA DEFENSA TÉCNICA.', 'ART. 80', '184442'),
    (1612, 'SUB-1612', 'SBM3', 'EN EL EXAMEN DE TESTIGOS, QUIÉN CONDUCIRÁ EL EXAMEN AL TESTIGO MENOR DE DIECISÉIS AÑOS DE EDAD:', 'EL JUEZ', 'ART. 378', '184443'),
    (1613, 'SUB-1613', 'SBM3', 'EL EXAMEN AL TESTIGO MENOR DE DIECISÉIS AÑOS DE EDAD SERÁ CONDUCIDO POR EL JUEZ EN BASE A LAS PREGUNTAS Y CONTRAINTERROGATORIOS PRESENTADOS POR:', 'EL FISCAL Y LAS DEMÁS PARTES', 'ART. 378', '184444'),
    (1614, 'SUB-1614', 'SBM3', 'CÓMO SE INICIA EL EXAMEN DE LOS PERITOS:', 'CON LA EXPOSICIÓN BREVE DEL CONTENIDO Y CONCLUSIONES DEL DICTAMEN PERICIAL', 'ART. 378', '184445'),
    (1615, 'SUB-1615', 'SBM3', 'SI UN TESTIGO O PERITO DECLARA QUE YA NO SE ACUERDA DE UN HECHO, QUÉ PROCEDIMIENTO SE UTILIZA:. Código Procesal Penal', 'SE PUEDE LEER LA PARTE CORRESPONDIENTE DEL ACTO SOBRE SU INTERROGATORIO ANTERIOR PARA HACER MEMORIA', 'ART. 378', '184446'),
    (1616, 'SUB-1616', 'SBM3', 'QUIÉNES ESTÁN AUTORIZADOS PARA CONSULTAR DOCUMENTOS, NOTAS ESCRITAS Y PUBLICACIONES DURANTE SU INTERROGATORIO:', 'LOS PERITOS', 'ART. 378', '184447'),
    (1617, 'SUB-1617', 'SBM3', 'DURANTE EL CONTRAINTERROGATORIO, QUIÉNES PODRÁN CONFRONTAR AL PERITO O TESTIGO CON SUS PROPIOS DICHOS U OTRAS VERSIONES DE LOS HECHOS PRESENTADAS EN EL JUICIO:', 'LAS PARTES', 'ART. 378', '184448'),
    (1618, 'SUB-1618', 'SBM3', 'A SOLICITUD DE QUIÉN, EL JUEZ PODRÁ AUTORIZAR UN NUEVO INTERROGATORIO DE LOS TESTIGOS O PERITOS QUE YA HUBIERAN DECLARADO EN LA AUDIENCIA:', 'DE ALGUNA DE LAS PARTES', 'ART. 378', '184449'),
    (1619, 'SUB-1619', 'SBM3', 'QUÉ ACCIÓN ADOPTA EL JUEZ, CUANDO EL TESTIGO O PERITO, OPORTUNAMENTE CITADO, NO HAYA COMPARECIDO AL JUICIO ORAL:', 'ORDENARÁ QUE SEA CONDUCIDO COMPULSIVAMENTE', 'ART. 379', '184450'),
    (1620, 'SUB-1620', 'SBM3', 'QUÉ SUCEDE CON EL JUICIO, SI EL TESTIGO O PERITO NO PUEDE SER LOCALIZADO PARA SU CONDUCCIÓN COMPULSIVA:', 'CONTINUARÁ CON PRESCINDENCIA DE ESA PRUEBA', 'ART. 379', '184451'),
    (1621, 'SUB-1621', 'SBM3', 'EN QUE CASO, EL JUEZ, DE OFICIO O A SOLICITUD DE PARTE, PUEDE ORDENAR QUE EL ACUSADO NO ESTÉ PRESENTE EN LA AUDIENCIA DURANTE UN INTERROGATORIO.', 'SI ES DE TEMER QUE OTRO PROCESADO, UN TESTIGO O UN PERITO NO DIRÁ LA VERDAD EN SU PRESENCIA', 'ART. 380', '184452'),
    (1622, 'SUB-1622', 'SBM3', 'LOS TESTIGOS Y PERITOS QUE NO PUEDAN CONCURRIR A LA SALA DE AUDIENCIAS POR UN IMPEDIMENTO JUSTIFICADO, DONDE SERÁN EXAMINADOS POR EL JUEZ:', 'EN EL LUGAR DONDE SE HALLEN', 'ART. 381', '184453'),
    (1623, 'SUB-1623', 'SBM3', 'SI LOS TESTIGOS Y PERITOS SE ENCUENTRAN EN LUGAR DISTINTO AL DEL JUICIO, QUE ACCIÓN ADOPTARÁ EL JUEZ:', 'SE TRASLADARÁ HASTA EL MISMO LUGAR', 'ART. 381', '184454'),
    (1624, 'SUB-1624', 'SBM3', 'SI LOS TESTIGOS Y PERITOS SE ENCUENTRAN EN LUGAR DISTINTO AL DEL JUICIO, QUE ACCIÓN ADOPTARÁ EL JUEZ:', 'EMPLEARÁ EL SISTEMA DE VÍDEO CONFERENCIA', 'ART. 381', '184455'),
    (1625, 'SUB-1625', 'SBM3', 'EN CASOS EXCEPCIONALES, SI SE CUENTA CON LOS MEDIOS TÉCNICOS CORRESPONDIENTES, LA PRACTICA DE LA PRUEBA, SE REPRODUCIRÁ A TRAVÉS DE:', 'VIDEO, FILMACIÓN O AUDIO', 'ART. 381', '184456'),
    (1626, 'SUB-1626', 'SBM3', 'QUÉ SERÁN EXHIBIDOS EN EL DEBATE Y PODRÁN SER EXAMINADOS POR LAS PARTES.', 'LOS INSTRUMENTOS O EFECTOS DEL DELITO, QUE OBREN O HAYAN SIDO INCORPORADOS AL JUICIO', 'ART. 382', '184457'),
    (1627, 'SUB-1627', 'SBM3', 'LOS VESTIGIOS INCAUTADOS O RECOGIDOS, SERÁN EXHIBIDOS EN EL DEBATE Y PODRÁN SER EXAMINADOS POR LAS PARTES, SIEMPRE:', 'QUE OBREN O HAYAN SIDO INCORPORADOS CON ANTERIORIDAD AL JUICIO', 'ART. 382', '184458'),
    (1628, 'SUB-1628', 'SBM3', 'CON QUE FINALIDAD LA PRUEBA MATERIAL PODRÁ SER PRESENTADA A LOS ACUSADOS, TESTIGOS Y PERITOS DURANTE SUS DECLARACIONES.', 'A FIN DE QUE LA RECONOZCAN O INFORMEN SOBRE ELLA', 'ART. 382', '184459'),
    (1629, 'SUB-1629', 'SBM3', '¿QUÉ DOCUMENTOS PODRÁN SER INCORPORADOS AL JUICIO PARA SU LECTURA?', 'LAS ACTAS CONTENIENDO LA PRUEBA ANTICIPADA', 'ART. 383', '184460'),
    (1630, 'SUB-1630', 'SBM3', '¿QUÉ DOCUMENTOS PODRÁN SER INCORPORADOS AL JUICIO PARA SU LECTURA?', 'LA DENUNCIA, LA PRUEBA DOCUMENTAL O DE INFORMES, Y LAS CERTIFICACIONES Y CONSTATACIONES', 'ART. 383', '184461'),
    (1631, 'SUB-1631', 'SBM3', '¿QUÉ DOCUMENTOS PODRÁN SER INCORPORADOS AL JUICIO PARA SU LECTURA?', 'LOS INFORMES O DICTÁMENES PERICIALES, LAS ACTAS DE EXAMEN Y DEBATE PERICIAL ACTUADAS', 'ART. 383', '184462'),
    (1632, 'SUB-1632', 'SBM3', 'EL FISCAL DE LA NACIÓN REGULARÁ MEDIANTE INSTRUCCIONES GENERALES LOS REQUISITOS LEGALES Y LAS FORMALIDADES DE LAS ACTUACIONES DE:.', 'INVESTIGACIÓN.', 'ART. 69', '184463'),
    (1633, 'SUB-1633', 'SBM3', '¿QUÉ DOCUMENTOS PODRÁN SER INCORPORADOS AL JUICIO PARA SU LECTURA? Código Procesal Penal', 'LAS ACTAS CONTENIENDO LA DECLARACIÓN DE TESTIGOS ACTUADAS MEDIANTE EXHORTO', 'ART. 383', '184464'),
    (1634, 'SUB-1634', 'SBM3', '¿QUÉ DOCUMENTOS PODRÁN SER INCORPORADOS AL JUICIO PARA SU LECTURA?', 'LAS DECLARACIONES PRESTADAS ANTE EL FISCAL CON LA CONCURRENCIA O EL DEBIDO EMPLAZAMIENTO DE LAS PARTES', 'ART. 383', '184465'),
    (1635, 'SUB-1635', 'SBM3', '¿DE QUÉ MANERA EL IMPUTADO PUEDE HACER VALER LOS DERECHOS QUE LA CONSTITUCIÓN Y LAS LEYES LE CONCEDEN, DESDE EL INICIO DE LAS PRIMERAS DILIGENCIAS DE INVESTIGACIÓN HASTA LA CULMINACIÓN DEL PROCESO?.', 'POR SÍ MISMO O A TRAVÉS DE SU ABOGADO DEFENSOR.', 'ART. 71. Num. 1', '184466'),
    (1636, 'SUB-1636', 'SBM3', '¿QUÉ DOCUMENTOS PODRÁN SER INCORPORADOS AL JUICIO PARA SU LECTURA?', 'LAS ACTAS LEVANTADAS POR LA POLICÍA, EL FISCAL O EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA', 'ART. 383', '184467'),
    (1637, 'SUB-1637', 'SBM3', '¿A QUIÉN SE LE APERCIBIRÁ CON LA SUSPENSIÓN DE LA DILIGENCIA Y DE CONTINUARLA CON LA SOLA INTERVENCIÓN DE SU ABOGADO DEFENSOR Y DEMÁS SUJETOS PROCESALES?', 'AL PROCESADO QUE ALTERE EL ORDEN EN UN ACTO PROCESAL', 'ART. 73. Num. 1', '184469'),
    (1638, 'SUB-1638', 'SBM3', 'DE ALTERAR UN ACTO PROCESAL ¿A QUIÉN SE LE EXCLUIRÁ DE PARTICIPAR EN LA DILIGENCIA Y DE CONTINUAR ÉSTA CON SU ABOGADO DEFENSOR Y DEMÁS SUJETOS PROCESALES?.', 'AL PROCESADO', 'ART. 73. Num. 1 Código Procesal Penal', '184470'),
    (1639, 'SUB-1639', 'SBM3', 'LA ORALIZACIÓN TENDRÁ LUGAR CUANDO INDISTINTAMENTE, LO PIDA:', 'EL FISCAL O LOS DEFENSORES', 'ART. 384', '184471'),
    (1640, 'SUB-1640', 'SBM3', 'LA ORALIZACIÓN SE REALIZARÁ POR SU ORDEN, INICIÁNDOLA EL', 'FISCAL', 'ART. 384', '184472'),
    (1641, 'SUB-1641', 'SBM3', '¿EN QUÉ CIRCUNSTANCIA EL DEFENSOR SERÁ SUSTITUIDO POR UNO NOMBRADO DE OFICIO?.', 'SI SE SOLIDARIZA Y ABANDONA LA DILIGENCIA.', 'ART. 73. Num. 2', '184473'),
    (1642, 'SUB-1642', 'SBM3', 'LA ORALIZACIÓN SE REALIZARÁ POR SU ORDEN, INICIÁNDOLA EL FISCAL, CONTINUÁNDOLA EL:', 'ABOGADO DEL ACTOR CIVIL', 'ART. 384', '184474'),
    (1643, 'SUB-1643', 'SBM3', 'SI SE ACREDITA LA MINORÍA DE EDAD, ¿EN QUÉ ETAPA, EL JUEZ, PREVIA AUDIENCIA Y CON INTERVENCIÓN DE LAS PARTES, DICTARÁ LA RESOLUCIÓN CORRESPONDIENTE?.', 'EN LA ETAPA INTERMEDIA O EN EL JUICIO ORAL.', 'ART. 74. Num. 2', '184475'),
    (1644, 'SUB-1644', 'SBM3', 'CUANDO LOS DOCUMENTOS O INFORMES FUERAN MUY VOLUMINOSOS, SE PODRÁ.', 'PRESCINDIR DE SU LECTURA ÍNTEGRA', 'ART. 384', '184476'),
    (1645, 'SUB-1645', 'SBM3', '¿QUÉ ES LO QUE NO ALTERARÁ EL CURSO DE LAS ACTUACIONES PROCESALES Y LOS ERRORES SOBRE ELLOS PODRÁN SER CORREGIDOS EN CUALQUIER OPORTUNIDAD?. Código Procesal Penal', 'LA DUDA SOBRE LOS DATOS OBTENIDOS.', 'ART. 72. Num. 3', '184477'),
    (1646, 'SUB-1646', 'SBM3', 'TODA PERSONA PARA QUE PREPARE SU DEFENSA, TAMBIÉN TIENE DERECHO A QUE SE LE CONCEDA UN:', 'TIEMPO RAZONABLE', 'TÍTULO PRELIMINAR ART. IX', '184478'),
    (1647, 'SUB-1647', 'SBM3', '¿CUÁNDO SE LE COMUNICARÁ AL IMPUTADO, DETALLADAMENTE EL HECHO OBJETO DE IMPUTACIÓN, LOS ELEMENTOS DE CONVICCIÓN Y DE PRUEBAS EXISTENTES, Y LAS DISPOSICIONES PENALES QUE SE CONSIDEREN APLICABLES?.', 'ANTES DE COMENZAR LA DECLARACIÓN.', 'ART. 87. Num. 1', '184479'),
    (1648, 'SUB-1648', 'SBM3', 'SI PARA CONOCER LOS HECHOS, SIEMPRE QUE SEA POSIBLE, QUE NO SE HAYA REALIZADO DICHA DILIGENCIA EN LA INVESTIGACIÓN PREPARATORIA O ESTA RESULTARÁ MANIFIESTAMENTE INSUFICIENTE, PREVIO DEBATE DE LOS INTERVINIENTES, QUIEN Y EN QUE CASOS ORDENARÁ LA REALIZACIÓN DE UNA INSPECCIÓN O DE UNA RECONSTRUCCIÓN:', 'EL JUEZ PENAL, DE OFICIO O A PEDIDO DE PARTE', 'ART. 385', '184480'),
    (1649, 'SUB-1649', 'SBM3', 'EXCEPCIONALMENTE, UNA VEZ CULMINADA LA RECEPCIÓN DE LAS PRUEBAS, PODRÁ DISPONER, DE OFICIO O A PEDIDO DE PARTE, LA ACTUACIÓN DE NUEVOS MEDIOS PROBATORIOS:', 'EL JUEZ PENAL', 'ART. 385', '184481'),
    (1650, 'SUB-1650', 'SBM3', 'CONCLUIDO EL DEBATE PROBATORIO, EN QUE ORDEN SE DESARROLLARÁ LA EXPOSICIÓN ORAL DEL FISCAL.', 'PRIMER ORDEN', 'ART. 386', '184482'),
    (1651, 'SUB-1651', 'SBM3', 'CONCLUIDO EL DEBATE PROBATORIO, EN QUE ORDEN SE DESARROLLARÁ LA DISCUSIÓN FINAL, ALEGATOS DE LOS ABOGADOS DEL ACTOR CIVIL Y DEL TERCERO CIVIL.', 'SEGUNDO ORDEN', 'ART. 386', '184483'),
    (1652, 'SUB-1652', 'SBM3', 'CONCLUIDO EL DEBATE PROBATORIO, EN QUE ORDEN SE DESARROLLARÁ LA DISCUSIÓN FINAL, ALEGATOS DEL ABOGADO DEFENSOR DEL ACUSADO.', 'TERCER ORDEN', 'ART. 386', '184484'),
    (1653, 'SUB-1653', 'SBM3', 'CONCLUIDO EL DEBATE PROBATORIO, EN QUE ORDEN SE DESARROLLARÁ LA DISCUSIÓN FINAL, LA AUTODEFENSA DEL ACUSADO.', 'CUARTO ORDEN', 'ART. 386', '184485'),
    (1654, 'SUB-1654', 'SBM3', 'EN CASO DE MANIFIESTO ABUSO DE LA PALABRA, QUE PARTE DEL PROCESO, LLAMARÁ LA ATENCIÓN AL ORADOR Y, SI ÉSTE PERSISTIERE, PODRÁ FIJARLE UN TIEMPO LÍMITE, EN EL QUE INDEFECTIBLEMENTE DARÁ POR CONCLUIDO EL ALEGATO.', 'EL JUEZ PENAL', 'ART. 386', '184486'),
    (1655, 'SUB-1655', 'SBM3', 'EN QUÉ CASO, EL JUEZ PENAL DECLARARÁ CERRADO EL DEBATE:', 'CULMINADA LA AUTODEFENSA DEL ACUSADO', 'ART. 386', '184487'),
    (1656, 'SUB-1656', 'SBM3', 'EXPEDIDA CON POSTERIORIDAD A LA ACTUACIÓN PROCESAL, ¿QUÉ SE APLICARÁ RETROACTIVAMENTE, INCLUSO PARA LOS ACTOS YA CONCLUIDOS, SI FUERA POSIBLE?', 'LA LEY PROCESAL REFERIDA A DERECHOS INDIVIDUALES QUE SEA MÁS FAVORABLE AL IMPUTADO', 'TÍTULO PRELIMINAR ART. VII Código Procesal Penal', '184489'),
    (1657, 'SUB-1657', 'SBM3', 'SI EL FISCAL CONSIDERA QUE DEL JUICIO HAN SURGIDO NUEVAS RAZONES PARA PEDIR AUMENTO O DISMINUCIÓN DE LA PENA O LA REPARACIÓN CIVIL SOLICITADAS EN LA ACUSACIÓN ESCRITA, QUE ACCIONES ADOPTARÁ AL RESPECTO:', 'DESTACARÁ DICHAS RAZONES Y PEDIRÁ LA ADECUACIÓN DE LA PENA O REPARACIÓN CIVIL', 'ART. 387', '184490'),
    (1658, 'SUB-1658', 'SBM3', 'EN QUÉ CASOS, EL FISCAL RETIRARÁ LOS CARGOS FORMULADOS AL ACUSADO:', 'CUANDO HAN SIDO ENERVADOS EN EL JUICIO', 'ART. 387', '184491'),
    (1659, 'SUB-1659', 'SBM3', 'CUANTO TENGA POR CONVENIENTE SOBRE EL HECHO QUE SE LE ATRIBUYE Y PARA INDICAR, DE SER POSIBLE O CONSIDERARLO OPORTUNO, LOS ACTOS DE INVESTIGACIÓN O DE PRUEBA CUYA PRÁCTICA DEMANDE, SE INVITARÁ AL:.', 'IMPUTADO A QUE DECLARE.', 'ART. 88. Num. 2', '184493'),
    (1660, 'SUB-1660', 'SBM3', 'EN EL ALEGATO ORAL DEL ACTOR CIVIL, EL ABOGADO ESTÁ PROHIBIDO DE:', 'CALIFICAR EL DELITO', 'ART. 388', '184494'),
    (1661, 'SUB-1661', 'SBM3', 'DECLARACIÓN DEL IMPUTADO: LA DILIGENCIA SE INICIARÁ REQUIRIENDO AL IMPUTADO DECLARAR RESPECTO A:', 'NOMBRE, APELLIDOS, SOBRENOMBRE O APODO SI LO TUVIERE, LUGAR Y FECHA DE NACIMIENTO, PRINCIPALES SITIOS DE RESIDENCIA ANTERIOR', 'ART. 88', '184495'),
    (1662, 'SUB-1662', 'SBM3', 'EN EL ALEGATO ORAL DEL ACTOR CIVIL, EL ABOGADO PODRÁ:', 'ESCLARECER CON TODA AMPLITUD LOS HECHOS DELICTUOSOS', 'ART. 388', '184496'),
    (1663, 'SUB-1663', 'SBM3', 'LA DILIGENCIA SE INICIARÁ REQUIRIENDO AL IMPUTADO DECLARAR RESPECTO A:.', 'ESTADO CIVIL, PROFESIÓN U OCUPACIÓN Y DOMICILIO REAL Y PROCESAL.', 'ART. 88. Num. 1. a)', '184497'),
    (1664, 'SUB-1664', 'SBM3', 'LA DILIGENCIA SE INICIARÁ REQUIRIENDO AL IMPUTADO DECLARAR RESPECTO A:.', 'NOMBRE Y APELLIDOS DE SUS PADRES, CONYUGE E HIJOS Y DE LAS PERSONAS CON QUIENES VIVE.', 'ART. 88. Num. 1. a)', '184498'),
    (1665, 'SUB-1665', 'SBM3', 'LA DILIGENCIA SE INICIARÁ REQUIRIENDO AL IMPUTADO DECLARAR RESPECTO A:.', 'SI HA SIDO ENCAUSADO ANTERIORMENTE POR EL MISMO HECHO O POR OTROS.', 'ART. 88. Num. 1. b)', '184499'),
    (1666, 'SUB-1666', 'SBM3', 'EN EL ALEGATO ORAL DEL ABOGADO DEL TERCERO CIVIL, EL ABOGADO PODRÁ:', 'NEGAR LA EXISTENCIA DEL HECHO DELICTIVO ATRIBUIDO AL ACUSADO', 'ART. 389', '184500'),
    (1667, 'SUB-1667', 'SBM3', 'EN EL ALEGATO ORAL DEL ABOGADO DEL TERCERO CIVIL, EL ABOGADO PODRÁ:', 'REFUTAR LA EXISTENCIA DE LA RESPONSABILIDAD CIVIL SOLIDARIA QUE LE ATRIBUYE LA ACUSACIÓN', 'ART. 389', '184501'),
    (1668, 'SUB-1668', 'SBM3', 'EN QUE CASO, SE DARÁ POR TERMINADA LA EXPOSICIÓN DEL ACUSADO:', 'SI INCUMPLE CON LA LIMITACIÓN IMPUESTA', 'ART. 391 Código Procesal Penal', '184504'),
    (1669, 'SUB-1669', 'SBM3', 'EN EL DESARROLLO DE LA DECLARACIÓN, SE INTERROGARÁ AL IMPUTADO. EN EL JUICIO PARTICIPARÁN EN EL INTERROGATORIO TODAS LAS PARTES MEDIANTE:.', 'UN INTERROGATORIO DIRECTO.', 'ART. 88. Num. 3', '184505'),
    (1670, 'SUB-1670', 'SBM3', 'EN EL DESARROLLO DE LA DECLARACIÓN, SE INTERROGARÁ AL IMPUTADO. EL JUEZ PODRÁ HACERLO, EXCEPCIONALMENTE, PARA:.', 'CUBRIR ALGÚN VACÍO EN EL INTERROGATORIO.', 'ART. 88. Num. 3', '184506'),
    (1671, 'SUB-1671', 'SBM3', 'EN LO QUE RESPECTA A LA SENTENCIA, PARA IMPONER LA PENA DE CADENA PERPETUA SE REQUERIRÁ:', 'DECISIÓN UNÁNIME', 'ART. 392', '184507'),
    (1672, 'SUB-1672', 'SBM3', 'RESPECTO A LA SENTENCIA. TRANSCURRIDO EL PLAZO SIN QUE SE PRODUZCA EL FALLO, EL JUICIO DEBERÁ:', 'REPETIRSE ANTE OTRO JUZGADO', 'ART. 392', '184508'),
    (1673, 'SUB-1673', 'SBM3', 'EN EL DESARROLLO DE LA DECLARACIÓN. PODRÁ REALIZARSE EN DICHO ACTO LAS DILIGENCIAS DE RECONOCIMIENTO DE DOCUMENTOS, DE PERSONAS, DE:.', 'VOCES O SONIDOS.', 'ART. 88. Num. 5', '184509'),
    (1674, 'SUB-1674', 'SBM3', 'EN EL DESARROLLO DE LA DECLARACIÓN. LA DECLARACIÓN SERÁ SUSPENDIDA, HASTA QUE ELLOS DESAPAREZCAN, SI POR LA DURACIÓN DEL ACTO SE NOTEN:.', 'SIGNOS DE FATIGA O FALTA DE SERENIDAD EN EL IMPUTADO.', 'ART. 88. Num. 6 Código Procesal Penal', '184510'),
    (1675, 'SUB-1675', 'SBM3', 'EN QUE MOMENTO, LA SENTENCIA SERÁ REDACTADA POR EL JUEZ O EL DIRECTOR DEL DEBATE SEGÚN EL CASO:', 'INMEDIATAMENTE DESPUÉS DE LA DELIBERACIÓN', 'ART. 395', '184511'),
    (1676, 'SUB-1676', 'SBM3', 'EN EL DESARROLLO DE LA DECLARACIÓN. DURANTE LA INVESTIGACIÓN PREPARATORIA, DE QUÉ MODO SE REPRODUCIRÁ EN EL ACTA QUE CONTENGA LA DECLARACIÓN DEL IMPUTADOLO, LO QUE SUCEDA EN LA DILIGENCIA:.', 'DEL MODO MÁS FIEL POSIBLE.', 'ART. 88. Num. 7', '184512'),
    (1677, 'SUB-1677', 'SBM3', 'EL IMPUTADO, CUANDO ESTUVIERA PRIVADO DE SU LIBERTAD, LA DILIGENCIA SE PODRÁ LLEVAR A CABO EN RECINTOS CERRADOS APROPIADOS PARA IMPEDIR:.', 'SU FUGA.', 'ART. 89. Num. 1', '184513'),
    (1678, 'SUB-1678', 'SBM3', 'CUANDO POR LA COMPLEJIDAD DEL ASUNTO SEA NECESARIO DIFERIR LA REDACCIÓN DE LA SENTENCIA, LUEGO QUE UNO DE LOS JUECES RELATARÁ SINTÉTICAMENTE AL PÚBLICO LOS FUNDAMENTOS QUE MOTIVARON LA DECISIÓN, ANUNCIARÁ DÍA Y LA HORA PARA LA LECTURA INTEGRAL, QUE SE LLEVARÁ EN:', 'PLAZO MÁXIMO DE LOS OCHO DÍAS POSTERIORES AL PRONUNCIAMIENTO', 'ART. 396', '184514'),
    (1679, 'SUB-1679', 'SBM3', 'CUANDO HUBIERE VARIOS IMPUTADOS, ANTES DE LA RECEPCIÓN DE SUS DECLARACIONES, SE RECIBIRÁ LAS MISMAS, EVITANDO:.', 'QUE SE COMUNIQUEN ENTRE SÍ.', 'ART. 89. Num. 2', '184515'),
    (1680, 'SUB-1680', 'SBM3', 'COMO QUEDARÁ NOTIFICADA LA SENTENCIA CON SU LECTURA INTEGRAL EN:', 'AUDIENCIA PÚBLICA', 'ART. 396', '184516'),
    (1681, 'SUB-1681', 'SBM3', 'LA VALORACIÓN PROBATORIA RESPETARÁ LAS REGLAS DE LA SANA CRÍTICA, ESPECIALMENTE CONFORME A:', 'LOS PRINCIPIOS DE LA LÓGICA, LAS MÁXIMAS DE LA EXPERIENCIA Y LOS CONOCIMIENTOS CIENTÍFICOS.', 'ART. 393', '184517'),
    (1682, 'SUB-1682', 'SBM3', 'LA SENTENCIA CONTENDRÁ:', 'LA MOTIVACIÓN CLARA, LÓGICA Y COMPLETA DE CADA UNO DE LOS HECHOS', 'ART. 394', '184518'),
    (1683, 'SUB-1683', 'SBM3', 'EN LO QUE RESPECTA A LA SENTENCIA, SE DICE QUE NO SE PODRÁ MODIFICAR LA CALIFICACIÓN JURÍDICA DEL HECHO OBJETO DE LA ACUSACIÓN O SU AMPLIATORIA, SALVO QUE EL JUEZ PENAL HAYA DADO CUMPLIMIENTO AL NUMERAL 1) DEL ARTÍCULO 374; ESTO ESTÁ REFERIDO A LA:', 'CONDENA', 'ART. 397', '184519'),
    (1684, 'SUB-1684', 'SBM3', 'LA SENTENCIA ABSOLUTORIA ORDENARÁ:', 'LA LIBERTAD DEL ACUSADO', 'ART. 398', '184520'),
    (1685, 'SUB-1685', 'SBM3', 'LA SENTENCIA ABSOLUTORIA ORDENARÁ:', 'LA CESACIÓN DE LAS MEDIDAS DE COERCIÓN', 'ART. 398', '184521'),
    (1686, 'SUB-1686', 'SBM3', 'LA SENTENCIA ABSOLUTORIA ORDENARÁ:', 'LA RESTITUCIÓN DE LOS OBJETOS AFECTADOS AL PROCESO QUE NO ESTÉN SUJETOS A COMISO', 'ART. 398', '184522'),
    (1687, 'SUB-1687', 'SBM3', 'LA SENTENCIA ABSOLUTORIA ORDENARÁ:', 'LA ANULACIÓN DE LOS ANTECEDENTES POLICIALES Y JUDICIALES QUE GENERÓ EL CASO', 'ART. 398', '184523'),
    (1688, 'SUB-1688', 'SBM3', 'SI DE LAS PRUEBAS ACTUADAS RESULTARA QUE UN TESTIGO HA DECLARADO FALSAMENTE, LA SENTENCIA DISPONDRÁ QUE ESTOS HECHOS SE PONGAN EN CONOCIMIENTO DE:', 'LA FISCALÍA COMPETENTE PARA LOS FINES LEGALES QUE CORRESPONDAN', 'ART. 400', '184524'),
    (1689, 'SUB-1689', 'SBM3', 'SI DE LAS PRUEBAS ACTUADAS, SE INFIERE RESPONSABILIDAD PENAL DE CUALQUIER OTRA PERSONA NO COMPRENDIDA EN EL PROCESO, LA SENTENCIA DISPONDRÁ QUE ESTOS HECHOS SE PONGAN EN CONOCIMIENTO DE:', 'LA FISCALÍA COMPETENTE PARA LOS FINES LEGALES QUE CORRESPONDAN', 'ART. 400', '184525'),
    (1690, 'SUB-1690', 'SBM3', 'SI DE LAS PRUEBAS ACTUADAS, SE DESCUBRE OTRO HECHO DELICTUOSO SIMILAR, DISTINTO O CONEXO CON EL QUE ES MATERIA DEL JUZGAMIENTO Y ES PERSEGUIBLE POR EJERCICIO PÚBLICO DE LA ACCIÓN PENAL, LA SENTENCIA DISPONDRÁ QUE ESTOS HECHOS SE PONGAN EN CONOCIMIENTO DE:', 'LA FISCALÍA COMPETENTE PARA LOS FINES LEGALES QUE CORRESPONDAN', 'ART. 400', '184526'),
    (1691, 'SUB-1691', 'SBM3', '¿CUÁNDO SE REQUERIRÁ A SU ÓRGANO SOCIAL QUE DESIGNE UN APODERADO JUDICIAL?', 'UNA VEZ QUE LA PERSONA JURÍDICA ES INCORPORADA AL PROCESO', 'ART. 92', '184527'),
    (1692, 'SUB-1692', 'SBM3', 'SI SE IMPONE PENA PRIVATIVA DE LIBERTAD EFECTIVA, PARA LOS EFECTOS DEL CÓMPUTO SE DESCONTARÁ, DE SER EL CASO:', 'EL TIEMPO DE DETENCIÓN DOMICILIARIA', 'ART. 399', '184528'),
    (1693, 'SUB-1693', 'SBM3', 'NO PODRÁ DESIGNARSE COMO APODERADO JUDICIAL A LA PERSONA NATURAL IMPUTADA POR:', 'LOS MISMOS HECHOS', 'ART. 92', '184529'),
    (1694, 'SUB-1694', 'SBM3', 'SI SE IMPONE PENA PRIVATIVA DE LIBERTAD EFECTIVA, PARA LOS EFECTOS DEL CÓMPUTO SE DESCONTARÁ, DE SER EL CASO:', 'LA PRIVACIÓN DE LIBERTAD SUFRIDA EN EL EXTRANJERO COMO CONSECUENCIA DEL PROCEDIMIENTO DE EXTRADICIÓN', 'ART. 399', '184530'),
    (1695, 'SUB-1695', 'SBM3', '¿CÓMO SE CONSIDERA A TODO AQUÉL QUE RESULTE DIRECTAMENTE OFENDIDO POR EL DELITO O PERJUDICADO POR LAS CONSECUENCIAS DEL MISMO?', 'AGRAVIADO', 'ART. 94. Num. 1', '184531'),
    (1696, 'SUB-1696', 'SBM3', 'QUÉ SE CUMPLE PROVISIONALMENTE, EN SU EXTREMO PENAL, AUNQUE SE INTERPONGA RECURSO CONTRA ELLA.', 'LA SENTENCIA CONDENATORIA', 'ART. 402', '184532'),
    (1697, 'SUB-1697', 'SBM3', 'DURANTE LAS ACTUACIONES EN LAS QUE INTERVENGA, QUIÉN TENDRÁ DERECHO A QUE SEA ACOMPAÑADO POR PERSONA DE SU CONFIANZA:.', 'EL AGRAVIADO SI FUERA MENOR O INCAPAZ.', 'ART. 95. Num. 3', '184533'),
    (1698, 'SUB-1698', 'SBM3', 'SE INSCRIBIRÁN EN EL REGISTRO CORRESPONDIENTE, A CARGO DEL PODER JUDICIAL, TODAS LAS PENAS Y MEDIDAS DE SEGURIDAD IMPUESTAS Y QUE CONSTAN DE:', 'SENTENCIA FIRME', 'ART. 403', '184534'),
    (1699, 'SUB-1699', 'SBM3', 'A CARGO DE QUE ORGANISMO, SE INSCRIBIRÁN EN EL REGISTRO CORRESPONDIENTE TODAS LAS PENAS Y MEDIDAS DE SEGURIDAD IMPUESTAS Y QUE CONSTAN DE SENTENCIA FIRME.', 'PODER JUDICIAL', 'ART. 403', '184535'),
    (1700, 'SUB-1700', 'SBM3', '¿CUÁNDO Y CÓMO CADUCARÁ LA INSCRIPCIÓN DE LA CONDENA?', 'AUTOMÁTICAMENTE CON EL CUMPLIMIENTO DE LA PENA O MEDIDA DE SEGURIDAD IMPUESTA', 'ART. 403', '184536')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

