INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1701 a 1800
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1701, 'SUB-1701', 'SBM3', '¿A QUIÉN LE ASISTE EL DERECHO DE IMPUGNAR LAS RESOLUCIONES JUDICIALES?', 'SÓLO A QUIEN LA LEY SE LO CONFIERE EXPRESAMENTE', 'ART. 404', '184537'),
    (1702, 'SUB-1702', 'SBM3', 'PODRÁ RECURRIR DIRECTAMENTE EN FAVOR DE SU PATROCINADO, QUIEN POSTERIORMENTE SI NO ESTÁ CONFORME PODRÁ DESISTIRSE:', 'EL DEFENSOR', 'ART. 404', '184538'),
    (1703, 'SUB-1703', 'SBM3', 'EL DESISTIMIENTO DEL RECURSO IMPUGNATORIO, REQUIERE AUTORIZACIÓN EXPRESA DEL:', 'ABOGADO DEFENSOR', 'ART. 404', '184539'),
    (1704, 'SUB-1704', 'SBM3', '¿QUÉ ACTO PROCESAL EFECTUADO CONTRA LAS RESOLUCIONES FINALES EXPEDIDAS EN LA AUDIENCIA, SE FORMALIZARÁN POR ESCRITO EN EL PLAZO DE CINCO DÍAS?', 'LOS RECURSOS INTERPUESTOS ORALMENTE', 'ART. 405', '184540'),
    (1705, 'SUB-1705', 'SBM3', '¿QUÉ AUTORIDAD SE PRONUNCIARÁ SOBRE LA ADMISIÓN DEL RECURSO Y NOTIFICARÁ SU DECISIÓN A TODAS LAS PARTES, LUEGO DE LO CUAL INMEDIATAMENTE ELEVARÁ LOS ACTUADOS AL ÓRGANO JURISDICCIONAL COMPETENTE?', 'EL JUEZ QUE EMITIÓ LA RESOLUCIÓN IMPUGNADA', 'ART. 405', '184541'),
    (1706, 'SUB-1706', 'SBM3', 'DESISTIMIENTO.- PUEDEN DESISTIRSE ANTES DE EXPEDIRSE RESOLUCIÓN SOBRE EL GRADO, EXPRESANDO SUS FUNDAMENTOS', 'QUIENES HAYAN INTERPUESTO UN RECURSO', 'ART. 406', '184542'),
    (1707, 'SUB-1707', 'SBM3', 'DESISTIMIENTO.- ¿QUIÉN NO PODRÁ DESISTIRSE DE LOS RECURSOS INTERPUESTOS POR ÉL SIN MANDATO EXPRESO DE SU PATROCINADO, POSTERIOR A LA INTERPOSICIÓN DEL RECURSO?', 'EL DEFENSOR', 'ART. 406', '184543'),
    (1708, 'SUB-1708', 'SBM3', '¿QUIÉNES PODRÁN IMPUGNAR, INDISTINTAMENTE, DEL OBJETO PENAL O DEL OBJETO CIVIL DE LA RESOLUCIÓN?', 'EL IMPUTADO Y EL MINISTERIO PÚBLICO', 'ART. 407', '184544'),
    (1709, 'SUB-1709', 'SBM3', '¿A QUIÉN FAVORECE LA IMPUGNACIÓN PRESENTADA POR EL IMPUTADO?', 'AL TERCERO CIVIL', 'ART. 408', '184545'),
    (1710, 'SUB-1710', 'SBM3', '¿A QUIÉN FAVORECE LA IMPUGNACIÓN PRESENTADA POR EL TERCERO CIVIL?', 'AL IMPUTADO', 'ART. 408', '184546'),
    (1711, 'SUB-1711', 'SBM3', '¿QUÉ ACTO PROCESAL EFECTUADO POR EL MINISTERIO PÚBLICO PERMITIRÁ REVOCAR O MODIFICAR LA RESOLUCIÓN AÚN A FAVOR DEL IMPUTADO?', 'LA IMPUGNACIÓN', 'ART. 409', '184547'),
    (1712, 'SUB-1712', 'SBM3', 'RESPECTO A UNA SENTENCIA PENDIENTE DE RECURSO, QUIENES SERÁN PUESTOS EN LIBERTAD INMEDIATAMENTE:', 'LOS IMPUTADOS QUE HAYAN SOBREPASADO EL TIEMPO DE LA PENA IMPUESTA POR UNA SENTENCIA PENDIENTE DE RECURSO', 'ART. 411', '184548'),
    (1713, 'SUB-1713', 'SBM3', 'LAS IMPUGNACIONES CONTRA LAS SENTENCIAS Y DEMÁS RESOLUCIONES NO PODRÁN TENER EFECTO SUSPENSIVO QUE:', 'DISPONGAN LA LIBERTAD DEL IMPUTADO', 'ART. 412', '184549'),
    (1714, 'SUB-1714', 'SBM3', 'SEÑALE CUÁLES SON LOS RECURSOS QUE SE INTERPONEN CONTRA LAS RESOLUCIONES JUDICIALES:', 'RECURSOS DE REPOSICIÓN, APELACIÓN, CASACIÓN Y QUEJA', 'ART. 413', '184550'),
    (1715, 'SUB-1715', 'SBM3', 'SEÑALE UNO DE LOS RECURSOS QUE SE INTERPONEN CONTRA LAS RESOLUCIONES JUDICIALES:', 'RECURSO DE REPOSICIÓN', 'ART. 413', '184551'),
    (1716, 'SUB-1716', 'SBM3', 'SEÑALE UNO DE LOS RECURSOS QUE SE INTERPONEN CONTRA LAS RESOLUCIONES JUDICIALES:', 'RECURSO DE APELACIÓN', 'ART. 413', '184552'),
    (1717, 'SUB-1717', 'SBM3', 'SEÑALE UNO DE LOS RECURSOS QUE SE INTERPONEN CONTRA LAS RESOLUCIONES JUDICIALES:', 'RECURSO DE CASACIÓN', 'ART. 413', '184553'),
    (1718, 'SUB-1718', 'SBM3', 'SEÑALE UNO DE LOS RECURSOS QUE SE INTERPONEN CONTRA LAS RESOLUCIONES JUDICIALES:', 'RECURSO DE QUEJA', 'ART. 413', '184554'),
    (1719, 'SUB-1719', 'SBM3', '¿EN QUÉ PLAZO SE INTERPONE EL RECURSO DE CASACIÓN?', 'DIEZ DÍAS', 'ART. 414', '184555'),
    (1720, 'SUB-1720', 'SBM3', '¿EN QUÉ PLAZO SE INTERPONE EL RECURSO DE REPOSICIÓN?', 'DOS DÍAS', 'ART. 414', '184556'),
    (1721, 'SUB-1721', 'SBM3', 'LA ACCIÓN PENAL ES:', 'PÚBLICA', 'ART. 1', '184557'),
    (1722, 'SUB-1722', 'SBM3', 'LA ACCIÓN PENAL, EN LOS DELITOS DE PERSECUCIÓN PRIVADA CORRESPONDE EJERCERLA AL:', 'DIRECTAMENTE OFENDIDO Código Procesal Penal', 'ART. 1', '184558'),
    (1723, 'SUB-1723', 'SBM3', '¿QUÉ NECESITA EL DIRECTAMENTE OFENDIDO, PARA EJERCER UNA ACCIÓN PENAL EN UN DELITO DE PERSECUCIÓN PRIVADA, ANTE EL ÓRGANO JURISDICCIONAL COMPETENTE?', 'PRESENTACIÓN DE QUERELLA', 'ART. 1', '184559'),
    (1724, 'SUB-1724', 'SBM3', 'EN LOS DELITOS QUE REQUIEREN LA PREVIA INSTANCIA DEL DIRECTAMENTE OFENDIDO POR EL DELITO, EL EJERCICIO DE LA ACCIÓN PENAL POR EL MINISTERIO PÚBLICO ESTÁ CONDICIONADO A LA DENUNCIA DE:', 'LA PERSONA AUTORIZADA PARA HACERLO', 'ART. 1', '184560'),
    (1725, 'SUB-1725', 'SBM3', 'CUANDO CORRESPONDE LA PREVIA AUTORIZACIÓN DEL CONGRESO O DE OTRO ÓRGANO PÚBLICO PARA EL EJERCICIO DE LA ACCIÓN PENAL, SE OBSERVARÁ EL PROCEDIMIENTO PREVISTO POR LA LEY PARA DEJAR EXPEDITA LA:', 'PROMOCIÓN DE LA ACCIÓN PENAL', 'ART. 1', '184561'),
    (1726, 'SUB-1726', 'SBM3', '¿EN QUÉ CASO EL MINISTERIO PÚBLICO, DE OFICIO O A PEDIDO DEL IMPUTADO Y CON SU CONSENTIMIENTO, PODRÁ ABSTENERSE DE EJERCITAR LA ACCIÓN PENAL?', 'CUANDO EL AGENTE HAYA SIDO AFECTADO GRAVEMENTE POR LAS CONSECUENCIAS DE SU DELITO', 'ART. 2', '184562'),
    (1727, 'SUB-1727', 'SBM3', '¿EN QUÉ CASO EL MINISTERIO PÚBLICO, DE OFICIO O A PEDIDO DEL IMPUTADO Y CON SU CONSENTIMIENTO, PODRÁ ABSTENERSE DE EJERCITAR LA ACCIÓN PENAL?', 'CUANDO SE TRATE DE DELITOS QUE NO AFECTEN GRAVEMENTE EL INTERÉS PÚBLICO', 'ART. 2', '184563'),
    (1728, 'SUB-1728', 'SBM3', '¿EN QUÉ CASO EL MINISTERIO PÚBLICO, DE OFICIO O A PEDIDO DEL IMPUTADO Y CON SU CONSENTIMIENTO, PODRÁ ABSTENERSE DE EJERCITAR LA ACCIÓN PENAL?', 'CUANDO SE ADVIERTA QUE NO EXISTE NINGÚN INTERÉS PÚBLICO GRAVEMENTE COMPROMETIDO EN SU PERSECUCIÓN', 'ART. 2', '184564'),
    (1729, 'SUB-1729', 'SBM3', '¿QUÉ PODRÁ DETERMINAR EL FISCAL, EN CASO DE INASISTENCIA DEL AGRAVIADO?', 'EL MONTO DE LA REPARACIÓN CIVIL QUE CORRESPONDA', 'ART. 2', '184565'),
    (1730, 'SUB-1730', 'SBM3', 'SI NO SE LLEGA A UN ACUERDO SOBRE EL PLAZO PARA EL PAGO DE LA REPARACIÓN CIVIL, EL FISCAL LO FIJARÁ SIN QUE ÉSTE EXCEDA DE:', 'NUEVE MESES', 'ART. 2', '184566'),
    (1731, 'SUB-1731', 'SBM3', 'NO SERÁ NECESARIA LA DILIGENCIA DE DETERMINACIÓN DE LA REPARACIÓN CIVIL, SI EL IMPUTADO Y LA VÍCTIMA LLEGAN A UN ACUERDO Y ÉSTE CONSTA EN:', 'INSTRUMENTO PÚBLICO O DOCUMENTO PRIVADO LEGALIZADO NOTARIALMENTE', 'ART. 2', '184567'),
    (1732, 'SUB-1732', 'SBM3', 'HABIENDO LLEGADO A UN ACUERDO EL IMPUTADO Y LA VÍCTIMA, Y SATISFECHA LA REPARACIÓN CIVIL, EL FISCAL EXPEDIRÁ:', 'UNA DISPOSICIÓN DE ABSTENCIÓN', 'ART. 2', '184568'),
    (1733, 'SUB-1733', 'SBM3', 'DE EXISTIR UN PLAZO PARA EL PAGO DE LA REPARACIÓN CIVIL, SE SUSPENDERÁN LOS EFECTOS DE DICHA DECISIÓN HASTA:', 'SU EFECTIVO CUMPLIMIENTO', 'ART. 2', '184569'),
    (1734, 'SUB-1734', 'SBM3', 'DE NO PRODUCIRSE EL PAGO DE LA REPARACIÓN CIVIL, SE DICTARÁ DISPOSICIÓN PARA LA PROMOCIÓN DE LA ACCIÓN PENAL, LA CUAL:', 'NO SERÁ IMPUGNABLE', 'ART. 2', '184570'),
    (1735, 'SUB-1735', 'SBM3', 'SEGÚN EL PRINCIPIO DE OPORTUNIDAD, ¿QUÉ PROPONDRÁ EL FISCAL DE OFICIO O A PEDIDO DEL IMPUTADO O DE LA VÍCTIMA?', 'UN ACUERDO REPARATORIO', 'ART. 2', '184571'),
    (1736, 'SUB-1736', 'SBM3', '¿QUÉ ACCIÓN ADOPTARÁ EL FISCAL, SI EL IMPUTADO NO CONCURRE A LA SEGUNDA CITACIÓN O SE IGNORA SU DOMICILIO O PARADERO?', 'PROMOVERÁ LA ACCIÓN PENAL', 'ART. 2', '184572'),
    (1737, 'SUB-1737', 'SBM3', 'SI LA ACCIÓN PENAL HUBIERA SIDO PROMOVIDA, PREVIA AUDIENCIA, A PETICIÓN DEL MINISTERIO PÚBLICO, CON LA APROBACIÓN DEL IMPUTADO Y CITACIÓN DEL AGRAVIADO, EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA PODRÁ:', 'DICTAR AUTO DE SOBRESEIMIENTO', 'ART. 2', '184573'),
    (1738, 'SUB-1738', 'SBM3', 'EL MINISTERIO PÚBLICO COMUNICARÁ AL JUEZ DE LA INVESTIGACIÓN PREPARATORIA SU DECISIÓN FORMAL DE CONTINUAR CON LAS:', 'INVESTIGACIONES PREPARATORIAS', 'ART. 3', '184574'),
    (1739, 'SUB-1739', 'SBM3', 'LA CUESTIÓN PREVIA PROCEDE CUANDO EL FISCAL DECIDE CONTINUAR CON LA INVESTIGACIÓN PREPARATORIA:', 'OMITIENDO UN REQUISITO DE PROCEDIBILIDAD', 'ART. 4', '184575'),
    (1740, 'SUB-1740', 'SBM3', 'EN LA CUESTIÓN PREVIA, LA INVESTIGACIÓN PREPARATORIA PODRÁ REINICIARSE LUEGO QUE EL REQUISITO OMITIDO SEA: Código Procesal Penal', 'SATISFECHO', 'ART. 4', '184576'),
    (1741, 'SUB-1741', 'SBM3', 'LA CUESTIÓN PREJUDICIAL PROCEDE CUANDO EL FISCAL DECIDE CONTINUAR CON LA INVESTIGACIÓN PREPARATORIA, PESE A QUE FUERE NECESARIA EN VÍA EXTRA-PENAL UNA DECLARACIÓN VINCULADA AL CARÁCTER DELICTUOSO DEL:', 'HECHO INCRIMINADO', 'ART. 5', '184577'),
    (1742, 'SUB-1742', 'SBM3', 'SI SE DECLARA FUNDADA, LA INVESTIGACIÓN PREPARATORIA SE SUSPENDE HASTA QUE EN LA OTRA VÍA RECAIGA:', 'RESOLUCIÓN FIRME', 'ART. 5', '184578'),
    (1743, 'SUB-1743', 'SBM3', 'EN CASO DE QUE EL PROCESO EXTRA-PENAL NO HAYA SIDO PROMOVIDO POR LA PERSONA LEGITIMADA PARA HACERLO, SE LE NOTIFICARÁ Y REQUERIRÁ PARA QUE LO HAGA EN EL PLAZO DE:', 'TREINTA DÍAS.', 'ART. 5', '184579'),
    (1744, 'SUB-1744', 'SBM3', 'SEGÚN LA CUESTIÓN PREJUDICIAL, EL FISCAL ESTÁ AUTORIZADO PARA INTERVENIR Y CONTINUAR EL PROCESO HASTA SU TERMINACIÓN, ASÍ COMO SUSTITUIR AL TITULAR DE LA ACCIÓN SI ÉSTE:', 'NO LO PROSIGUE', 'ART. 5', '184580'),
    (1745, 'SUB-1745', 'SBM3', '¿DE QUÉ DEPENDE LA PROSECUCIÓN O EL SOBRESEIMIENTO DEFINITIVO DE LA CAUSA?', 'DE LO RESUELTO EN LA VÍA EXTRA-PENAL', 'ART. 5', '184581'),
    (1746, 'SUB-1746', 'SBM3', 'UNA DE LAS EXCEPCIONES QUE PUEDE DEDUCIRSE, ES LA SIGUIENTE:', 'NATURALEZA DE JUICIO, CUANDO SE HA DADO AL PROCESO UNA SUSTANCIACIÓN DISTINTA A LA PREVISTA EN LA LEY', 'ART. 6', '184582'),
    (1747, 'SUB-1747', 'SBM3', 'UNA DE LAS EXCEPCIONES QUE PUEDE DEDUCIRSE, ES LA SIGUIENTE:', 'IMPROCEDENCIA DE ACCIÓN, CUANDO EL HECHO NO CONSTITUYE DELITO O NO ES JUSTICIABLE PENALMENTE', 'ART. 6', '184583'),
    (1748, 'SUB-1748', 'SBM3', 'UNA DE LAS EXCEPCIONES QUE PUEDE DEDUCIRSE, ES LA SIGUIENTE:', 'COSA JUZGADA, CUANDO EL HECHO PUNIBLE HA SIDO OBJETO DE UNA RESOLUCIÓN FIRME', 'ART. 6', '184584'),
    (1749, 'SUB-1749', 'SBM3', 'UNA DE LAS EXCEPCIONES QUE PUEDE DEDUCIRSE, ES LA SIGUIENTE:', 'AMNISTÍA', 'ART. 6', '184585'),
    (1750, 'SUB-1750', 'SBM3', 'UNA DE LAS EXCEPCIONES QUE PUEDE DEDUCIRSE, ES LA SIGUIENTE:', 'PRESCRIPCIÓN', 'ART. 6', '184586'),
    (1751, 'SUB-1751', 'SBM3', 'EN CASO QUE SE DECLARE FUNDADA LA EXCEPCIÓN DE NATURALEZA DE JUICIO, EL PROCESO SE ADECUARÁ AL TRÁMITE RECONOCIDO EN EL:', 'AUTO QUE LA RESUELVA', 'ART. 6', '184587'),
    (1752, 'SUB-1752', 'SBM3', 'LA CUESTIÓN PREVIA, CUESTIÓN PREJUDICIAL Y LAS EXCEPCIONES SE PLANTEAN UNA VEZ QUE EL FISCAL HAYA DECIDIDO CONTINUAR CON LAS INVESTIGACIONES PREPARATORIAS O:', 'AL CONTESTAR LA QUERELLA ANTE EL JUEZ', 'ART. 7', '184588'),
    (1753, 'SUB-1753', 'SBM3', 'LA CUESTIÓN PREVIA Y LAS EXCEPCIONES TAMBIÉN SE PUEDEN DEDUCIR DURANTE LA:', 'ETAPA INTERMEDIA', 'ART. 7', '184589'),
    (1754, 'SUB-1754', 'SBM3', 'LOS MEDIOS DE DEFENSA REFERIDOS EN ESTE DISPOSITIVO, PUEDEN SER DECLARADOS DE:', 'OFICIO', 'ART. 7', '184590'),
    (1755, 'SUB-1755', 'SBM3', 'LA CUESTIÓN PREVIA, CUESTIÓN PREJUDICIAL Y LAS EXCEPCIONES QUE SE DEDUZCAN DURANTE LA INVESTIGACIÓN PREPARATORIA SERÁN PLANTEADAS MEDIANTE:', 'SOLICITUD DEBIDAMENTE FUNDAMENTADA', 'ART. 8', '184591'),
    (1756, 'SUB-1756', 'SBM3', 'EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA, UNA VEZ QUE HA RECABADO INFORMACIÓN DEL FISCAL ACERCA DE LOS SUJETOS PROCESALES APERSONADOS EN LA CAUSA Y LUEGO DE NOTIFICARLES LA ADMISIÓN DEL MEDIO DE DEFENSA DEDUCIDO, DENTRO DEL TERCER DÍA SEÑALARÁ FECHA PARA:', 'LA REALIZACIÓN DE LA AUDIENCIA', 'ART. 8', '184592'),
    (1757, 'SUB-1757', 'SBM3', 'EL FISCAL ASISTIRÁ OBLIGATORIAMENTE Y EXHIBIRÁ EL EXPEDIENTE FISCAL PARA SU EXAMEN INMEDIATO POR EL:', 'JUEZ EN ESE ACTO', 'ART. 8', '184593'),
    (1758, 'SUB-1758', 'SBM3', 'INSTALADA LA AUDIENCIA, EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA ESCUCHARÁ POR SU ORDEN, AL ABOGADO DEFENSOR QUE PROPUSO EL:', 'MEDIO DE DEFENSA', 'ART. 8', '184594'),
    (1759, 'SUB-1759', 'SBM3', 'EN EL TURNO QUE LES CORRESPONDE, LOS PARTICIPANTES HARÁN MENCIÓN A LOS ELEMENTOS DE CONVICCIÓN QUE CONSTEN EN AUTOS O QUE HAN ACOMPAÑADO EN SEDE JUDICIAL. SI ASISTE EL IMPUTADO TIENE DERECHO A INTERVENIR EN:', 'ÚLTIMO TÉRMINO', 'ART. 8', '184595'),
    (1760, 'SUB-1760', 'SBM3', 'EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA RESOLVERÁ INMEDIATAMENTE O, EN TODO CASO, EN EL PLAZO DE DOS DÍAS LUEGO DE:', 'CELEBRADA LA VISTA', 'ART. 8', '184596'),
    (1761, 'SUB-1761', 'SBM3', 'EL JUEZ, EXCEPCIONALMENTE, Y HASTA POR VEINTICUATRO HORAS, PODRÁ RETENER EL EXPEDIENTE FISCAL PARA RESOLVER EL MEDIO DE DEFENSA DEDUCIDO, QUE SE HARÁ MEDIANTE:', 'AUTO DEBIDAMENTE FUNDAMENTADO', 'ART. 8', '184597'),
    (1762, 'SUB-1762', 'SBM3', 'LA CUESTIÓN PREVIA, CUESTIÓN PREJUDICIAL Y LAS EXCEPCIONES DEDUCIDAS A FAVOR DE UNO DE LOS IMPUTADOS BENEFICIA A LOS DEMÁS, SIEMPRE QUE SE ENCUENTREN EN:', 'IGUAL SITUACIÓN JURÍDICA', 'ART. 8', '184598'),
    (1763, 'SUB-1763', 'SBM3', 'CONTRA EL AUTO EXPEDIDO POR EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA PROCEDE:', 'RECURSO DE APELACIÓN', 'ART. 9', '184599'),
    (1764, 'SUB-1764', 'SBM3', 'CONCEDIDO EL RECURSO DE APELACIÓN, EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA DISPONDRÁ, ANTES DE LA ELEVACIÓN DEL RECURSO A LA SALA PENAL SUPERIOR, QUE DENTRO DEL QUINTO DÍA SE AGREGUEN A LOS ACTUADOS FORMADOS EN SEDE JUDICIAL LAS:', 'COPIAS CERTIFICADAS PERTINENTES DEL EXPEDIENTE FISCAL', 'ART. 9', '184600'),
    (1765, 'SUB-1765', 'SBM3', 'SI TRANSCURRE EL PLAZO SIN QUE SE HAYA AGREGADO LAS COPIAS CORRESPONDIENTES, EL JUEZ INMEDIATAMENTE ELEVARÁ LOS ACTUADOS A LA:', 'SALA PENAL SUPERIOR', 'ART. 9', '184601'),
    (1766, 'SUB-1766', 'SBM3', 'CUANDO EN LA SUSTANCIACIÓN DE UN PROCESO EXTRA-PENAL APAREZCAN INDICIOS DE LA COMISIÓN DE UN DELITO DE PERSECUCIÓN PÚBLICA EL JUEZ DE OFICIO O A PEDIDO DE PARTE, COMUNICARÁ AL MINISTERIO PÚBLICO PARA LOS:', 'FINES CONSIGUIENTES', 'ART. 10', '184602'),
    (1767, 'SUB-1767', 'SBM3', 'SI EL FISCAL LUEGO DE LAS PRIMERAS DILIGENCIAS DECIDE CONTINUAR CON LA INVESTIGACIÓN PREPARATORIA LO COMUNICARÁ AL JUEZ EXTRA PENAL, QUIEN:', 'SUSPENDERÁ EL PROCESO', 'ART. 10', '184603'),
    (1768, 'SUB-1768', 'SBM3', 'EL EJERCICIO DE LA ACCIÓN CIVIL DERIVADA DEL HECHO PUNIBLE CORRESPONDE AL:', 'MINISTERIO PÚBLICO', 'ART. 11', '184604'),
    (1769, 'SUB-1769', 'SBM3', 'EL PERJUDICADO POR EL DELITO PODRÁ EJERCER LA ACCIÓN CIVIL EN EL PROCESO PENAL O ANTE EL: Código Procesal Penal', 'ORDEN JURISDICCIONAL CIVIL', 'ART. 12', '184605'),
    (1770, 'SUB-1770', 'SBM3', 'SI LA PERSECUCIÓN PENAL NO PUDIESE PROSEGUIR, YA SEA QUE SE DISPONGA LA RESERVA DEL PROCESO O SE SUSPENDA POR ALGUNA CONSIDERACIÓN LEGAL, LA ACCIÓN CIVIL DERIVADA DEL HECHO PUNIBLE PODRÁ SER EJERCIDA ANTE EL:', 'ORDEN JURISDICCIONAL CIVIL', 'ART. 12', '184606'),
    (1771, 'SUB-1771', 'SBM3', 'LA SENTENCIA ABSOLUTORIA O EL AUTO DE SOBRESEIMIENTO NO IMPEDIRÁ AL ÓRGANO JURISDICCIONAL PRONUNCIARSE SOBRE LA:', 'ACCIÓN CIVIL DERIVADA DEL HECHO PUNIBLE', 'ART. 12', '184607'),
    (1772, 'SUB-1772', 'SBM3', 'HASTA CUÁNDO, EL ACTOR CIVIL PODRÁ DESISTIRSE DE SU PRETENSIÓN DE REPARACIÓN CIVIL:', 'ANTES DEL INICIO DE LA ETAPA INTERMEDIA DEL PROCESO', 'ART. 13', '184608'),
    (1773, 'SUB-1773', 'SBM3', 'DERECHO A LA DEFENSA TÉCNICA.- EL SERVICIO NACIONAL DE LA DEFENSA DE OFICIO, A CARGO DEL MINISTERIO DE JUSTICIA, PROVEERÁ:.', 'LA DEFENSA GRATUITA.', 'ART. 80', '184609'),
    (1774, 'SUB-1774', 'SBM3', 'EL DESISTIMIENTO DE SU PRETENSIÓN DE REPARACIÓN CIVIL, GENERA LA OBLIGACIÓN AL ACTOR CIVIL DEL:', 'PAGO DE COSTAS', 'ART. 13', '184610'),
    (1775, 'SUB-1775', 'SBM3', 'LA ACCIÓN CIVIL DERIVADA DEL HECHO PUNIBLE PODRÁ SER OBJETO DE: Código Procesal Penal', 'TRANSACCIÓN', 'ART. 14', '184611'),
    (1776, 'SUB-1776', 'SBM3', 'UNA VEZ QUE LA TRANSACCIÓN SE FORMALICE ANTE EL JUEZ DE LA INVESTIGACIÓN PREPARATORIA, RESPECTO DE LA CUAL NO SE PERMITE OPOSICIÓN DEL MINISTERIO PÚBLICO, EL FISCAL SE ABSTENDRÁ DE:', 'SOLICITAR REPARACIÓN CIVIL EN SU ACUSACIÓN', 'ART. 14', '184612'),
    (1777, 'SUB-1777', 'SBM3', 'DEFENSA CONJUNTA.-SI CONCURREN VARIOS ABOGADOS ASOCIADOS A LAS DILIGENCIAS:.', 'UNO SOLO EJERCERÁ LA DEFENSA.', 'ART. 82', '184613'),
    (1778, 'SUB-1778', 'SBM3', 'EL MINISTERIO PÚBLICO O EL ACTOR CIVIL, INTRODUCIRÁN MOTIVADAMENTE LA PRETENSIÓN ANULATORIA CORRESPONDIENTE E INSTARÁ AL JUEZ DE LA INVESTIGACIÓN PREPARATORIA QUE DISPONGA AL FISCAL LA FORMACIÓN DEL:', 'CUADERNO DE NULIDAD DE TRANSFERENCIA', 'ART. 15', '184614'),
    (1779, 'SUB-1779', 'SBM3', 'EFECTOS DE LA NOTIFICACIÓN.- LA NOTIFICACIÓN EFECTUADA POR ORDEN DEL FISCAL O DEL JUEZ, EN EL DOMICILIO PROCESAL SEÑALADO EN AUTOS POR EL ESTUDIO ASOCIADO, COMPRENDERÁ A:.', 'TODOS Y CADA UNO DE LOS ABOGADOS QUE PARTICIPAN EN LA DEFENSA.', 'ART. 83', '184615'),
    (1780, 'SUB-1780', 'SBM3', 'EL JUEZ CORRERÁ TRASLADO DEL REQUERIMIENTO DE NULIDAD AL IMPUTADO, AL ADQUIRENTE Y/O POSEEDOR DEL BIEN CUESTIONADO O A:', 'AQUÉL EN CUYO FAVOR SE GRAVÓ EL BIEN', 'ART. 15', '184616'),
    (1781, 'SUB-1781', 'SBM3', 'EL JUEZ, ABSUELTO EL TRÁMITE O TRANSCURRIDO EL PLAZO RESPECTIVO, DE SER EL CASO, CITARÁ A UNA AUDIENCIA DENTRO DEL QUINTO DÍA PARA LA ACTUACIÓN DE LAS PRUEBAS OFRECIDAS Y ESCUCHAR LOS:', 'ALEGATOS DE LOS PARTICIPANTES', 'ART. 15', '184617'),
    (1782, 'SUB-1782', 'SBM3', 'A SU CULMINACIÓN, CON LAS CONCLUSIONES ESCRITAS DE LAS PARTES, EL JUEZ DICTARÁ RESOLUCIÓN DANDO POR CONCLUIDO EL:', 'PROCEDIMIENTO INCIDENTAL', 'ART. 15', '184618'),
    (1783, 'SUB-1783', 'SBM3', 'EL ÓRGANO JURISDICCIONAL COMPETENTE PARA DICTAR SENTENCIA SE PRONUNCIARÁ SOBRE LA:', 'NULIDAD DEMANDADA', 'ART. 15', '184619'),
    (1784, 'SUB-1784', 'SBM3', 'TODOS LOS LEGITIMADOS PARA INTERVENIR EN ESTE INCIDENTE PUEDEN PARTICIPAR EN TODAS LAS ACTUACIONES PROCESALES QUE PUEDAN AFECTAR SU DERECHO Y, ESPECIALMENTE, EN:', 'EL JUICIO ORAL', 'ART. 15', '184620'),
    (1785, 'SUB-1785', 'SBM3', 'SEGÚN LA NULIDAD DE TRANSFERENCIA, ESTA PRETENSIÓN TAMBIÉN PUEDE INTERPONERSE DURANTE LA ETAPA INTERMEDIA, EN QUÉ MOMENTO:', 'EN EL FIJADO POR LA LEY', 'ART. 15', '184621'),
    (1786, 'SUB-1786', 'SBM3', 'SI EL ABOGADO DEFENSOR NO ASISTE INJUSTIFICADAMENTE A LA DILIGENCIA PARA LA QUE ES CITADO, Y ÉSTA NO TIENE EL CARÁCTER DE INAPLAZABLE, EL PROCESADO SERÁ REQUERIDO PARA QUE EN EL TÉRMINO DE:.', '24 HORAS DESIGNE AL REEMPLAZANTE.', 'ART. 85. Num. 2 Código Procesal Penal', '184622'),
    (1787, 'SUB-1787', 'SBM3', 'LA POTESTAD JURISDICCIONAL DEL ESTADO EN MATERIA PENAL SE EJERCE POR:', 'LA SALA PENAL DE LA CORTE SUPREMA', 'ART. 16', '184623'),
    (1788, 'SUB-1788', 'SBM3', 'LA POTESTAD JURISDICCIONAL DEL ESTADO EN MATERIA PENAL SE EJERCE POR:', 'LAS SALAS PENALES DE LAS CORTES SUPERIORES', 'ART. 16', '184624'),
    (1789, 'SUB-1789', 'SBM3', 'LA DECLARACION DEL IMPUTADO.- LAS AMPLIACIONES DE DECLARACIÓN PROCEDERÁN SI FUEREN PERTINENTES Y NO APAREZCAN SÓLO COMO UN PROCEDIMIENTO DILATORIO O:.', 'MALICIOSO', 'ART. 86. Num. 1', '184625'),
    (1790, 'SUB-1790', 'SBM3', 'LA POTESTAD JURISDICCIONAL DEL ESTADO EN MATERIA PENAL SE EJERCE POR:', 'LOS JUZGADOS PENALES, CONSTITUIDOS EN ÓRGANOS COLEGIADOS O UNIPERSONALES', 'ART. 16', '184626'),
    (1791, 'SUB-1791', 'SBM3', 'LA POTESTAD JURISDICCIONAL DEL ESTADO EN MATERIA PENAL SE EJERCE POR:', 'LOS JUZGADOS DE LA INVESTIGACIÓN PREPARATORIA', 'ART. 16', '184627'),
    (1792, 'SUB-1792', 'SBM3', 'LA POTESTAD JURISDICCIONAL DEL ESTADO EN MATERIA PENAL SE EJERCE POR:', 'LOS JUZGADOS DE PAZ LETRADOS', 'ART. 16', '184628'),
    (1793, 'SUB-1793', 'SBM3', 'INSTRUCCIONES PRELIMINARES.- EL IMPUTADO TAMBIÉN SERÁ INFORMADO DE QUE PUEDE SOLICITAR LA ACTUACIÓN DE MEDIOS DE INVESTIGACIÓN O DE PRUEBA, ASÍ COMO A DICTAR SU DECLARACIÓN DURANTE:. Código Procesal Penal', 'LA ETAPA DE INVESTIGACIÓN PREPARATORIA.', 'ART. 87. Num. 3', '184629'),
    (1794, 'SUB-1794', 'SBM3', 'LA JURISDICCIÓN PENAL ORDINARIA ES:', 'IMPRORROGABLE', 'ART. 17', '184630'),
    (1795, 'SUB-1795', 'SBM3', 'LA JURISDICCIÓN PENAL ORDINARIA, TIENE LUGAR SEGÚN LOS CRITERIOS DE APLICACIÓN ESTABLECIDOS EN EL CÓDIGO PENAL Y EN LOS:', 'TRATADOS INTERNACIONALES', 'ART. 17', '184631'),
    (1796, 'SUB-1796', 'SBM3', 'LA JURISDICCIÓN PENAL ORDINARIA NO ES COMPETENTE PARA CONOCER:', 'DE LOS DELITOS PREVISTOS EN EL ARTÍCULO 173 DE LA CONSTITUCIÓN', 'ART. 18', '184632'),
    (1797, 'SUB-1797', 'SBM3', 'LA JURISDICCIÓN PENAL ORDINARIA NO ES COMPETENTE PARA CONOCER:', 'DE LOS HECHOS PUNIBLES COMETIDOS POR ADOLESCENTES', 'ART. 18', '184633'),
    (1798, 'SUB-1798', 'SBM3', 'LA JURISDICCIÓN PENAL ORDINARIA NO ES COMPETENTE PARA CONOCER:', 'DE LOS HECHOS PUNIBLES EN LOS CASOS PREVISTOS EN EL ARTÍCULO 149 DE LA CONSTITUCIÓN', 'ART. 18', '184634'),
    (1799, 'SUB-1799', 'SBM3', '¿EN QUÉ CASO PROCEDE EL RECURSO DE REPOSICIÓN?', 'CONTRA LOS DECRETOS', 'ART. 415', '184635'),
    (1800, 'SUB-1800', 'SBM3', 'LA COMPETENCIA ES OBJETIVA, FUNCIONAL, TERRITORIAL Y:', 'POR CONEXIÓN', 'ART. 19', '184636')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

