  VALUES
    ('SUB-2701', 'A', 'SOLAMENTE UNA VEZ EMITIDO EL INFORME PERICIAL OFICIAL POR UN ÚNICO PERITO Y ANTES QUE SEA REMITIDO AL JUEZ, EN VIRTUD DEL PRINCIPIO DE ECONOMÍA PROCESAL.', FALSE, 1),
