    ('SUB-2711', 'E', 'EL TIPO DE RESIDENCIA FISCAL DE LA PERSONA INVESTIGADA EN EL EXTRANJERO.', FALSE, 5),
    ('SUB-2712', 'A', 'LA INTERVENCIÓN PUEDE DURAR HASTA NOVENTA DÍAS Y SER PRORROGADA UNA VEZ MÁS POR IGUAL PLAZO SIN MAYORES REQUISITOS. Ley 32130 - Modifica Código Procesal Penal para fortalecer la investigación del delito como función de la Policía', FALSE, 1),
    ('SUB-2712', 'B', 'LA INTERVENCIÓN NO TIENE UN PLAZO DEFINIDO Y PUEDE MANTENERSE VIGENTE HASTA QUE EL FISCAL LO CONSIDERE NECESARIO.', FALSE, 2),
    ('SUB-2712', 'C', 'EL PLAZO MÁXIMO ES DE SESENTA DÍAS, PRORROGABLE POR ÚNICA VEZ POR IGUAL PLAZO, PREVIA SUSTENTACIÓN FISCAL Y DECISIÓN MOTIVADA DEL JUEZ, SOLO SUSTENTADA EN NUEVOS Y SUFICIENTES ELEMENTOS PROBATORIOS.', TRUE, 3),
    ('SUB-2712', 'D', 'LA INTERVENCIÓN ÚNICAMENTE PUEDE DURAR QUINCE DÍAS, PRORROGABLE ILIMITADAMENTE CON AUTORIZACIÓN JUDICIAL SIMPLE.', FALSE, 4),
    ('SUB-2712', 'E', 'LA INTERVENCIÓN PUEDE SER PRORROGADA CUANTAS VECES LO SOLICITE LA POLICÍA, MIENTRAS LO SUSTENTE ORALMENTE EN AUDIENCIA PÚBLICA.', FALSE, 5),
    ('SUB-2713', 'A', 'LA SOLA CONCLUSIÓN DE QUE LOS RESULTADOS INICIALES FUERON INSUFICIENTES, SIN NUEVOS ELEMENTOS PROBATORIOS.', FALSE, 1),
    ('SUB-2713', 'B', 'LA EXISTENCIA DE NUEVOS APORTES Y SUFICIENTES ELEMENTOS PROBATORIOS QUE LA JUSTIFIQUEN.', TRUE, 2),
    ('SUB-2713', 'C', 'EL DESEO DE AMPLIAR LA INVESTIGACIÓN PARA CUBRIR HECHOS FUTUROS DESCONOCIDOS.', FALSE, 3),
